CREATE OR REPLACE FUNCTION neuvetra.create_annual_inventory_v2(target_company_id uuid, target_register_id uuid, inventory_id uuid, audit_id uuid, request_payload_json text, request_snapshot_sha256 text, request_idempotency_key uuid, request_operation_fingerprint text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'neuvetra', 'pg_temp'
AS $function$
declare actor_id uuid := neuvetra.current_user_id(); stored_id uuid; reg record; payload jsonb := request_payload_json::jsonb;
begin
  if actor_id is null or not neuvetra.can_manage_company(target_company_id) then raise exception 'workspace not found' using errcode='42501'; end if;
  select * into reg from neuvetra.annual_source_register_versions where company_id=target_company_id and id=target_register_id and version=2 and status='resolved_with_exceptions' for update;
  if reg.id is null then raise exception 'resolved register required' using errcode='22023'; end if;
  if payload - 'snapshotSha256' is distinct from jsonb_build_object(
    'id',inventory_id,'companyId',target_company_id,'boundaryId',reg.boundary_id,'previousInventoryVersionId',reg.previous_inventory_version_id,'registerId',reg.id,'registerSnapshotSha256',reg.snapshot_sha256,
    'version',2,'reportingYear',2023,'scope','scope_2_location_based','periodResolution','resolved_with_exceptions','overallInventoryCompleteness','incomplete','releaseEligible',false,
    'counts',(reg.payload_json::jsonb)->'counts','totals',(reg.payload_json::jsonb)->'totals',
    'warnings',jsonb_build_array('one_period_estimated','one_period_excluded','market_based_scope2_not_included','factor_and_method_not_released','scope_1_and_scope_3_not_assessed','synthetic_local_only_no_assurance')
  ) then raise exception 'inventory contract mismatch' using errcode='22023'; end if;
  if jsonb_typeof(payload) is distinct from 'object' or (select count(*) from jsonb_object_keys(payload)) is distinct from 16::bigint or payload->>'id' is distinct from inventory_id::text or payload->>'companyId' is distinct from target_company_id::text or payload->>'boundaryId' is distinct from reg.boundary_id::text or payload->>'previousInventoryVersionId' is distinct from reg.previous_inventory_version_id::text
    or payload->>'registerId' is distinct from reg.id::text or payload->>'registerSnapshotSha256' is distinct from reg.snapshot_sha256 or payload->>'version' is distinct from '2' or payload->>'reportingYear' is distinct from '2023' or payload->>'scope' is distinct from 'scope_2_location_based'
    or payload->>'periodResolution' is distinct from 'resolved_with_exceptions' or payload->>'overallInventoryCompleteness' is distinct from 'incomplete' or payload->>'releaseEligible' is distinct from 'false' or payload->>'snapshotSha256' is distinct from request_snapshot_sha256
    or payload#>>'{counts,resolved}' is distinct from '12' or payload#>>'{counts,reported}' is distinct from '10' or payload#>>'{counts,estimated}' is distinct from '1' or payload#>>'{counts,excluded}' is distinct from '1' or payload#>>'{counts,missing}' is distinct from '0' or payload#>>'{counts,calculationBearing}' is distinct from '11'
    or payload#>>'{totals,includedMwh}' is distinct from '139.281000' or payload#>>'{totals,includedKgCo2e}' is distinct from '27165.4064643528' or payload#>>'{totals,includedDisplayKgCo2e}' is distinct from '27165.4065'
    or payload->'warnings' is distinct from jsonb_build_array('one_period_estimated','one_period_excluded','market_based_scope2_not_included','factor_and_method_not_released','scope_1_and_scope_3_not_assessed','synthetic_local_only_no_assurance')
  then raise exception 'inventory contract mismatch' using errcode='22023'; end if;
  insert into neuvetra.annual_inventory_versions values
    (inventory_id,target_company_id,reg.boundary_id,reg.previous_inventory_version_id,reg.id,2,request_payload_json,request_snapshot_sha256,request_idempotency_key,request_operation_fingerprint,actor_id,now())
    on conflict (company_id,boundary_id,version) do nothing returning id into stored_id;
  if stored_id is null then select id into stored_id from neuvetra.annual_inventory_versions where company_id=target_company_id and boundary_id=reg.boundary_id and version=2 and register_version_id=reg.id; end if;
  if stored_id is null then raise exception 'inventory conflict' using errcode='23505'; end if;
  insert into neuvetra.annual_inventory_audit_log values(audit_id,target_company_id,actor_id,'annual_inventory.created',stored_id,jsonb_build_object('version',2,'snapshot_sha256',request_snapshot_sha256),now()) on conflict do nothing;
  return stored_id;
end $function$

CREATE OR REPLACE FUNCTION neuvetra.create_company_workspace(company_id uuid, company_name text, facility_id uuid, facility_name text, boundary_id uuid, reporting_year integer, audit_event_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'neuvetra', 'pg_temp'
AS $function$
declare
  actor_id uuid := neuvetra.current_user_id();
begin
  if actor_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  insert into neuvetra.companies (id, name, country_code, state_code, created_by)
  values (company_id, btrim(company_name), 'US', 'CA', actor_id);
  insert into neuvetra.company_members (company_id, user_id, role)
  values (company_id, actor_id, 'owner');
  insert into neuvetra.facilities (id, company_id, name, country_code, state_code, egrid_subregion)
  values (facility_id, company_id, btrim(facility_name), 'US', 'CA', 'CAMX');
  insert into neuvetra.reporting_boundaries (id, company_id, reporting_year, approach)
  values (boundary_id, company_id, reporting_year, 'operational_control');
  insert into neuvetra.boundary_facilities (company_id, boundary_id, facility_id)
  values (company_id, boundary_id, facility_id);
  insert into neuvetra.audit_events (id, company_id, actor_user_id, event_type, subject_id, event_data)
  values (audit_event_id, company_id, actor_id, 'workspace.created', company_id,
    jsonb_build_object('boundary_id', boundary_id, 'facility_id', facility_id, 'version', 1));
  return company_id;
end
$function$

CREATE OR REPLACE FUNCTION neuvetra.create_fugitive_report(target_company uuid, target_stream uuid, family text, request jsonb, p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
#variable_conflict use_column
declare actor uuid:=auth.uid();v jsonb;r jsonb;cv jsonb;works jsonb;deps jsonb;snapshot jsonb;expected jsonb;old record;fingerprint text;begin if not neuvetra.m77_lock(target_company,true)then raise exception 'forbidden'using errcode='42501';end if;perform neuvetra.m71_keys(request,'versionId,expectedVersionSha256,expectedDecisionId,expectedDecisionSha256,expectedReconciliationSha256,idempotencyKey');perform neuvetra.m71_keys(p,'id,companyId,streamId,family,versionId,versionSha256,createdBy,createdAt,rendererVersion,snapshotJson,snapshotSha256,html,htmlSha256,htmlByteLength,reportSha256');fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','report','actor',actor,'companyId',target_company,'family',family,'streamId',target_stream,'request',request-'idempotencyKey'));select * into old from neuvetra.fugitive_requests where company_id=target_company and idempotency_key=((request->>'idempotencyKey'))::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'report'or old.actor_id<>actor then raise exception 'idempotency conflict'using errcode='23505';end if;return old.record_id;end if;
select vv.payload into v from neuvetra.fugitive_versions vv join neuvetra.fugitive_heads h on h.id=vv.stream_id and h.company_id=vv.company_id where vv.company_id=target_company and h.id=target_stream and h.family=create_fugitive_report.family and vv.id=((request->>'versionId'))::uuid;if v is null or (v->>'versionSha256')is distinct from (request->>'expectedVersionSha256') then raise exception 'report version changed'using errcode='23505';end if;cv:=neuvetra.m77_current_coverage(target_company);works:=neuvetra.m77_current_workpapers(target_company);deps:=neuvetra.m77_dependencies(cv,works);select rr.payload into r from neuvetra.fugitive_reviews rr where rr.company_id=target_company and rr.version_id=((v->>'id'))::uuid and(case when family='source'then true else (rr.payload#>>'{dependencies,dependencySha256}')=(deps->>'dependencySha256')end);if (request->'expectedDecisionId')is distinct from coalesce((r->'id'),'null'::jsonb)or (request->'expectedDecisionSha256')is distinct from coalesce((r->'decisionSha256'),'null'::jsonb)then raise exception 'report review changed'using errcode='23505';end if;
if family='population'and not exists(select 1 from neuvetra.fugitive_heads h where h.company_id=target_company and h.id=target_stream and h.version_id=((v->>'id'))::uuid)then raise exception 'report population head changed'using errcode='23505';end if;
expected:=jsonb_build_object('profile','m77-report-snapshot-v1','version',v,'review',r,'reconciliation',case when family='population'then neuvetra.m77_reconciliation(target_company,cv,works,v,r)else null end,'proof',case when family='population'then jsonb_build_object('coverageVersion',cv,'workpaperVersions',works)else null end,'limitations','["synthetic_only","declared_fugitive_reconciliation_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","no_emissions_aggregation","requirements_not_determined","no_external_assurance"]'::jsonb);snapshot:=((p->>'snapshotJson'))::jsonb;
if (request->'expectedReconciliationSha256')is distinct from coalesce((expected#>'{reconciliation,contentSha256}'),'null'::jsonb)then raise exception 'reconciliation changed'using errcode='23505';end if;if snapshot is distinct from expected or (p->>'snapshotJson')is distinct from neuvetra.m67_canonical(expected)or (p->>'html')is distinct from neuvetra.m77_render_report(expected)or (p->>'snapshotSha256')is distinct from encode(sha256(convert_to((p->>'snapshotJson'),'utf8')),'hex')or (p->>'htmlSha256')is distinct from encode(sha256(convert_to((p->>'html'),'utf8')),'hex')or (p->'htmlByteLength')is distinct from to_jsonb(octet_length(convert_to((p->>'html'),'utf8')))or (p->>'reportSha256')is distinct from neuvetra.m67_hash(p-array['html','snapshotJson','reportSha256'])or (p->>'companyId')is distinct from target_company::text or (p->>'streamId')is distinct from target_stream::text or (p->>'family')is distinct from family or (p->'versionId')is distinct from (v->'id')or (p->'versionSha256')is distinct from (v->'versionSha256')or (p->>'createdBy')is distinct from actor::text or (p->>'rendererVersion')is distinct from 'm77-retained-report-v1'or abs(extract(epoch from(clock_timestamp()-((p->>'createdAt'))::timestamptz)))>300 then raise exception 'report semantic integrity'using errcode='22023';end if;
