 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare actor uuid:=auth.uid();v record;decision record;old record;new_id uuid:=gen_random_uuid();captured timestamptz;fingerprint text;snapshot jsonb;snapshot_text text;html text;body jsonb;digest text;begin
