insert into neuvetra.stationary_gas_reports values(new_id,target_company,target_worksheet,v.id,decision.id,body,digest,actor,captured);insert into neuvetra.stationary_gas_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'report',fingerprint,new_id);insert into neuvetra.stationary_gas_audit values(gen_random_uuid(),target_company,new_id,'report',digest,actor,captured);return new_id;end $function$

CREATE OR REPLACE FUNCTION neuvetra.create_synthetic_scope2_inventory(target_company_id uuid, target_calculation_id uuid, inventory_id uuid, audit_id uuid, request_idempotency_key uuid, request_operation_fingerprint text, request_snapshot_sha256 text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'neuvetra', 'pg_temp'
AS $function$
declare actor_id uuid := neuvetra.current_user_id(); stored_id uuid; linked record;
begin
  if actor_id is null then raise exception 'authentication required' using errcode = '42501'; end if;
  if not neuvetra.can_manage_company(target_company_id) then raise exception 'workspace not found' using errcode = '42501'; end if;
  if request_operation_fingerprint !~ '^[0-9a-f]{64}$' or request_snapshot_sha256 !~ '^[0-9a-f]{64}$' then raise exception 'inventory contract mismatch' using errcode = '22023'; end if;
  select c.boundary_id, c.result_payload_sha256 into linked
    from neuvetra.inventory_calculation_results c
    join neuvetra.reporting_boundaries b on b.id = c.boundary_id and b.company_id = c.company_id
    where c.company_id = target_company_id and c.id = target_calculation_id
      and c.status = 'draft' and c.release_eligible = false and c.classification = 'development_candidate'
      and c.source_quantity_kwh = 12346.000 and c.normalized_quantity_mwh = 12.346000
      and c.unrounded_kg_co2e = 2407.9674055248 and c.display_kg_co2e = 2407.9674
      and b.reporting_year = 2023 and b.status = 'draft' and b.version = 1
    for update of c, b;
  if linked.boundary_id is null then raise exception 'calculation not found' using errcode = '42501'; end if;

  insert into neuvetra.inventory_versions (
    id, company_id, boundary_id, calculation_id, version, reporting_year, scope, status,
    expected_facilities, covered_facilities, expected_periods, covered_periods, covered_months, missing_months,
    complete, factor_release_eligible, warning_codes, calculation_result_sha256, snapshot_sha256,
    idempotency_key, operation_fingerprint, submitted_by
  ) values (
    inventory_id, target_company_id, linked.boundary_id, target_calculation_id, 1, 2023, 'scope_2_location_based', 'in_review',
    1, 1, 12, 1, array['2023-01'], array['2023-02','2023-03','2023-04','2023-05','2023-06','2023-07','2023-08','2023-09','2023-10','2023-11','2023-12'],
    false, false, array['annual_coverage_incomplete_1_of_12_months','market_based_scope2_not_included','factor_and_method_not_released','synthetic_local_only_no_assurance'], linked.result_payload_sha256, request_snapshot_sha256,
    request_idempotency_key, request_operation_fingerprint, actor_id
  ) on conflict (company_id, boundary_id, version) do nothing returning id into stored_id;
  if stored_id is null then
    select id into stored_id from neuvetra.inventory_versions where company_id = target_company_id and boundary_id = linked.boundary_id and version = 1
      and calculation_id = target_calculation_id and calculation_result_sha256 = linked.result_payload_sha256 and snapshot_sha256 = request_snapshot_sha256
      and operation_fingerprint = request_operation_fingerprint;
    if stored_id is null then raise exception 'inventory conflict' using errcode = '23505'; end if;
    return stored_id;
  end if;
  insert into neuvetra.inventory_review_audit_log values (
    audit_id, target_company_id, actor_id, 'inventory.version.created', stored_id,
    jsonb_build_object('version', 1, 'complete', false, 'factor_release_eligible', false, 'snapshot_sha256', request_snapshot_sha256), now()
  );
  return stored_id;
end $function$

CREATE OR REPLACE FUNCTION neuvetra.create_worksheet_report(target_company uuid, request jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
declare actor uuid:=neuvetra.current_user_id(); v record; r record; prior record; source jsonb; report_id uuid; fingerprint text;
 template_sha text:=encode(sha256(convert_to(neuvetra.worksheet_report_template(),'utf8')),'hex'); captured timestamptz; captured_text text; content bytea; content_sha text; meta jsonb;
begin
 if actor is null or not neuvetra.can_manage_company(target_company) then raise exception 'workspace not found' using errcode='42501';end if;
 perform id from neuvetra.companies where id=target_company for update;
 if jsonb_typeof(request) is distinct from 'object' or (select array_agg(key order by key) from jsonb_object_keys(request) key) is distinct from array['expectedInputSha256','expectedResultSha256','expectedReviewId','expectedReviewSha256','idempotencyKey','sourceVersionId']::text[] then raise exception 'invalid report request' using errcode='22023';end if;
 if exists(select 1 from jsonb_each(request) where key not in('expectedReviewId','expectedReviewSha256') and jsonb_typeof(value)<>'string') or request->>'sourceVersionId' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'idempotencyKey' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'expectedInputSha256' !~ '^[0-9a-f]{64}$' or request->>'expectedResultSha256' !~ '^[0-9a-f]{64}$' then raise exception 'invalid report request' using errcode='22023';end if;
 if not ((request->'expectedReviewId'='null'::jsonb and request->'expectedReviewSha256'='null'::jsonb) or (jsonb_typeof(request->'expectedReviewId')='string' and jsonb_typeof(request->'expectedReviewSha256')='string' and request->>'expectedReviewId' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' and request->>'expectedReviewSha256' ~ '^[0-9a-f]{64}$')) then raise exception 'invalid review binding' using errcode='22023';end if;
 select * into v from neuvetra.electricity_worksheet_versions where company_id=target_company and id=(request->>'sourceVersionId')::uuid;
 if not found or v.input_sha256 is distinct from request->>'expectedInputSha256' or v.result_sha256 is distinct from request->>'expectedResultSha256' then raise exception 'report source conflicts' using errcode='23505';end if;
 fingerprint:=encode(sha256(convert_to(concat_ws(E'\n','neuvetra.synthetic.worksheet-report.v1',target_company::text,v.id::text,v.input_sha256,v.result_sha256,coalesce(request->>'expectedReviewId','<none>'),coalesce(request->>'expectedReviewSha256','<none>'),'m65-january-camx-report-v1',template_sha),'utf8')),'hex');
 select * into prior from neuvetra.worksheet_report_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;
 if found then
  if prior.operation_fingerprint<>fingerprint then raise exception 'report request conflicts' using errcode='23505';end if;
  return prior.report_id;
 end if;
 select id into report_id from neuvetra.worksheet_reports where company_id=target_company and operation_fingerprint=fingerprint;
 if found then
  insert into neuvetra.worksheet_report_requests values(target_company,(request->>'idempotencyKey')::uuid,fingerprint,report_id,actor);
  return report_id;
 end if;
 select * into r from neuvetra.electricity_worksheet_reviews where company_id=target_company and version_id=v.id;
 if r.id is distinct from (request->>'expectedReviewId')::uuid or r.decision_sha256 is distinct from request->>'expectedReviewSha256' then raise exception 'report review snapshot changed' using errcode='23505';end if;
 source:=v.payload||jsonb_build_object('createdAt',to_char(v.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'review',case when r.id is null then 'null'::jsonb else r.payload||jsonb_build_object('reviewedAt',to_char(r.reviewed_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) end);
 report_id:=gen_random_uuid();captured:=date_trunc('milliseconds',clock_timestamp());captured_text:=to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
 content:=neuvetra.render_worksheet_report(report_id,target_company,actor,captured_text,source,fingerprint);
 content_sha:=encode(sha256(content),'hex');
 insert into neuvetra.worksheet_reports values(report_id,target_company,v.id,v.input_sha256,v.result_sha256,r.id,r.decision_sha256,'m65-january-camx-report-v1',template_sha,source,content,content_sha,octet_length(content),fingerprint,actor,captured);
 insert into neuvetra.worksheet_report_requests values(target_company,(request->>'idempotencyKey')::uuid,fingerprint,report_id,actor);
 meta:=jsonb_build_object('profile','neuvetra.synthetic.worksheet-report.v1','reportId',report_id,'sourceVersionId',v.id,'inputSha256',v.input_sha256,'resultSha256',v.result_sha256,'reviewId',r.id,'reviewSha256',r.decision_sha256,'templateVersion','m65-january-camx-report-v1','templateSha256',template_sha,'reportSha256',content_sha,'reportByteLength',octet_length(content),'identitySha256',fingerprint);
 insert into neuvetra.worksheet_report_audit values(gen_random_uuid(),target_company,report_id,actor,meta,captured);
 return report_id;
end $function$

CREATE OR REPLACE FUNCTION neuvetra.link_synthetic_bill(target_company_id uuid, target_boundary_id uuid, target_facility_id uuid, bill_version_id uuid, activity_id uuid, log_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'neuvetra', 'pg_temp'
AS $function$
declare actor_id uuid := neuvetra.current_user_id(); stored_activity_id uuid;
begin
  if actor_id is null then raise exception 'authentication required' using errcode = '42501'; end if;
  if not neuvetra.can_manage_company(target_company_id) then raise exception 'workspace not found' using errcode = '42501'; end if;

  insert into neuvetra.inventory_activity_versions
    select activity_id, target_company_id, target_boundary_id, target_facility_id, reviewed.id, null, 1,
      12.346000, 'MWh', 'draft', actor_id, now()
    from neuvetra.bill_versions reviewed
    where reviewed.id = bill_version_id and reviewed.company_id = target_company_id and reviewed.facility_id = target_facility_id
      and reviewed.version = 2 and reviewed.service_period_start >= '2023-01-01' and reviewed.service_period_end <= '2023-12-31'
      and exists (
        select 1 from neuvetra.reporting_boundaries boundary_record
        join neuvetra.boundary_facilities included on included.company_id = boundary_record.company_id and included.boundary_id = boundary_record.id
        where boundary_record.id = target_boundary_id and boundary_record.company_id = target_company_id
          and boundary_record.reporting_year = 2023 and boundary_record.approach = 'operational_control'
          and boundary_record.status = 'draft' and boundary_record.version = 1
          and included.facility_id = target_facility_id and included.included = true
      )
    on conflict on constraint inventory_activity_versions_bill_version_id_key do nothing returning id into stored_activity_id;
  if stored_activity_id is null then
    select existing.id into stored_activity_id from neuvetra.inventory_activity_versions existing where existing.company_id = target_company_id and existing.bill_version_id = link_synthetic_bill.bill_version_id;
    if stored_activity_id is null then raise exception 'reviewed bill not found' using errcode = '42501'; end if;
    return stored_activity_id;
  end if;

  insert into neuvetra.evidence_audit_log values
    (log_id, target_company_id, actor_id, 'bill.linked', activity_id, jsonb_build_object('bill_version_id', bill_version_id), now());
  return stored_activity_id;
end
$function$

