CREATE OR REPLACE FUNCTION neuvetra.m67_calculate_months(input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
declare row jsonb; idx integer:=0; expected_month text; raw text; milli numeric; sum_milli numeric:=0; known integer:=0; months jsonb:='[]'::jsonb; missing jsonb:='[]'::jsonb; calculated jsonb;
begin
 if jsonb_typeof(input) is distinct from 'array' then raise exception 'invalid annual month array' using errcode='22023';end if;
 if jsonb_array_length(input)<>12 then raise exception 'invalid annual month count' using errcode='22023';end if;
 for row in select value from jsonb_array_elements(input) loop
  idx:=idx+1;expected_month:='2023-'||lpad(idx::text,2,'0');
  if jsonb_typeof(row) is distinct from 'object' then raise exception 'invalid annual month' using errcode='22023';end if;
  if (select array_agg(key order by key) from jsonb_object_keys(row) key) is distinct from array['month','quantityKwh']::text[] or row->>'month' is distinct from expected_month or jsonb_typeof(row->'month') is distinct from 'string' then raise exception 'invalid annual month' using errcode='22023';end if;
  if row->'quantityKwh'='null'::jsonb then
   months:=months||jsonb_build_array(jsonb_build_object('month',expected_month,'quantityKwh',null,'quantityMwh',null,'total',null));missing:=missing||jsonb_build_array(expected_month);
  else
   raw:=row->>'quantityKwh';
   if jsonb_typeof(row->'quantityKwh') is distinct from 'string' or char_length(raw)>11 or raw !~ '^(0|[1-9][0-9]{0,6})(\.[0-9]{1,3})?$' or raw ~ '[^0-9.]' then raise exception 'invalid annual quantity' using errcode='22023';end if;
   if raw::numeric>1000000 then raise exception 'invalid annual monthly limit' using errcode='22023';end if;
   milli:=raw::numeric*1000;sum_milli:=sum_milli+milli;known:=known+1;calculated:=neuvetra.m67_quantity(milli);
   months:=months||jsonb_build_array(calculated||jsonb_build_object('month',expected_month));
  end if;
 end loop;
 if known=0 or sum_milli>12000000000 then raise exception 'enter at least one annual month' using errcode='22023';end if;
 return neuvetra.m67_quantity(sum_milli)||jsonb_build_object('months',months,'coverage',jsonb_build_object('knownMonths',known,'missingMonths',missing,'electricityComplete',known=12));
end $function$

CREATE OR REPLACE FUNCTION neuvetra.m67_canonical(value jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
declare result text;
begin
 if jsonb_typeof(value)='object' then
  select '{'||coalesce(string_agg(to_json(key)::text||':'||neuvetra.m67_canonical(v),',' order by key collate "C"),'')||'}' into result from jsonb_each(value) as item(key,v);return result;
 elsif jsonb_typeof(value)='array' then
  select '['||coalesce(string_agg(neuvetra.m67_canonical(v),',' order by ord),'')||']' into result from jsonb_array_elements(value) with ordinality as item(v,ord);return result;
 end if;
 return value::text;
end $function$

CREATE OR REPLACE FUNCTION neuvetra.m67_quantity(milli numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
declare scaled numeric:=milli*1950402888; q numeric; rem numeric; exact_total text; display_total text;
begin
 exact_total:=rtrim(rtrim((scaled*0.0000000000001)::numeric(24,13)::text,'0'),'.');q:=div(scaled,1000000000);rem:=mod(scaled,1000000000);
 if rem>500000000 or (rem=500000000 and mod(q,2)=1) then q:=q+1;end if;
 display_total:=(q*0.0001)::numeric(16,4)::text;
 return jsonb_build_object('quantityKwh',(milli*0.001)::numeric(12,3)::text,'quantityMwh',(milli*0.000001)::numeric(12,6)::text,'total',jsonb_build_object('unrounded',exact_total,'display',display_total,'unit','kg CO2e','rounding','half_even_4dp'));
end $function$

CREATE OR REPLACE FUNCTION neuvetra.m71_findings(s jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
declare result jsonb:='[]';r jsonb;code text;begin
 result:=jsonb_build_array(jsonb_build_object('code','requirements_not_determined','recordId',null,'message','Corporate applicability and reporting requirements remain undetermined.'),jsonb_build_object('code','methods_not_released','recordId',null,'message','No corporate calculation method is released; emissions remain unknown.'));
 if s->>'consolidationApproach'<>'operational_control' then result:=result||jsonb_build_array(jsonb_build_object('code','unsupported_consolidation','recordId',null,'message','This consolidation approach requires a later reviewed method.'));end if;
 for r in select e from jsonb_array_elements((s->'entities')||(s->'facilities'))e loop
  if r->>'countryCode'<>'US' or r->>'regionCode' is distinct from 'CA' then result:=result||jsonb_build_array(jsonb_build_object('code','unsupported_geography','recordId',r->'id','message','Discovered operations remain registered; this milestone supports only California operations.'));end if;
  if r->>'start'<>'2025-01-01' or r->>'endExclusive'<>'2026-01-01' then result:=result||jsonb_build_array(jsonb_build_object('code','unsupported_temporal_allocation','recordId',r->'id','message','Partial-year control/operations need reviewed interval allocation.'));end if;
 end loop;
 for r in select e from jsonb_array_elements(s->'relationships')e loop
  if r->>'start'<>'2025-01-01' or r->>'endExclusive'<>'2026-01-01' or r->>'ownershipPercent' is distinct from '100' then result:=result||jsonb_build_array(jsonb_build_object('code','unsupported_boundary_relationship','recordId',r->'id','message','Partial-year or non-wholly-owned relationships need reviewed allocation.'));end if;
  if r->'controlFacts'='null'::jsonb or jsonb_array_length(r->'evidenceRefs')=0 then result:=result||jsonb_build_array(jsonb_build_object('code','control_evidence_missing','recordId',r->'id','message','Control facts and supporting evidence are incomplete.'));end if;
 end loop;
 for r in select e from jsonb_array_elements(s->'boundaryDecisions')e loop
  if r->>'disposition' in('missing','unassessed') then result:=result||jsonb_build_array(jsonb_build_object('code','boundary_unreconciled','recordId',r->'id','message','Expected entity remains unreconciled.'));end if;
  if r->>'disposition' in('excluded','not_applicable') then result:=result||jsonb_build_array(jsonb_build_object('code','boundary_assertion_unverified','recordId',r->'id','message','Boundary exclusion/non-applicability remains visible and requires qualified review.'));end if;
 end loop;
 for r in select e from jsonb_array_elements(s->'coverageItems')e loop
  if r->'quantity'='null'::jsonb then result:=result||jsonb_build_array(jsonb_build_object('code','activity_unknown','recordId',r->'id','message','No activity quantity is recorded; unknown is not zero.'));end if;
  if r->>'evidenceState'<>'linked' then code:=case when r->>'evidenceState'='conflicting' then 'evidence_conflicting' else 'evidence_incomplete' end;result:=result||jsonb_build_array(jsonb_build_object('code',code,'recordId',r->'id','message','Supporting evidence is missing, incomplete or conflicting.'));end if;
  if jsonb_array_length(r->'evidenceRefs')>0 then result:=result||jsonb_build_array(jsonb_build_object('code','synthetic_evidence_not_sufficient','recordId',r->'id','message','Pinned fictional evidence is not proof of activity or reporting sufficiency.'));end if;
  if r->>'methodReadiness'<>'candidate' then result:=result||jsonb_build_array(jsonb_build_object('code','method_unsupported','recordId',r->'id','message','This screening has no released calculation method.'));end if;
  if r->>'disposition' in('excluded','not_applicable') then result:=result||jsonb_build_array(jsonb_build_object('code','screening_assertion_unverified','recordId',r->'id','message','The assertion remains an open coverage finding.'));end if;
  if r->'estimateBasis'<>'null'::jsonb then result:=result||jsonb_build_array(jsonb_build_object('code','estimate_unverified','recordId',r->'id','message','Proposed estimate needs a reviewed method and supporting activity.'));end if;
 end loop;
 for r in select e from jsonb_array_elements(s->'requirements')e loop code:=case when r->>'applicability'='conflicting' then 'requirement_conflicting' else 'requirement_unknown' end;result:=result||jsonb_build_array(jsonb_build_object('code',code,'recordId',r->'id','message','Missing facts/source review prevent a legal determination.'));end loop;
 return (select jsonb_agg(e order by coalesce(e->>'recordId','') collate "C",e->>'code' collate "C") from jsonb_array_elements(result)e);
end $function$

CREATE OR REPLACE FUNCTION neuvetra.m71_lock(target_company uuid, manager boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
declare actor uuid:=auth.uid();a record;m record;begin
 select * into a from neuvetra.staging_access where user_id=actor for share;
 if not found or not a.active or a.company_id is distinct from target_company then return false;end if;
 select * into m from neuvetra.company_members where company_id=target_company and user_id=actor for share;
 if not found or (manager and m.role not in('owner','admin')) then return false;end if;
 return neuvetra.is_company_member(target_company) and (not manager or neuvetra.can_manage_company(target_company));end $function$

CREATE OR REPLACE FUNCTION neuvetra.m71_node(v jsonb, kind text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
declare spec text;pair record;child jsonb;childkind text;str text;arr jsonb;begin
 spec:=case kind
 when 'snapshot' then 'profile,companyLabel,period,consolidationApproach,policyVersion,entities,relationships,facilities,sources,boundaryDecisions,coverageItems,requirements'
 when 'period' then 'start,endExclusive'
 when 'entities' then 'id,legalName,countryCode,regionCode,start,endExclusive,evidenceRefs'
 when 'relationships' then 'id,parentEntityId,childEntityId,ownershipPercent,controlFacts,start,endExclusive,evidenceRefs'
 when 'facilities' then 'id,entityId,name,countryCode,regionCode,start,endExclusive,evidenceRefs'
 when 'sources' then 'id,entityId,facilityId,name,domain,start,endExclusive,evidenceRefs'
 when 'boundaryDecisions' then 'id,entityId,disposition,reason,start,endExclusive,evidenceRefs'
 when 'coverageItems' then 'id,domain,entityId,sourceId,disposition,activityDataState,evidenceState,methodReadiness,reason,evidenceRefs,estimateBasis,quantity,unit,start,endExclusive'
 when 'requirements' then 'id,character,sourceLocator,sourceEdition,lastCheckedOn,applicability,missingFacts,reason'
 when 'evidenceRefs' then 'artifactId,expectedSha256,locator,purpose'
 when 'estimateBasis' then 'methodVersionId,assumptions,inputEvidenceRefs,uncertainty' end;
 if spec is null then raise exception 'invalid corporate shape' using errcode='22023';end if;perform neuvetra.m71_keys(v,spec);
 for pair in select key,value from jsonb_each(v) loop
  if pair.key in('period','estimateBasis') then if pair.key='estimateBasis' and pair.value='null'::jsonb then continue;end if;perform neuvetra.m71_node(pair.value,pair.key);
  elsif pair.key in('entities','relationships','facilities','sources','boundaryDecisions','coverageItems','requirements','evidenceRefs','inputEvidenceRefs','missingFacts') then
   if jsonb_typeof(pair.value) is distinct from 'array' or jsonb_array_length(pair.value)>150 then raise exception 'invalid corporate array' using errcode='22023';end if;
   childkind:=case when pair.key='inputEvidenceRefs' then 'evidenceRefs' else pair.key end;
   if pair.key='missingFacts' then
    if jsonb_array_length(pair.value) not between 1 and 20 or exists(select 1 from jsonb_array_elements(pair.value) e where jsonb_typeof(e)<>'string' or length(e#>>'{}') not between 1 and 100 or e#>>'{}'<>btrim(e#>>'{}') or e#>>'{}'<>normalize(e#>>'{}',NFC) or e#>>'{}'~'[[:cntrl:]]') or (select count(distinct e) from jsonb_array_elements(pair.value)e)<>jsonb_array_length(pair.value) then raise exception 'invalid missing facts' using errcode='22023';end if;
    select jsonb_agg(e order by e#>>'{}' collate "C") into arr from jsonb_array_elements(pair.value)e;
   else
    for child in select value from jsonb_array_elements(pair.value) loop perform neuvetra.m71_node(child,childkind);end loop;
    if childkind='evidenceRefs' then
     if jsonb_array_length(pair.value)>8 or (select count(distinct e->>'purpose') from jsonb_array_elements(pair.value)e)<>jsonb_array_length(pair.value) then raise exception 'duplicate evidence purpose' using errcode='22023';end if;
     select coalesce(jsonb_agg(e order by e->>'purpose' collate "C"),'[]') into arr from jsonb_array_elements(pair.value)e;
    else select coalesce(jsonb_agg(e order by e->>'id' collate "C"),'[]') into arr from jsonb_array_elements(pair.value)e;end if;
   end if;
   if arr is distinct from pair.value then raise exception 'corporate arrays must be canonical' using errcode='22023';end if;
  else
   if pair.value='null'::jsonb and (pair.key in('regionCode','ownershipPercent','controlFacts','facilityId','reason','quantity','unit','sourceLocator','sourceEdition','lastCheckedOn') or kind='coverageItems' and pair.key in('entityId','sourceId')) then continue;end if;
   if jsonb_typeof(pair.value) is distinct from 'string' then raise exception 'invalid corporate scalar type' using errcode='22023';end if;
   str:=pair.value#>>'{}';
   if length(str) not between 1 and 500 or str<>btrim(str) or str<>normalize(str,NFC) or str~'[[:cntrl:]]' then raise exception 'invalid corporate text' using errcode='22023';end if;
   if pair.key in('companyLabel','legalName','name') and length(str)>160 or pair.key in('policyVersion','methodVersionId') and length(str)>100 or pair.key='unit' and length(str)>40 then raise exception 'corporate label too long' using errcode='22023';end if;
   if pair.key in('id','entityId','sourceId','facilityId','parentEntityId','childEntityId','artifactId') and str!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'invalid corporate ID' using errcode='22023';end if;
   if pair.key in('start','endExclusive','lastCheckedOn') and (str!~'^\d{4}-\d{2}-\d{2}$' or to_char(str::date,'YYYY-MM-DD')<>str) then raise exception 'invalid corporate date' using errcode='22023';end if;
   if pair.key='countryCode' and str!~'^[A-Z]{2}$' or pair.key='regionCode' and str!~'^[A-Z0-9-]{1,12}$' then raise exception 'invalid corporate geography' using errcode='22023';end if;
   if pair.key in('quantity','ownershipPercent') and (str!~'^(0|[1-9][0-9]{0,17})(\.[0-9]{0,5}[1-9])?$' or (pair.key='ownershipPercent' and str::numeric>100)) then raise exception 'invalid corporate decimal' using errcode='22023';end if;
   if pair.key='disposition' and str not in('unassessed','missing','included_activity','included_estimate','excluded','not_applicable') or pair.key='activityDataState' and str not in('not_assessed','missing','partial','entered','estimate_proposed','explicit_zero') or pair.key='evidenceState' and str not in('not_assessed','missing','partial','linked','conflicting') or pair.key='methodReadiness' and str not in('not_assessed','unsupported','candidate') or pair.key='applicability' and str not in('unknown','conflicting') or pair.key='consolidationApproach' and str not in('operational_control','financial_control','equity_share') or pair.key='character' and str not in('statute','regulation','standard','agency_guidance','proposal','enforcement_statement','court_order') then raise exception 'invalid corporate state' using errcode='22023';end if;
  end if;
 end loop;
 if v ? 'start' and ((v->>'start')>=(v->>'endExclusive') or (v->>'start')<'2025-01-01' or (v->>'endExclusive')>'2026-01-01') then raise exception 'invalid corporate interval' using errcode='22023';end if;
 if kind='evidenceRefs' and (v->>'artifactId'<>'71000000-0000-4000-8000-000000000900' or v->>'expectedSha256'<>'4fe7dc12d8f253f8d3cb1fd7fba2eade05f3d605ad7cb95376cca9d957afe5c7' or v->>'locator'<>'synthetic-register:entities-and-screening') then raise exception 'unsupported synthetic evidence' using errcode='22023';end if;
 if v->>'disposition' in('excluded','not_applicable') and (v->'reason'='null'::jsonb or jsonb_array_length(v->'evidenceRefs')=0) then raise exception 'explanation and evidence required' using errcode='22023';end if;
end $function$

CREATE OR REPLACE FUNCTION neuvetra.m71_snapshot(s jsonb, prior jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
declare key text;row jsonb;other jsonb;parent jsonb;domain text;cursor text;ids text[]:='{}';domains text[]:=array['stationary_combustion','mobile_combustion','process','fugitive','electricity','steam','heat','cooling','location_based','market_based'];begin
 perform neuvetra.m71_node(s,'snapshot');
 if octet_length(convert_to(neuvetra.m67_canonical(s),'utf8'))>50000 or s->>'profile'<>'synthetic-corporate-coverage-v1' or s->'period'<>'{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb or jsonb_array_length(s->'requirements')=0 then raise exception 'unsupported corporate profile' using errcode='22023';end if;
 if not exists(select 1 from jsonb_array_elements(s->'relationships')e where e->>'id'='71000000-0000-4000-8000-000000000010') then raise exception 'expected control relationship omitted' using errcode='22023';end if;
 for i in 1..15 loop domains:=array_append(domains,'scope3_'||i::text);end loop;
 foreach key in array array['entities','relationships','facilities','sources','boundaryDecisions','coverageItems','requirements'] loop
  for row in select value from jsonb_array_elements(s->key) loop
   if row->>'id'=any(ids) then raise exception 'duplicate corporate identity' using errcode='22023';end if;ids:=array_append(ids,row->>'id');
   if row ? 'domain' and not(row->>'domain'=any(domains)) then raise exception 'unknown screening domain' using errcode='22023';end if;
   if key in('facilities','sources','boundaryDecisions','coverageItems') and row->'entityId'<>'null'::jsonb then
    select e into parent from jsonb_array_elements(s->'entities')e where e->>'id'=row->>'entityId';
    if parent is null or row->>'start'<parent->>'start' or row->>'endExclusive'>parent->>'endExclusive' then raise exception 'invalid corporate entity binding' using errcode='22023';end if;
   end if;
  end loop;
  if prior is not null then for row in select value from jsonb_array_elements(prior->key) loop
   select e into other from jsonb_array_elements(s->key)e where e->>'id'=row->>'id';if other is null then raise exception 'corporate history cannot be omitted' using errcode='22023';end if;
   if (select jsonb_object_agg(k,v) from jsonb_each(row)t(k,v) where k in('entityId','sourceId','facilityId','parentEntityId','childEntityId','domain')) is distinct from (select jsonb_object_agg(k,v) from jsonb_each(other)t(k,v) where k in('entityId','sourceId','facilityId','parentEntityId','childEntityId','domain')) then raise exception 'corporate identity cannot be repurposed' using errcode='22023';end if;
  end loop;end if;
 end loop;
 foreach key in array array['entities','facilities','sources'] loop
  for i in 0..1 loop
   if not exists(select 1 from jsonb_array_elements(s->key)e where e->>'id'='71000000-0000-4000-8000-'||lpad((case key when 'entities' then 1 when 'facilities' then 20 else 30 end+i)::text,12,'0')) then raise exception 'expected corporate universe omitted' using errcode='22023';end if;
  end loop;
 end loop;
 for row in select value from jsonb_array_elements(s->'entities') loop
  cursor:=row->>'start';for other in select e from jsonb_array_elements(s->'boundaryDecisions')e where e->>'entityId'=row->>'id' order by e->>'start' loop
   if other->>'start'<>cursor then raise exception 'boundary interval gap or overlap' using errcode='22023';end if;cursor:=other->>'endExclusive';end loop;
  if cursor<>row->>'endExclusive' then raise exception 'missing boundary decision' using errcode='22023';end if;
 end loop;
 for row in select value from jsonb_array_elements(s->'relationships') loop
  foreach key in array array['parentEntityId','childEntityId'] loop select e into parent from jsonb_array_elements(s->'entities')e where e->>'id'=row->>key;
   if parent is null or row->>'start'<parent->>'start' or row->>'endExclusive'>parent->>'endExclusive' then raise exception 'invalid relationship binding' using errcode='22023';end if;end loop;
  if row->>'parentEntityId'=row->>'childEntityId' or exists(select 1 from jsonb_array_elements(s->'relationships')e where e->>'id'<>row->>'id' and e->>'childEntityId'=row->>'childEntityId' and e->>'start'<row->>'endExclusive' and row->>'start'<e->>'endExclusive') then raise exception 'overlapping relationship' using errcode='22023';end if;
 end loop;
 if exists(with recursive edges as(select e->>'parentEntityId' p,e->>'childEntityId' c,e->>'start' a,e->>'endExclusive' b from jsonb_array_elements(s->'relationships')e),walk as(select p,c,a,b,array[p,c] path,p=c cycle from edges union all select w.p,e.c,greatest(w.a,e.a),least(w.b,e.b),w.path||e.c,e.c=any(w.path) from walk w join edges e on e.p=w.c and e.a<w.b and w.a<e.b where not w.cycle)select 1 from walk where cycle) then raise exception 'effective relationship cycle' using errcode='22023';end if;
 for row in select value from jsonb_array_elements(s->'sources') loop
  if row->'facilityId'<>'null'::jsonb then select e into parent from jsonb_array_elements(s->'facilities')e where e->>'id'=row->>'facilityId';if parent is null or parent->>'entityId'<>row->>'entityId' or row->>'start'<parent->>'start' or row->>'endExclusive'>parent->>'endExclusive' then raise exception 'invalid source facility' using errcode='22023';end if;end if;
  if (select count(*) from jsonb_array_elements(s->'coverageItems')e where e->>'sourceId'=row->>'id' and e->>'start'=row->>'start' and e->>'endExclusive'=row->>'endExclusive')<>1 then raise exception 'source coverage missing' using errcode='22023';end if;
 end loop;
 for row in select value from jsonb_array_elements(s->'coverageItems') loop
  if row->'sourceId'<>'null'::jsonb then select e into parent from jsonb_array_elements(s->'sources')e where e->>'id'=row->>'sourceId';if parent is null or parent->>'entityId' is distinct from row->>'entityId' or parent->>'domain'<>row->>'domain' or row->>'start'<>parent->>'start' or row->>'endExclusive'<>parent->>'endExclusive' then raise exception 'invalid source screening' using errcode='22023';end if;
  elsif row->'entityId'<>'null'::jsonb then raise exception 'unsupported entity-only screening' using errcode='22023';
  elsif row->>'start'<>'2025-01-01' or row->>'endExclusive'<>'2026-01-01' then raise exception 'group screening must cover full period' using errcode='22023';end if;
  if (row->'quantity'='null'::jsonb)<>(row->'unit'='null'::jsonb) or (coalesce(row->>'quantity'='0',false))<>(row->>'activityDataState'='explicit_zero') or (row->'quantity'<>'null'::jsonb and row->>'activityDataState' not in('entered','partial','estimate_proposed','explicit_zero')) then raise exception 'invalid activity state' using errcode='22023';end if;
  if row->>'evidenceState'='linked' and jsonb_array_length(row->'evidenceRefs')=0 or row->>'activityDataState'='explicit_zero' and (row->'reason'='null'::jsonb or jsonb_array_length(row->'evidenceRefs')=0) then raise exception 'activity evidence missing' using errcode='22023';end if;
  if row->>'disposition'='included_estimate' and (row->'estimateBasis'='null'::jsonb or row->>'activityDataState'<>'estimate_proposed') or row->'estimateBasis'<>'null'::jsonb and jsonb_array_length(row#>'{estimateBasis,inputEvidenceRefs}')=0 then raise exception 'invalid estimate basis' using errcode='22023';end if;
 end loop;
 foreach domain in array domains loop if (select count(*) from jsonb_array_elements(s->'coverageItems')e where e->'entityId'='null'::jsonb and e->'sourceId'='null'::jsonb and e->>'domain'=domain and e->>'start'='2025-01-01' and e->>'endExclusive'='2026-01-01')<>1 then raise exception 'required group screening missing or duplicated' using errcode='22023';end if;end loop;
end $function$

CREATE OR REPLACE FUNCTION neuvetra.m73_calculation(a jsonb, statement_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare q numeric;co2 numeric;ch4 numeric;n2o numeric;total numeric;i jsonb;body jsonb;begin
if a->'quantityMmbtu'='null' then return 'null'::jsonb;end if;q:=(a->>'quantityMmbtu')::numeric;co2:=q*53.06;ch4:=q/1000;n2o:=q/10000;total:=co2+ch4*28+n2o*265;
i:=jsonb_build_object('binding',a->'binding','period',a->'period','fuel',a->'fuel','heatBasis',a->'heatBasis','unit',a->'unit','quantityMmbtu',a->'quantityMmbtu','statementSha256',statement_hash);
body:=jsonb_build_object('profile','m73-decimal-result-v1','input',i,'inputSha256',neuvetra.m67_hash(i),'method',neuvetra.m73_method(),'gasResults',jsonb_build_object('co2',jsonb_build_object('mass',neuvetra.m73_exact(co2),'massUnit','kg CO2','co2e',neuvetra.m73_exact(co2),'co2eUnit','kg CO2e'),'ch4',jsonb_build_object('mass',neuvetra.m73_exact(ch4),'massUnit','kg CH4','co2e',neuvetra.m73_exact(ch4*28),'co2eUnit','kg CO2e'),'n2o',jsonb_build_object('mass',neuvetra.m73_exact(n2o),'massUnit','kg N2O','co2e',neuvetra.m73_exact(n2o*265),'co2eUnit','kg CO2e')),'total',jsonb_build_object('unrounded',neuvetra.m73_exact(total),'display',neuvetra.m73_display(total),'unit','kg CO2e','rounding','half_even_4dp'));
return body||jsonb_build_object('resultSha256',neuvetra.m67_hash(body));end $function$

CREATE OR REPLACE FUNCTION neuvetra.m73_coverage(target_company uuid, b jsonb, current_required boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare cv record;s jsonb;e jsonb;f jsonb;src jsonb;bd jsonb;rel jsonb;node text;seen text[]:='{}';pair record;begin
perform neuvetra.m71_keys(b,'coverageVersionId,coverageVersionSha256,entityId,facilityId,sourceId,boundaryDecisionId');for pair in select key,value from jsonb_each(b) loop if jsonb_typeof(pair.value)<>'string' or (pair.value#>>'{}') !~ (case when pair.key='coverageVersionSha256' then '^[0-9a-f]{64}$' else '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' end) then raise exception 'invalid binding' using errcode='22023';end if;end loop;
select * into cv from neuvetra.corporate_inventory_versions where company_id=target_company and id=(b->>'coverageVersionId')::uuid;if not found or cv.version_sha256<>b->>'coverageVersionSha256' then raise exception 'coverage binding conflict' using errcode='23505';end if;
if current_required and not exists(select 1 from neuvetra.corporate_inventory_heads where company_id=target_company and version_id=cv.id) then raise exception 'coverage changed' using errcode='23505';end if;
s:=cv.payload->'snapshot';perform neuvetra.m71_snapshot(s,null);if neuvetra.m67_hash(s)<>cv.content_sha256 or neuvetra.m67_hash((cv.payload-'snapshot'-'versionSha256')||jsonb_build_object('profile','synthetic-corporate-coverage-v1'))<>cv.version_sha256 or cv.export_text<>neuvetra.m67_canonical(cv.payload||jsonb_build_object('findings',neuvetra.m71_findings(s),'synthetic',true,'corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','emissionsTotals',null,'review',null)) then raise exception 'coverage integrity failure' using errcode='22023';end if;
select x into e from jsonb_array_elements(s->'entities')x where x->>'id'=b->>'entityId';select x into f from jsonb_array_elements(s->'facilities')x where x->>'id'=b->>'facilityId';select x into src from jsonb_array_elements(s->'sources')x where x->>'id'=b->>'sourceId';select x into bd from jsonb_array_elements(s->'boundaryDecisions')x where x->>'id'=b->>'boundaryDecisionId';
if s->>'consolidationApproach'<>'operational_control' or e is null or f is null or src is null or bd is null or src->>'domain'<>'stationary_combustion' or src->>'entityId'<>e->>'id' or src->>'facilityId'<>f->>'id' or f->>'entityId'<>e->>'id' or bd->>'entityId'<>e->>'id' or e->>'countryCode'<>'US' or e->>'regionCode' is distinct from 'CA' or f->>'countryCode'<>'US' or f->>'regionCode' is distinct from 'CA' or bd->>'disposition'<>'included_activity' or bd->'reason'='null' or jsonb_array_length(bd->'evidenceRefs')=0 then raise exception 'source ineligible' using errcode='22023';end if;
for pair in select value from jsonb_array_elements(jsonb_build_array(e,f,src,bd))loop if pair.value->>'start'<>'2025-01-01' or pair.value->>'endExclusive'<>'2026-01-01' then raise exception 'unsupported period' using errcode='22023';end if;end loop;
node:=e->>'id';loop if node=any(seen) then raise exception 'relationship cycle' using errcode='22023';end if;seen:=array_append(seen,node);select x into rel from jsonb_array_elements(s->'relationships')x where x->>'childEntityId'=node;exit when rel is null;if rel->>'start'<>'2025-01-01' or rel->>'endExclusive'<>'2026-01-01' or rel->>'ownershipPercent' is distinct from '100' or rel->'controlFacts'='null' or jsonb_array_length(rel->'evidenceRefs')=0 then raise exception 'control basis incomplete' using errcode='22023';end if;node:=rel->>'parentEntityId';end loop;
return cv.export_text::jsonb;end $function$

CREATE OR REPLACE FUNCTION neuvetra.m73_render_report(snapshot jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare v jsonb:=snapshot->'version';c jsonb:=v->'calculation';src jsonb;f jsonb;entity jsonb;boundary jsonb;fields jsonb;facts text;findings text;begin
select x into src from jsonb_array_elements(v#>'{coverageVersion,snapshot,sources}')x where x->>'id'=v#>>'{activity,binding,sourceId}';select x into f from jsonb_array_elements(v#>'{coverageVersion,snapshot,facilities}')x where x->>'id'=v#>>'{activity,binding,facilityId}';
select x into entity from jsonb_array_elements(v#>'{coverageVersion,snapshot,entities}')x where x->>'id'=v#>>'{activity,binding,entityId}';select x into boundary from jsonb_array_elements(v#>'{coverageVersion,snapshot,boundaryDecisions}')x where x->>'id'=v#>>'{activity,binding,boundaryDecisionId}';
facts:=neuvetra.m73_pair('Company',v#>>'{coverageVersion,snapshot,companyLabel}')||neuvetra.m73_pair('Entity',entity->>'legalName')||neuvetra.m73_pair('Boundary basis',boundary->>'reason')||neuvetra.m73_pair('Facility',f->>'name')||neuvetra.m73_pair('Source',src->>'name')||neuvetra.m73_pair('Reporting period','2025-01-01 through 2026-01-01 (exclusive)')||neuvetra.m73_pair('Coverage version',v#>>'{activity,binding,coverageVersionId}')||neuvetra.m73_pair('Source version',v->>'version')||neuvetra.m73_pair('Entered natural gas (MMBtu HHV)',v#>>'{activity,quantityMmbtu}')||neuvetra.m73_pair('Statement amount (MMBtu HHV)',v#>>'{activity,statement,statedQuantityMmbtu}')||neuvetra.m73_pair('Discrepancy explanation',coalesce(v#>>'{activity,discrepancyReason}','Not applicable'))||neuvetra.m73_pair('No-consumption explanation',coalesce(v#>>'{activity,zeroReason}','Not applicable'))||neuvetra.m73_pair('Exact source subtotal (kg CO2e)',c#>>'{total,unrounded}')||neuvetra.m73_pair('Displayed source subtotal (kg CO2e)',c#>>'{total,display}')||neuvetra.m73_pair('Review as captured',coalesce(snapshot#>>'{review,decision}','Unreviewed'))||neuvetra.m73_pair('Reviewer note',coalesce(snapshot#>>'{review,note}','Not yet reviewed'))||neuvetra.m73_pair('Review time',coalesce(snapshot#>>'{review,reviewedAt}','Not yet reviewed'))||neuvetra.m73_pair('Correction reason',coalesce(v->>'correctionReason','Not applicable'));
select coalesce(string_agg('<li>'||neuvetra.m73_escape(message)||'</li>','' order by ord),'') into findings from(select x->>'message' message,min(ord) ord from jsonb_array_elements((v->'findings')||(v#>'{coverageVersion,findings}')) with ordinality a(x,ord) group by x->>'message') deduplicated;
fields:=jsonb_build_object('facts',facts,'calculation',case when c='null' then '<p>Activity is missing; no emissions total was calculated.</p>' else '<table><thead><tr><th>Gas</th><th>Mass (kg)</th><th>kg CO2e</th></tr></thead><tbody>'||(select string_agg('<tr><th>'||label||'</th><td>'||neuvetra.m73_escape(c#>>array['gasResults',key,'mass'])||'</td><td>'||neuvetra.m73_escape(c#>>array['gasResults',key,'co2e'])||'</td></tr>','' order by ord) from(values('co2','CO2',1),('ch4','CH4',2),('n2o','N2O',3)) gases(key,label,ord))||'</tbody></table><p>Only the displayed total is rounded to four decimal places, using half-even rounding. Gas values and the exact total retain full precision.</p>' end,'statement',case when v->'statement'='null' then neuvetra.m73_pair('Evidence','No supporting statement entered') else neuvetra.m73_pair('Statement type','Synthetic — not a utility bill')||neuvetra.m73_pair('Issuer',v#>>'{activity,statement,issuer}')||neuvetra.m73_pair('Reference',v#>>'{activity,statement,reference}')||neuvetra.m73_pair('Dedicated meter',v#>>'{activity,statement,meterLabel}')||neuvetra.m73_pair('Annual period','2025-01-01 through 2026-01-01 (exclusive)')||neuvetra.m73_pair('Stated energy (MMBtu HHV)',v#>>'{activity,statement,statedQuantityMmbtu}')||neuvetra.m73_pair('Description',v#>>'{activity,statement,description}')||neuvetra.m73_pair('Retained statement locator',v#>>'{statement,locator}')||neuvetra.m73_pair('Statement SHA-256',v#>>'{statement,sha256}') end,'findings',findings,'snapshot',neuvetra.m73_escape(neuvetra.m67_canonical(snapshot)));
return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src ''none''; style-src ''unsafe-inline''; base-uri ''none''; form-action ''none''"><title>Synthetic stationary natural-gas source report</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:900px;color:#172f2c;overflow-wrap:anywhere}h1,h2{line-height:1.2}dt{font-weight:700}dd{margin:0 0 .6rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}li{margin:.3rem 0}table{border-collapse:collapse;width:100%}th,td{padding:.45rem;text-align:left;border-bottom:1px solid #ccd8d0}@media print{body{font-size:11pt;margin:0;max-width:none}h2{break-after:avoid}pre{font-size:9pt}.technical-appendix:not([open]){display:none}}</style></head><body><h1>Stationary natural-gas source report — synthetic internal draft</h1><p>Development candidate · Not released. Corporate inventory incomplete. No filing determination or external assurance.</p><h2>Source and activity</h2><dl>'||(fields->>'facts')||'</dl><h2>Gas results and calculation trace</h2>'||(fields->>'calculation')||'<h2>Supporting synthetic statement</h2><dl>'||(fields->>'statement')||'</dl><h2>Corporate coverage remains incomplete</h2><p>Stationary combustion is partial. Mobile combustion, fugitive emissions including refrigerants, process emissions, other sources/facilities/periods, Scope 2 and all 15 Scope 3 categories remain unresolved or separately assessed. Combustion only; upstream fuel emissions excluded.</p><ul>'||(fields->>'findings')||'</ul><details class="technical-appendix"><summary>Exact version and provenance record</summary><pre>'||(fields->>'snapshot')||'</pre></details></body></html>';end $function$

CREATE OR REPLACE FUNCTION neuvetra.m73_validate_request(r jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare a jsonb;rkey text;begin
perform neuvetra.m71_keys(r,'profile,binding,period,fuel,heatBasis,unit,quantityMmbtu,statement,manualConfirmation,discrepancyReason,zeroReason,expectedVersionId,expectedVersionSha256,correctionReason,idempotencyKey');
if r->>'profile' is distinct from 'synthetic-stationary-natural-gas-v1' or r->'period' is distinct from '{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb or r->>'fuel' is distinct from 'Natural Gas' or r->>'heatBasis' is distinct from 'HHV' or r->>'unit' is distinct from 'MMBtu' or jsonb_typeof(r->'manualConfirmation') is distinct from 'boolean' or jsonb_typeof(r->'idempotencyKey') is distinct from 'string' or r->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'invalid profile' using errcode='22023';end if;
foreach rkey in array array['discrepancyReason','zeroReason','correctionReason']loop if r->rkey<>'null' then perform neuvetra.m73_text(r->rkey,500);end if;end loop;
if r->'expectedVersionId'='null' then if r->'expectedVersionSha256'<>'null' or r->'correctionReason'<>'null' then raise exception 'initial binding invalid' using errcode='22023';end if;else if jsonb_typeof(r->'expectedVersionId')<>'string' or r->>'expectedVersionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(r->'expectedVersionSha256')<>'string' or r->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or r->'correctionReason'='null' then raise exception 'correction binding invalid' using errcode='22023';end if;end if;
if r->'statement'<>'null' then a:=r->'statement';perform neuvetra.m71_keys(a,'issuer,reference,meterLabel,statedQuantityMmbtu,description,consumptionBasis');perform neuvetra.m73_text(a->'issuer',120);perform neuvetra.m73_text(a->'reference',120);perform neuvetra.m73_text(a->'meterLabel',120);perform neuvetra.m73_text(a->'description',2000);perform neuvetra.m73_quantity(a->'statedQuantityMmbtu');if a->>'consumptionBasis' is distinct from 'dedicated_meter_consumed_no_adjustments' then raise exception 'consumption basis invalid' using errcode='22023';end if;end if;
if r->'quantityMmbtu'<>'null' then perform neuvetra.m73_quantity(r->'quantityMmbtu');if r->'statement'='null' or r->'manualConfirmation'<>'true' then raise exception 'evidence missing' using errcode='22023';end if;if r->>'quantityMmbtu'='0.000' then if r#>>'{statement,statedQuantityMmbtu}'<>'0.000' or r->'zeroReason'='null' then raise exception 'zero unsupported' using errcode='22023';end if;elsif r->>'quantityMmbtu'<>r#>>'{statement,statedQuantityMmbtu}' and r->'discrepancyReason'='null' then raise exception 'discrepancy reason missing' using errcode='22023';end if;end if;end $function$

CREATE OR REPLACE FUNCTION neuvetra.m74_calculation(a jsonb, fuel_hash text, mileage_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare gallons numeric;miles numeric;co2 numeric;ch4 numeric;n2o numeric;ch4e numeric;n2oe numeric;total numeric;i jsonb;body jsonb;begin
if not neuvetra.m74_can_calculate(a) then return 'null'::jsonb;end if;gallons:=(a->>'quantityGallons')::numeric;miles:=(a->>'distanceMiles')::numeric;co2:=gallons*10.21;ch4:=miles*0.0095/1000;n2o:=miles*0.0431/1000;ch4e:=ch4*28;n2oe:=n2o*265;total:=co2+ch4e+n2oe;
i:=jsonb_build_object('binding',a->'binding','period',a->'period','vehicle',a->'vehicle','quantityGallons',a->'quantityGallons','quantityUnit','US_gallon','distanceMiles',a->'distanceMiles','distanceUnit','vehicle_mile','fuelStatementSha256',fuel_hash,'mileageStatementSha256',mileage_hash);
body:=jsonb_build_object('profile','m74-decimal-result-v1','input',i,'inputSha256',neuvetra.m67_hash(i),'method',neuvetra.m74_method(),'gasResults',jsonb_build_object('co2',jsonb_build_object('mass',neuvetra.m74_exact(co2),'massUnit','kg CO2','co2e',neuvetra.m74_exact(co2),'co2eUnit','kg CO2e'),'ch4',jsonb_build_object('mass',neuvetra.m74_exact(ch4),'massUnit','kg CH4','co2e',neuvetra.m74_exact(ch4e),'co2eUnit','kg CO2e'),'n2o',jsonb_build_object('mass',neuvetra.m74_exact(n2o),'massUnit','kg N2O','co2e',neuvetra.m74_exact(n2oe),'co2eUnit','kg CO2e')),'total',jsonb_build_object('unrounded',neuvetra.m74_exact(total),'display',neuvetra.m74_display(total),'unit','kg CO2e','rounding','half_even_4dp'));
return body||jsonb_build_object('resultSha256',neuvetra.m67_hash(body));end $function$

CREATE OR REPLACE FUNCTION neuvetra.m74_coverage(target_company uuid, b jsonb, current_required boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare cv record;s jsonb;e jsonb;f jsonb;src jsonb;bd jsonb;rel jsonb;node text;seen text[]:='{}';pair record;begin
perform neuvetra.m71_keys(b,'coverageVersionId,coverageVersionSha256,entityId,facilityId,sourceId,boundaryDecisionId');for pair in select key,value from jsonb_each(b) loop if jsonb_typeof(pair.value)<>'string' or (pair.value#>>'{}') !~ (case when pair.key='coverageVersionSha256' then '^[0-9a-f]{64}$' else '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' end) then raise exception 'invalid binding' using errcode='22023';end if;end loop;
select * into cv from neuvetra.corporate_inventory_versions where company_id=target_company and id=(b->>'coverageVersionId')::uuid;if not found or cv.version_sha256<>b->>'coverageVersionSha256' then raise exception 'coverage binding conflict' using errcode='23505';end if;
if current_required and not exists(select 1 from neuvetra.corporate_inventory_heads where company_id=target_company and version_id=cv.id) then raise exception 'coverage changed' using errcode='23505';end if;
s:=cv.payload->'snapshot';perform neuvetra.m71_snapshot(s,null);if neuvetra.m67_hash(s)<>cv.content_sha256 or neuvetra.m67_hash((cv.payload-'snapshot'-'versionSha256')||jsonb_build_object('profile','synthetic-corporate-coverage-v1'))<>cv.version_sha256 or cv.export_text<>neuvetra.m67_canonical(cv.payload||jsonb_build_object('findings',neuvetra.m71_findings(s),'synthetic',true,'corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','emissionsTotals',null,'review',null)) then raise exception 'coverage integrity failure' using errcode='22023';end if;
select x into e from jsonb_array_elements(s->'entities')x where x->>'id'=b->>'entityId';select x into f from jsonb_array_elements(s->'facilities')x where x->>'id'=b->>'facilityId';select x into src from jsonb_array_elements(s->'sources')x where x->>'id'=b->>'sourceId';select x into bd from jsonb_array_elements(s->'boundaryDecisions')x where x->>'id'=b->>'boundaryDecisionId';
if s->>'consolidationApproach'<>'operational_control' or e is null or f is null or src is null or bd is null or src->>'domain'<>'mobile_combustion' or src->>'entityId'<>e->>'id' or src->>'facilityId'<>f->>'id' or f->>'entityId'<>e->>'id' or bd->>'entityId'<>e->>'id' or e->>'countryCode'<>'US' or e->>'regionCode' is distinct from 'CA' or f->>'countryCode'<>'US' or f->>'regionCode' is distinct from 'CA' or bd->>'disposition'<>'included_activity' or bd->'reason'='null' or jsonb_array_length(bd->'evidenceRefs')=0 then raise exception 'source ineligible' using errcode='22023';end if;
for pair in select value from jsonb_array_elements(jsonb_build_array(e,f,src,bd))loop if pair.value->>'start'<>'2025-01-01' or pair.value->>'endExclusive'<>'2026-01-01' then raise exception 'unsupported period' using errcode='22023';end if;end loop;
node:=e->>'id';loop if node=any(seen) then raise exception 'relationship cycle' using errcode='22023';end if;seen:=array_append(seen,node);select x into rel from jsonb_array_elements(s->'relationships')x where x->>'childEntityId'=node;exit when rel is null;if rel->>'start'<>'2025-01-01' or rel->>'endExclusive'<>'2026-01-01' or rel->>'ownershipPercent' is distinct from '100' or rel->'controlFacts'='null' or jsonb_array_length(rel->'evidenceRefs')=0 then raise exception 'control basis incomplete' using errcode='22023';end if;node:=rel->>'parentEntityId';end loop;
return cv.export_text::jsonb;end $function$

CREATE OR REPLACE FUNCTION neuvetra.m74_render_report(snapshot jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare v jsonb:=snapshot->'version';c jsonb:=v->'calculation';m jsonb:=c->'method';src jsonb;f jsonb;entity jsonb;boundary jsonb;facts text;calc text;fuel text;mileage text;method text;findings text;begin
select x into src from jsonb_array_elements(v#>'{coverageVersion,snapshot,sources}')x where x->>'id'=v#>>'{activity,binding,sourceId}';select x into f from jsonb_array_elements(v#>'{coverageVersion,snapshot,facilities}')x where x->>'id'=v#>>'{activity,binding,facilityId}';select x into entity from jsonb_array_elements(v#>'{coverageVersion,snapshot,entities}')x where x->>'id'=v#>>'{activity,binding,entityId}';select x into boundary from jsonb_array_elements(v#>'{coverageVersion,snapshot,boundaryDecisions}')x where x->>'id'=v#>>'{activity,binding,boundaryDecisionId}';
facts:=neuvetra.m74_pair('Company',v#>>'{coverageVersion,snapshot,companyLabel}')||neuvetra.m74_pair('Entity',entity->>'legalName')||neuvetra.m74_pair('Boundary basis',boundary->>'reason')||neuvetra.m74_pair('Base facility',f->>'name')||neuvetra.m74_pair('Source',src->>'name')||neuvetra.m74_pair('Reporting period','2025-01-01 through 2026-01-01 (exclusive)')||neuvetra.m74_pair('All-trip location basis','All vehicle travel, including interstate trips')||neuvetra.m74_pair('Coverage version',v#>>'{activity,binding,coverageVersionId}')||neuvetra.m74_pair('Source version',v->>'version')||neuvetra.m74_pair('Vehicle asset ID',v#>>'{activity,vehicle,assetId}')||neuvetra.m74_pair('Vehicle class',v#>>'{activity,vehicle,vehicleClass}')||neuvetra.m74_pair('Classification basis',v#>>'{activity,vehicle,classificationBasis}')||neuvetra.m74_pair('Model year',v#>>'{activity,vehicle,modelYear}')||neuvetra.m74_pair('Fuel',v#>>'{activity,vehicle,fuel}')||neuvetra.m74_pair('Control basis',v#>>'{activity,vehicle,controlBasis}')||neuvetra.m74_pair('Entered consumed fuel (U.S. gallons)',v#>>'{activity,quantityGallons}')||neuvetra.m74_pair('Fuel statement amount (U.S. gallons)',v#>>'{activity,fuelStatement,statedQuantityGallons}')||neuvetra.m74_pair('Fuel dimension status',v#>>'{activityStatus,fuel}')||neuvetra.m74_pair('Fuel discrepancy explanation',coalesce(v#>>'{activity,fuelDiscrepancyReason}','Not applicable'))||neuvetra.m74_pair('Entered distance (vehicle-miles)',v#>>'{activity,distanceMiles}')||neuvetra.m74_pair('Mileage statement amount (vehicle-miles)',v#>>'{activity,mileageStatement,statedDistanceMiles}')||neuvetra.m74_pair('Mileage dimension status',v#>>'{activityStatus,mileage}')||neuvetra.m74_pair('Mileage discrepancy explanation',coalesce(v#>>'{activity,mileageDiscrepancyReason}','Not applicable'))||neuvetra.m74_pair('No-operation/no-consumption explanation',coalesce(v#>>'{activity,zeroReason}','Not applicable'))||neuvetra.m74_pair('Exact vehicle mobile-combustion subtotal (kg CO2e)',c#>>'{total,unrounded}')||neuvetra.m74_pair('Displayed vehicle mobile-combustion subtotal (kg CO2e)',c#>>'{total,display}')||neuvetra.m74_pair('Review as captured',coalesce(snapshot#>>'{review,decision}','Unreviewed'))||neuvetra.m74_pair('Reviewer note',coalesce(snapshot#>>'{review,note}','Not yet reviewed'))||neuvetra.m74_pair('Review time',coalesce(snapshot#>>'{review,reviewedAt}','Not yet reviewed'))||neuvetra.m74_pair('Correction reason',coalesce(v->>'correctionReason','Not applicable'));
if c='null' then calc:='<p>Required compatible activity and evidence are incomplete or contradictory; no emissions total was calculated.</p>';method:=neuvetra.m74_pair('Method','No calculation was admitted; method remains a development candidate');else calc:='<table><thead><tr><th>Gas</th><th>Mass</th><th>kg CO2e</th></tr></thead><tbody>'||(select string_agg('<tr><th>'||label||'</th><td>'||neuvetra.m74_escape(c#>>array['gasResults',key,'mass'])||' '||neuvetra.m74_escape(c#>>array['gasResults',key,'massUnit'])||'</td><td>'||neuvetra.m74_escape(c#>>array['gasResults',key,'co2e'])||'</td></tr>','' order by ord)from(values('co2','CO2',1),('ch4','CH4',2),('n2o','N2O',3))gases(key,label,ord))||'</tbody></table><p>CO2 uses consumed U.S. gallons. CH4 and N2O use vehicle-miles. Only the displayed total is rounded to four decimal places, using half-even rounding. Gas values and the exact total retain full precision.</p>';method:=neuvetra.m74_pair('Method ID and version',(m->>'id')||' / '||(m->>'version'))||neuvetra.m74_pair('Source',m->>'sourceTitle')||neuvetra.m74_pair('Source edition','January 15, 2025')||neuvetra.m74_pair('Workbook SHA-256',m->>'sourceSha256')||neuvetra.m74_pair('Factor locators',(select string_agg(value,', ' order by ord)from jsonb_array_elements_text(m->'factorCells')with ordinality x(value,ord)))||neuvetra.m74_pair('GWP locators',(select string_agg(value,', ' order by ord)from jsonb_array_elements_text(m->'gwpCells')with ordinality x(value,ord)))||neuvetra.m74_pair('Note locators',(select string_agg(value,', ' order by ord)from jsonb_array_elements_text(m->'noteCells')with ordinality x(value,ord)))||neuvetra.m74_pair('Factor normalization','Published displayed decimals corroborated by the EPA 2025 PDF; XLSX binary tails are not used')||neuvetra.m74_pair('CO2 factor',(m->>'co2KgPerGallon')||' kg CO2 per U.S. gallon')||neuvetra.m74_pair('CH4 factor',(m->>'ch4GramsPerMile')||' g CH4 per vehicle-mile')||neuvetra.m74_pair('N2O factor',(m->>'n2oGramsPerMile')||' g N2O per vehicle-mile')||neuvetra.m74_pair('GWP basis',(m->>'gwpAssessment')||'; CH4 '||(m->>'ch4Gwp')||', N2O '||(m->>'n2oGwp'))||neuvetra.m74_pair('Rights status',m->>'rights')||neuvetra.m74_pair('Method status',m->>'status');end if;
fuel:=case when v->'fuelStatement'='null' then neuvetra.m74_pair('Evidence','No supporting fuel statement retained') else neuvetra.m74_pair('Statement type','Synthetic human-entered fuel statement')||neuvetra.m74_pair('Issuer',v#>>'{activity,fuelStatement,issuer}')||neuvetra.m74_pair('Reference',v#>>'{activity,fuelStatement,reference}')||neuvetra.m74_pair('Annual period','2025-01-01 through 2026-01-01 (exclusive)')||neuvetra.m74_pair('Stated consumed fuel (U.S. gallons)',v#>>'{activity,fuelStatement,statedQuantityGallons}')||neuvetra.m74_pair('Description',v#>>'{activity,fuelStatement,description}')||neuvetra.m74_pair('Manual confirmation',v#>>'{activity,fuelManualConfirmation}')||neuvetra.m74_pair('Retained statement locator',v#>>'{fuelStatement,locator}')||neuvetra.m74_pair('Statement SHA-256',v#>>'{fuelStatement,sha256}')||neuvetra.m74_pair('Statement byte length',v#>>'{fuelStatement,byteLength}') end;
mileage:=case when v->'mileageStatement'='null' then neuvetra.m74_pair('Evidence','No supporting mileage statement retained') else neuvetra.m74_pair('Statement type','Synthetic human-entered mileage statement')||neuvetra.m74_pair('Issuer',v#>>'{activity,mileageStatement,issuer}')||neuvetra.m74_pair('Reference',v#>>'{activity,mileageStatement,reference}')||neuvetra.m74_pair('Annual period','2025-01-01 through 2026-01-01 (exclusive)')||neuvetra.m74_pair('Stated distance (vehicle-miles)',v#>>'{activity,mileageStatement,statedDistanceMiles}')||neuvetra.m74_pair('Description',v#>>'{activity,mileageStatement,description}')||neuvetra.m74_pair('Manual confirmation',v#>>'{activity,mileageManualConfirmation}')||neuvetra.m74_pair('Retained statement locator',v#>>'{mileageStatement,locator}')||neuvetra.m74_pair('Statement SHA-256',v#>>'{mileageStatement,sha256}')||neuvetra.m74_pair('Statement byte length',v#>>'{mileageStatement,byteLength}') end;
select coalesce(string_agg('<li>'||neuvetra.m74_escape(message)||'</li>','' order by ord),'')into findings from(select x->>'message' message,min(ord)ord from jsonb_array_elements((v->'findings')||(v#>'{coverageVersion,findings}'))with ordinality a(x,ord)group by x->>'message')deduplicated;
return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src ''none''; style-src ''unsafe-inline''; base-uri ''none''; form-action ''none''"><title>Synthetic vehicle mobile-combustion source report</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:900px;color:#172f2c;overflow-wrap:anywhere}h1,h2{line-height:1.2}dt{font-weight:700}dd{margin:0 0 .6rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}li{margin:.3rem 0}table{border-collapse:collapse;width:100%}th,td{padding:.45rem;text-align:left;border-bottom:1px solid #ccd8d0}@media print{body{font-size:11pt;margin:0;max-width:none}h2{break-after:avoid}pre{font-size:9pt}.technical-appendix:not([open]){display:none}}</style></head><body><h1>Vehicle mobile-combustion subtotal — synthetic internal draft</h1><p>Development candidate · Not released. Corporate inventory incomplete. No filing determination or external assurance.</p><h2>Source, vehicle and activity</h2><dl>'||facts||'</dl><h2>Gas results and calculation trace</h2>'||calc||'<h2>Supporting synthetic fuel statement</h2><dl>'||fuel||'</dl><h2>Supporting synthetic mileage statement</h2><dl>'||mileage||'</dl><h2>Method and provenance</h2><dl>'||method||'</dl><h2>Corporate coverage remains incomplete</h2><p>This report covers one bounded vehicle source. Other stationary, mobile, fugitive, process, facility and period sources remain unresolved or separately assessed. Combustion only; upstream fuel emissions are excluded.</p><ul>'||findings||'</ul><details class="technical-appendix"><summary>Exact version and provenance record</summary><pre>'||neuvetra.m74_escape(neuvetra.m67_canonical(snapshot))||'</pre></details></body></html>';end $function$

CREATE OR REPLACE FUNCTION neuvetra.m74_validate_request(r jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare a jsonb;k text;begin
perform neuvetra.m71_keys(r,'profile,binding,period,vehicle,quantityGallons,distanceMiles,fuelStatement,mileageStatement,fuelManualConfirmation,mileageManualConfirmation,fuelDiscrepancyReason,mileageDiscrepancyReason,zeroReason,expectedVersionId,expectedVersionSha256,correctionReason,idempotencyKey');
if r->>'profile' is distinct from 'synthetic-mobile-diesel-v1' or r->'period' is distinct from '{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb or jsonb_typeof(r->'fuelManualConfirmation') is distinct from 'boolean' or jsonb_typeof(r->'mileageManualConfirmation') is distinct from 'boolean' or jsonb_typeof(r->'idempotencyKey') is distinct from 'string' or r->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'invalid profile' using errcode='22023';end if;
a:=r->'vehicle';perform neuvetra.m71_keys(a,'assetId,vehicleClass,classificationBasis,modelYear,fuel,controlBasis');if jsonb_typeof(a->'assetId')<>'string' or a->>'assetId'!~'^[A-Z0-9][A-Z0-9._-]{0,63}$' or a->>'vehicleClass'<>'Medium- and Heavy-Duty Vehicles' or jsonb_typeof(a->'modelYear')<>'number' or a->>'modelYear'!~'^(200[7-9]|201[0-9]|202[0-2])$' or a->>'fuel'<>'Fossil Diesel' or a->>'controlBasis'<>'owned_operational_control_full_year' then raise exception 'unsupported vehicle' using errcode='22023';end if;perform neuvetra.m74_text(a->'classificationBasis',500);
foreach k in array array['fuelDiscrepancyReason','mileageDiscrepancyReason','zeroReason','correctionReason']loop if r->k<>'null' then perform neuvetra.m74_text(r->k,500);end if;end loop;
if r->'expectedVersionId'='null' then if r->'expectedVersionSha256'<>'null' or r->'correctionReason'<>'null' then raise exception 'initial binding invalid' using errcode='22023';end if;else if jsonb_typeof(r->'expectedVersionId')<>'string' or r->>'expectedVersionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(r->'expectedVersionSha256')<>'string' or r->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or r->'correctionReason'='null' then raise exception 'correction binding invalid' using errcode='22023';end if;end if;
if r->'quantityGallons'<>'null' then perform neuvetra.m74_quantity(r->'quantityGallons');end if;if r->'distanceMiles'<>'null' then perform neuvetra.m74_quantity(r->'distanceMiles');end if;
if r->'fuelStatement'<>'null' then a:=r->'fuelStatement';perform neuvetra.m71_keys(a,'issuer,reference,statedQuantityGallons,description,consumptionBasis');perform neuvetra.m74_text(a->'issuer',120);perform neuvetra.m74_text(a->'reference',120);perform neuvetra.m74_quantity(a->'statedQuantityGallons');perform neuvetra.m74_text(a->'description',2000);if a->>'consumptionBasis'<>'dedicated_vehicle_consumed_no_adjustments' then raise exception 'fuel basis invalid' using errcode='22023';end if;end if;
if r->'mileageStatement'<>'null' then a:=r->'mileageStatement';perform neuvetra.m71_keys(a,'issuer,reference,statedDistanceMiles,description,distanceBasis');perform neuvetra.m74_text(a->'issuer',120);perform neuvetra.m74_text(a->'reference',120);perform neuvetra.m74_quantity(a->'statedDistanceMiles');perform neuvetra.m74_text(a->'description',2000);if a->>'distanceBasis'<>'dedicated_vehicle_annual_distance' then raise exception 'distance basis invalid' using errcode='22023';end if;end if;end $function$

CREATE OR REPLACE FUNCTION neuvetra.m75_current_reconciliation(target_company uuid, review_override jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
declare coverage jsonb; workpapers jsonb; roster jsonb; reviews jsonb;
begin
select v.payload||jsonb_build_object('review',r.payload) into coverage from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on v.company_id=h.company_id and v.id=h.version_id left join neuvetra.corporate_inventory_reviews r on r.company_id=v.company_id and r.version_id=v.id where h.company_id=target_company;
select coalesce(jsonb_agg(v.payload||jsonb_build_object('review',r.payload) order by h.id),'[]') into workpapers from neuvetra.mobile_diesel_heads h join neuvetra.mobile_diesel_versions v on v.company_id=h.company_id and v.id=h.version_id left join neuvetra.mobile_diesel_reviews r on r.company_id=v.company_id and r.version_id=v.id where h.company_id=target_company;
select v.payload into roster from neuvetra.controlled_fleet_heads h join neuvetra.controlled_fleet_versions v on v.company_id=h.company_id and v.id=h.version_id where h.company_id=target_company;
select coalesce(jsonb_agg(r.payload order by r.reviewed_at,r.id),'[]') into reviews from neuvetra.controlled_fleet_reviews r where r.company_id=target_company;
if review_override is not null and review_override<>'null'::jsonb then reviews:=reviews||jsonb_build_array(review_override);end if;
return neuvetra.m75_derive_reconciliation(target_company,coverage,workpapers,roster,reviews);
end $function$

CREATE OR REPLACE FUNCTION neuvetra.m75_derive_reconciliation(target_company uuid, coverage jsonb, workpapers jsonb, version_payload jsonb, reviews jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra'
AS $function$
declare
 deps jsonb; pins jsonb; global_findings jsonb:='[]'; rows_json jsonb:='[]'; all_findings jsonb;
 activity jsonb:=version_payload->'activity'; statement jsonb:=activity->'rosterStatement';
 sources jsonb; source jsonb; asset jsonb; head jsonb; works jsonb; findings jsonb; screening jsonb;
 row_key text; source_id text; worksheet_ids jsonb; mapped_sources text[]:='{}'; used_worksheets text[]:='{}';
 entity_label text; facility_label text; current_review jsonb; final_status text; base jsonb;
begin
select coalesce(jsonb_agg(jsonb_build_object('worksheetId',w->'worksheetId','sourceId',w#>'{activity,binding,sourceId}','assetId',w#>'{activity,vehicle,assetId}','version',jsonb_build_object('id',w->'id','sha256',w->'versionSha256'),'decision',case when coalesce(w->'review','null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',w#>'{review,id}','sha256',w#>'{review,decisionSha256}') end) order by (w->>'worksheetId') collate "C"),'[]'::jsonb) into pins from jsonb_array_elements(workpapers) w;
deps:=jsonb_build_object('coveragePin',case when coalesce(coverage,'null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',coverage->'id','sha256',coverage->'versionSha256') end,'coverageReviewPin',case when coalesce(coverage->'review','null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',coverage#>'{review,id}','sha256',coverage#>'{review,decisionSha256}') end,'workpaperPins',pins);
deps:=deps||jsonb_build_object('dependencySha256',neuvetra.m67_hash(deps));

if coverage#>>'{review,decision}' is distinct from 'accepted_bounded_internal' then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','coverage_review_required','rowKey',null,'message','The exact current corporate coverage version needs bounded internal acceptance.','blocking',true)); end if;
if coalesce(version_payload,'null'::jsonb)='null'::jsonb then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','roster_missing','rowKey',null,'message','No controlled-fleet roster has been saved.','blocking',true)); else
 global_findings:=global_findings||(version_payload->'findings');
if version_payload#>>'{dependencies,dependencySha256}' is distinct from deps->>'dependencySha256' then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','dependency_stale','rowKey',null,'message','Corporate coverage or a mobile workpaper/review changed; save a current roster successor.','blocking',true)); end if;
if activity->>'coverageVersionId' is distinct from coverage->>'id' or activity->>'coverageVersionSha256' is distinct from coverage->>'versionSha256' then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','coverage_stale','rowKey',null,'message','The roster is not bound to the current corporate coverage version.','blocking',true)); end if;
end if;
select coalesce(jsonb_agg(s order by n),'[]') into sources from jsonb_array_elements(coverage#>'{snapshot,sources}') with ordinality x(s,n) where s->>'domain'='mobile_combustion';
for asset in select a from jsonb_array_elements(coalesce(statement->'assets','[]'::jsonb)) with ordinality x(a,n) order by n loop
 row_key:='roster:'||(asset->>'rowId');
 select coalesce(jsonb_agg(f order by n),'[]') into findings from jsonb_array_elements(version_payload->'findings') with ordinality x(f,n) where f->>'rowKey'=row_key;
 select l->>'sourceId' into source_id from jsonb_array_elements(activity->'links') with ordinality x(l,n) where l->>'rowId'=asset->>'rowId' order by n desc limit 1;
 select s into source from jsonb_array_elements(sources) s where s->>'id'=source_id limit 1;
 select coalesce(jsonb_agg(w order by n),'[]') into works from jsonb_array_elements(workpapers) with ordinality x(w,n) where w#>>'{activity,binding,sourceId}'=source_id;
 if source_id is not null then mapped_sources:=array_append(mapped_sources,source_id);end if;
 for head in select w from jsonb_array_elements(works) w loop used_worksheets:=array_append(used_worksheets,head->>'worksheetId');end loop;
if source_id is not null and source is null then findings:=findings||jsonb_build_array(jsonb_build_object('code','source_missing','rowKey',row_key,'message','The mapped source is absent from current corporate coverage.','blocking',true)); end if;
if source is not null and neuvetra.m75_source_eligible(coverage,source) is not true then findings:=findings||jsonb_build_array(jsonb_build_object('code','source_ineligible','rowKey',row_key,'message','The current corporate mobile source or boundary is not eligible for M74.','blocking',true)); end if;
if source is not null then
 select s into screening from jsonb_array_elements(coverage#>'{snapshot,coverageItems}') with ordinality x(s,n) where s->>'sourceId'=source->>'id' and s->>'domain'='mobile_combustion' order by n limit 1;
if screening is null or screening->>'disposition' is distinct from 'included_activity' then findings:=findings||jsonb_build_array(jsonb_build_object('code','source_screening_unresolved','rowKey',row_key,'message','The current corporate mobile-source screening must be included activity; missing, estimate, excluded and not-applicable assertions remain unresolved.','blocking',true)); end if;
end if;
if jsonb_array_length(works)=0 and source is not null then if jsonb_array_length(workpapers)>=3 then findings:=findings||jsonb_build_array(jsonb_build_object('code','capacity_blocked','rowKey',row_key,'message','The M74 three-workpaper capacity is full.','blocking',true)); else findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_missing','rowKey',row_key,'message','No current M74 workpaper exists for this vehicle.','blocking',true)); end if;end if;
if jsonb_array_length(works)>1 then findings:=findings||jsonb_build_array(jsonb_build_object('code','duplicate_workpaper','rowKey',row_key,'message','Multiple M74 workpapers map to this roster source.','blocking',true)); end if;
for head in select w from jsonb_array_elements(works) with ordinality x(w,n) order by n loop
if asset->'assetId' is distinct from head#>'{activity,vehicle,assetId}' then findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_asset_conflict','rowKey',row_key,'message','Roster and workpaper asset identities differ.','blocking',true)); end if;
if asset->'entityId' is distinct from head#>'{activity,binding,entityId}' or asset->'facilityId' is distinct from head#>'{activity,binding,facilityId}' or asset->'vehicleClass' is distinct from head#>'{activity,vehicle,vehicleClass}' or asset->'modelYear' is distinct from head#>'{activity,vehicle,modelYear}' or asset->'fuel' is distinct from head#>'{activity,vehicle,fuel}' or asset->'controlBasis' is distinct from head#>'{activity,vehicle,controlBasis}' or asset->'period' is distinct from head#>'{activity,period}' then findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_fact_conflict','rowKey',row_key,'message','Roster and workpaper boundary or vehicle facts differ.','blocking',true)); end if;
if coalesce(head->'calculation','null'::jsonb)='null'::jsonb or coalesce(head#>>'{activityStatus,fuel}','') not in('entered','explicit_zero') or coalesce(head#>>'{activityStatus,mileage}','') not in('entered','explicit_zero') or exists(select 1 from jsonb_array_elements(head->'findings') f where f->>'code' not in('scope1_incomplete','method_not_released')) then findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_incomplete','rowKey',row_key,'message','The current workpaper has incomplete, discrepant or unsupported activity/evidence.','blocking',true)); end if;
if head#>>'{activity,binding,coverageVersionId}' is distinct from coverage->>'id' or head#>>'{activity,binding,coverageVersionSha256}' is distinct from coverage->>'versionSha256' then findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_stale','rowKey',row_key,'message','The workpaper is bound to an older corporate coverage version.','blocking',true)); end if;
if head#>>'{review,decision}' is distinct from 'accepted_bounded_internal' then findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_review_required','rowKey',row_key,'message','The exact current workpaper needs bounded internal acceptance.','blocking',true)); end if;
end loop;
select coalesce(jsonb_agg(w->'worksheetId' order by (w->>'worksheetId') collate "C"),'[]') into worksheet_ids from jsonb_array_elements(works) w;
select e->>'legalName' into entity_label from jsonb_array_elements(coverage#>'{snapshot,entities}') e where e->>'id'=asset->>'entityId' limit 1;
select f->>'name' into facility_label from jsonb_array_elements(coverage#>'{snapshot,facilities}') f where f->>'id'=asset->>'facilityId' limit 1;
rows_json:=rows_json||jsonb_build_array(jsonb_build_object('rowKey',row_key,'rosterRowId',asset->'rowId','sourceId',source_id,'assetId',asset->'assetId','worksheetIds',worksheet_ids,'entityLabel',entity_label,'facilityLabel',facility_label,'sourceLabel',source->>'name','status',neuvetra.m75_row_status(findings),'findings',findings));
end loop;
for source in select s from jsonb_array_elements(sources) with ordinality x(s,n) where not(s->>'id'=any(mapped_sources)) order by n loop
 row_key:='source:'||(source->>'id');findings:='[]';
findings:=findings||jsonb_build_array(jsonb_build_object('code','orphan_source','rowKey',row_key,'message','Current corporate mobile source is absent from the declared roster mapping.','blocking',true));
 select coalesce(jsonb_agg(w order by n),'[]') into works from jsonb_array_elements(workpapers) with ordinality x(w,n) where w#>>'{activity,binding,sourceId}'=source->>'id';
 for head in select w from jsonb_array_elements(works) w loop used_worksheets:=array_append(used_worksheets,head->>'worksheetId');end loop;
 select coalesce(jsonb_agg(w->'worksheetId' order by (w->>'worksheetId') collate "C"),'[]') into worksheet_ids from jsonb_array_elements(works) w;
 select e->>'legalName' into entity_label from jsonb_array_elements(coverage#>'{snapshot,entities}') e where e->>'id'=source->>'entityId' limit 1;
 select f->>'name' into facility_label from jsonb_array_elements(coverage#>'{snapshot,facilities}') f where f->>'id'=source->>'facilityId' limit 1;
 rows_json:=rows_json||jsonb_build_array(jsonb_build_object('rowKey',row_key,'rosterRowId',null,'sourceId',source->'id','assetId',works#>'{0,activity,vehicle,assetId}','worksheetIds',worksheet_ids,'entityLabel',entity_label,'facilityLabel',facility_label,'sourceLabel',source->>'name','status','orphan_source','findings',findings));
end loop;
for head in select w from jsonb_array_elements(workpapers) with ordinality x(w,n) where not(w->>'worksheetId'=any(used_worksheets)) order by n loop
 row_key:='workpaper:'||(head->>'worksheetId');findings:='[]';
findings:=findings||jsonb_build_array(jsonb_build_object('code','orphan_workpaper','rowKey',row_key,'message','Current M74 workpaper is absent from the declared roster mapping.','blocking',true));
 rows_json:=rows_json||jsonb_build_array(jsonb_build_object('rowKey',row_key,'rosterRowId',null,'sourceId',head#>'{activity,binding,sourceId}','assetId',head#>'{activity,vehicle,assetId}','worksheetIds',jsonb_build_array(head->'worksheetId'),'entityLabel',null,'facilityLabel',null,'sourceLabel',null,'status','orphan_workpaper','findings',findings));
end loop;
select coalesce(jsonb_agg(r order by (r->>'rowKey') collate "C"),'[]') into rows_json from jsonb_array_elements(rows_json) r;
select global_findings||coalesce(jsonb_agg(f order by n,k),'[]') into all_findings from jsonb_array_elements(rows_json) with ordinality x(r,n) cross join lateral jsonb_array_elements(r->'findings') with ordinality y(f,k);
select r into current_review from jsonb_array_elements(reviews) with ordinality x(r,n) where r->>'versionId'=version_payload->>'id' and r->>'versionSha256'=version_payload->>'versionSha256' and r#>>'{dependencies,dependencySha256}'=deps->>'dependencySha256' order by n limit 1;
if current_review is null or current_review->>'decision' is distinct from 'accepted_bounded_reconciliation' then all_findings:=all_findings||jsonb_build_array(jsonb_build_object('code','roster_review_required','rowKey',null,'message','The exact current fleet reconciliation needs independent internal acceptance.','blocking',true)); end if;
final_status:=case when not exists(select 1 from jsonb_array_elements(all_findings) f where f->>'blocking'='true' and f->>'code'<>'roster_review_required') and current_review->>'decision'='accepted_bounded_reconciliation' then 'reconciled_bounded_synthetic' else 'blocked' end;
base:=jsonb_build_object('profile','m75-fleet-reconciliation-v1','companyId',target_company,'period',jsonb_build_object('start','2025-01-01','endExclusive','2026-01-01'),
'rosterPin',case when coalesce(version_payload,'null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',version_payload->'id','sha256',version_payload->'versionSha256') end,
'rosterReviewPin',case when current_review is null then 'null'::jsonb else jsonb_build_object('id',current_review->'id','sha256',current_review->'decisionSha256') end,
'coveragePin',deps->'coveragePin','coverageReviewPin',deps->'coverageReviewPin','workpaperPins',deps->'workpaperPins','rows',rows_json,'findings',all_findings,
'counts',jsonb_build_object('evidenceRows',jsonb_array_length(coalesce(statement->'assets','[]'::jsonb)),
'declaredUniqueKnownAssets',(select count(distinct a->>'assetId') from jsonb_array_elements(coalesce(statement->'assets','[]'::jsonb)) a where nullif(a->>'assetId','') is not null),
'currentMobileSources',jsonb_array_length(sources),'currentWorkpaperStreams',jsonb_array_length(workpapers),
'reconciledRows',(select count(*) from jsonb_array_elements(rows_json) r where r->>'status'='matched_reviewed'),
'blockingFindings',(select count(*) from jsonb_array_elements(all_findings) f where f->>'blocking'='true')),
'status',final_status,'dependencySha256',deps->>'dependencySha256',
'limitations','["synthetic_only","declared_roster_reconciliation_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","no_emissions_aggregation","requirements_not_determined","no_external_assurance"]'::jsonb,
'synthetic',true,'scope1Completeness','incomplete','corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','emissionsTotals',null);
return base||jsonb_build_object('contentSha256',neuvetra.m67_hash(base));
end $function$

CREATE OR REPLACE FUNCTION neuvetra.m75_roster_findings(activity jsonb, coverage jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
 out_findings jsonb := '[]'::jsonb;
 statement jsonb := activity->'rosterStatement';
 asset jsonb;
 row_key text;
 source_id text;
 expected_entities jsonb;
 supported boolean;
 identity_row record;
begin

if statement is null or statement='null'::jsonb then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','roster_statement_missing','rowKey',null,'message','The declared controlled-vehicle roster statement is missing.','blocking',true)); return out_findings; end if;
if activity->>'manualConfirmation' is distinct from 'true' then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','roster_unconfirmed','rowKey',null,'message','Confirm the complete synthetic roster declaration.','blocking',true)); end if;
if jsonb_array_length(statement->'assets')=0 then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','roster_empty','rowKey',null,'message','An empty roster cannot establish a zero fleet.','blocking',true)); end if;
if statement->>'completeness' is distinct from 'declared_complete' then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','roster_not_declared_complete','rowKey',null,'message','The roster population is partial or unknown.','blocking',true)); end if;
if statement->>'allTripLocationsIncluded' is distinct from 'true' then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','trip_locations_incomplete','rowKey',null,'message','The roster declaration must cover all trip locations, including interstate travel.','blocking',true)); end if;
select coalesce(jsonb_agg(to_jsonb(e->>'id') order by (e->>'id') collate "C"),'[]'::jsonb) into expected_entities from jsonb_array_elements(coverage#>'{snapshot,entities}') e;
if statement->'coveredEntityIds' is distinct from expected_entities then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','entity_population_incomplete','rowKey',null,'message','Every entity in the bound corporate register needs a roster population declaration.','blocking',true)); end if;
for asset in select a from jsonb_array_elements(statement->'assets') with ordinality x(a,n) order by n loop
 row_key := 'roster:'||(asset->>'rowId');
 select l->>'sourceId' into source_id from jsonb_array_elements(activity->'links') with ordinality x(l,n) where l->>'rowId'=asset->>'rowId' order by n desc limit 1;
 if nullif(asset->>'entityId','') is not null and not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,entities}') e where e->>'id'=asset->>'entityId') then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','unknown_entity','rowKey',row_key,'message','The declared entity is not in the bound corporate register.','blocking',true)); end if;
 if nullif(asset->>'facilityId','') is not null and not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,facilities}') f where f->>'id'=asset->>'facilityId' and (nullif(asset->>'entityId','') is null or f->>'entityId'=asset->>'entityId')) then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','facility_conflict','rowKey',row_key,'message','The declared facility is missing or belongs to another entity.','blocking',true)); end if;
 if nullif(source_id,'') is not null and not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,sources}') s where s->>'id'=source_id and s->>'domain'='mobile_combustion') then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','source_conflict','rowKey',row_key,'message','The mapped source is missing or is not mobile combustion.','blocking',true)); end if;
 if nullif(asset->>'assetId','') is null then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','asset_identity_unknown','rowKey',row_key,'message','Stable vehicle identity is unknown.','blocking',true)); end if;
 if nullif(asset->>'entityId','') is null or nullif(asset->>'facilityId','') is null or coalesce(asset->'period','null'::jsonb)='null'::jsonb or asset->>'mode'='unknown' or nullif(asset->>'vehicleClass','') is null or asset->>'modelYear' is null or nullif(asset->>'fuel','') is null or asset->>'controlBasis'='unknown' or nullif(asset->>'classificationBasis','') is null or nullif(asset->>'controlExplanation','') is null then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','vehicle_facts_unknown','rowKey',row_key,'message','One or more required vehicle, period, classification or control facts are unknown.','blocking',true)); end if;
 supported := coalesce(asset->>'mode'='on_road' and asset->>'vehicleClass'='Medium- and Heavy-Duty Vehicles' and (asset->>'modelYear')::integer between 2007 and 2022 and asset->>'fuel'='Fossil Diesel' and asset->>'controlBasis'='owned_operational_control_full_year' and asset->'period'=jsonb_build_object('start','2025-01-01','endExclusive','2026-01-01'),false);
 if not supported and nullif(asset->>'assetId','') is not null and asset->>'mode'<>'unknown' and nullif(asset->>'vehicleClass','') is not null and asset->>'modelYear' is not null and nullif(asset->>'fuel','') is not null and asset->>'controlBasis'<>'unknown' and coalesce(asset->'period','null'::jsonb)<>'null'::jsonb then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','vehicle_profile_unsupported','rowKey',row_key,'message','The controlled vehicle is outside the current M74 candidate profile.','blocking',true)); end if;
 if nullif(source_id,'') is null then out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','source_missing','rowKey',row_key,'message','No current corporate mobile source is mapped to this roster row.','blocking',true)); end if;
end loop;
-- Match JavaScript Map insertion order: first occurrence of each identity,
-- then every occurrence's original asset/alias order (including duplicates).
for identity_row in
 with assets as(select a,n from jsonb_array_elements(statement->'assets') with ordinality x(a,n)),
 identities as(
  select a->>'assetId' identity,a->>'rowId' row_id,n asset_order,0::bigint alias_order from assets where nullif(a->>'assetId','') is not null
  union all select alias#>>'{}',a->>'rowId',n,k from assets cross join lateral jsonb_array_elements(a->'aliases') with ordinality x(alias,k)
 ), positions as(select *,row_number() over(order by asset_order,alias_order) position from identities),
 repeated as(select *,count(*) over(partition by identity) occurrences,min(position) over(partition by identity) first_position from positions)
 select identity,row_id from repeated where occurrences>1 order by first_position,position
loop

 out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','duplicate_asset_identity','rowKey','roster:'||identity_row.row_id,'message','Declared asset identity '||identity_row.identity||' appears in multiple roster rows.','blocking',true));
end loop;
for identity_row in
 with assets as(select a,n from jsonb_array_elements(statement->'assets') with ordinality x(a,n)),
 mapped as(select a->>'rowId' row_id,n,(select l->>'sourceId' from jsonb_array_elements(activity->'links') with ordinality x(l,k) where l->>'rowId'=a->>'rowId' order by k desc limit 1) identity from assets),
 repeated as(select *,count(*) over(partition by identity) occurrences,min(n) over(partition by identity) first_position from mapped where nullif(identity,'') is not null)
 select identity,row_id from repeated where occurrences>1 order by first_position,n
loop

 out_findings := out_findings || jsonb_build_array(jsonb_build_object('code','duplicate_source_mapping','rowKey','roster:'||identity_row.row_id,'message','Corporate mobile source '||identity_row.identity||' is mapped to multiple roster rows.','blocking',true));
end loop;
return out_findings;
end $function$

CREATE OR REPLACE FUNCTION neuvetra.m75_row_status(findings jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare codes text[]; code text;
begin select coalesce(array_agg(f->>'code'),'{}') into codes from jsonb_array_elements(findings) f where f->>'blocking'='true';
if exists(select 1 from unnest(codes) c where left(c,10)='duplicate_') then return 'duplicate';end if;
if 'vehicle_profile_unsupported'=any(codes) then return 'unsupported';end if;
if exists(select 1 from unnest(codes) c where position('unknown' in c)>0 or position('unconfirmed' in c)>0) then return 'unknown';end if;
if 'orphan_source'=any(codes) then return 'orphan_source';end if;
if 'orphan_workpaper'=any(codes) then return 'orphan_workpaper';end if;
if 'source_missing'=any(codes) then return 'missing_source';end if;
if exists(select 1 from unnest(codes) c where position('stale' in c)>0) then return 'stale';end if;
if 'capacity_blocked'=any(codes) then return 'capacity_blocked';end if;
if 'workpaper_missing'=any(codes) then return 'missing_workpaper';end if;
if cardinality(codes)>0 then return 'workpaper_incomplete';end if;
return 'matched_reviewed';end $function$

CREATE OR REPLACE FUNCTION neuvetra.m75_source_eligible(coverage jsonb, source jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare entity jsonb; facility jsonb; boundary jsonb; relationship jsonb; current_id text; seen text[]:='{}'; item jsonb;
begin
select e into entity from jsonb_array_elements(coverage#>'{snapshot,entities}') e where e->>'id'=source->>'entityId' limit 1;
select f into facility from jsonb_array_elements(coverage#>'{snapshot,facilities}') f where f->>'id'=source->>'facilityId' limit 1;
select b into boundary from jsonb_array_elements(coverage#>'{snapshot,boundaryDecisions}') with ordinality x(b,n) where b->>'entityId'=source->>'entityId' and b->>'start'='2025-01-01' and b->>'endExclusive'='2026-01-01' order by n limit 1;
if coverage#>>'{snapshot,consolidationApproach}' is distinct from 'operational_control' or entity is null or facility is null or facility->>'entityId' is distinct from entity->>'id' or entity->>'countryCode' is distinct from 'US' or entity->>'regionCode' is distinct from 'CA' or facility->>'countryCode' is distinct from 'US' or facility->>'regionCode' is distinct from 'CA' then return false; end if;
foreach item in array array[coverage#>'{snapshot,period}',entity,facility,source] loop
 if item->>'start' is distinct from '2025-01-01' or item->>'endExclusive' is distinct from '2026-01-01' then return false; end if;
end loop;

if boundary is null or boundary->>'disposition' is distinct from 'included_activity' or nullif(btrim(boundary->>'reason'),'') is null or not exists(select 1 from jsonb_array_elements(boundary->'evidenceRefs') r where r->>'artifactId'='71000000-0000-4000-8000-000000000900' and r->>'expectedSha256'='4fe7dc12d8f253f8d3cb1fd7fba2eade05f3d605ad7cb95376cca9d957afe5c7' and r->>'locator'='synthetic-register:entities-and-screening') then return false;end if;
current_id:=entity->>'id';while current_id is not null and current_id<>'' loop
 if current_id=any(seen) then return false;end if;seen:=array_append(seen,current_id);
 select r into relationship from jsonb_array_elements(coverage#>'{snapshot,relationships}') with ordinality x(r,n) where r->>'childEntityId'=current_id order by n limit 1;
 if relationship is null then exit;end if;
if relationship->>'start' is distinct from '2025-01-01' or relationship->>'endExclusive' is distinct from '2026-01-01' or relationship->>'ownershipPercent' is distinct from '100' or nullif(btrim(relationship->>'controlFacts'),'') is null or not exists(select 1 from jsonb_array_elements(relationship->'evidenceRefs') r where r->>'artifactId'='71000000-0000-4000-8000-000000000900' and r->>'expectedSha256'='4fe7dc12d8f253f8d3cb1fd7fba2eade05f3d605ad7cb95376cca9d957afe5c7' and r->>'locator'='synthetic-register:entities-and-screening') then return false;end if;
 current_id:=relationship->>'parentEntityId';
end loop;return true;end $function$

CREATE OR REPLACE FUNCTION neuvetra.m76_activity_valid(a jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra'
AS $function$declare s jsonb:=a->'rosterStatement';e jsonb;r jsonb;l jsonb;k text;ids jsonb;uuid_re text:='^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';id_re text:='^[A-Z0-9][A-Z0-9._-]{0,63}$';date_re text:='^[0-9]{4}-[0-9]{2}-[0-9]{2}$';begin
if not neuvetra.m76_exact_keys(a,array['profile','coverageVersionId','coverageVersionSha256','period','rosterStatement','manualConfirmation','links'])or a->>'profile'is distinct from 'synthetic-stationary-equipment-v1'or a->>'coverageVersionId'!~uuid_re or a->>'coverageVersionSha256'!~'^[0-9a-f]{64}$'or a->'period'is distinct from '{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb or jsonb_typeof(a->'manualConfirmation')is distinct from 'boolean'or jsonb_typeof(a->'links')is distinct from 'array'or jsonb_array_length(a->'links')>25 then return false;end if;
if s='null'::jsonb then return a->'links'='[]'::jsonb;end if;
if not neuvetra.m76_exact_keys(s,array['issuer','reference','description','discoveryBasis','coveredEntityIds','coveredFacilityIds','completeness','allControlledLocationsIncluded','assets'])or not neuvetra.m76_text_valid(s->'issuer',120)or not neuvetra.m76_text_valid(s->'reference',120)or not neuvetra.m76_text_valid(s->'description',2000)or not neuvetra.m76_text_valid(s->'discoveryBasis',2000)or s->>'completeness'not in('declared_complete','partial','unknown')or jsonb_typeof(s->'allControlledLocationsIncluded')is distinct from 'boolean'or jsonb_typeof(s->'assets')is distinct from 'array'or jsonb_array_length(s->'assets')>25 then return false;end if;
foreach k in array array['coveredEntityIds','coveredFacilityIds']loop ids:=s->k;if jsonb_typeof(ids)is distinct from 'array'or exists(select 1 from jsonb_array_elements(ids)x where jsonb_typeof(x)<>'string'or x#>>'{}'!~uuid_re)or ids is distinct from(select coalesce(jsonb_agg(x order by x#>>'{}'collate "C"),'[]')from(select distinct x from jsonb_array_elements(ids)x)q)then return false;end if;end loop;
for e in select x from jsonb_array_elements(s->'assets')x loop
if not neuvetra.m76_exact_keys(e,array['rowId','equipmentId','aliases','identifierBasis','entityId','facilityId','period','equipmentType','fuel','controlBasis','classificationBasis','controlExplanation','meterRelationship'])or e->>'rowId'!~uuid_re or(e->'equipmentId'<>'null'::jsonb and(jsonb_typeof(e->'equipmentId')<>'string'or e->>'equipmentId'!~id_re))or jsonb_typeof(e->'aliases')is distinct from 'array'or jsonb_array_length(e->'aliases')>8 or e->>'equipmentType'not in('boiler','space_heater','stationary_emergency_generator','other','unknown')or e->>'controlBasis'not in('owned_operational_control_full_year','other_control_arrangement','unknown')then return false;end if;
foreach k in array array['entityId','facilityId']loop if e->k<>'null'::jsonb and(jsonb_typeof(e->k)<>'string'or e->>k!~uuid_re)then return false;end if;end loop;
foreach k in array array['identifierBasis','classificationBasis','controlExplanation']loop if e->k<>'null'::jsonb and not neuvetra.m76_text_valid(e->k,500)then return false;end if;end loop;if e->'fuel'<>'null'::jsonb and not neuvetra.m76_text_valid(e->'fuel',100)then return false;end if;
if exists(select 1 from jsonb_array_elements(e->'aliases')x where jsonb_typeof(x)<>'string'or x#>>'{}'!~id_re or x=e->'equipmentId')or e->'aliases'is distinct from(select coalesce(jsonb_agg(x order by x#>>'{}'collate "C"),'[]')from(select distinct x from jsonb_array_elements(e->'aliases')x)q)then return false;end if;
r:=e->'period';if r<>'null'::jsonb then if not neuvetra.m76_exact_keys(r,array['start','endExclusive'])or r->>'start'!~date_re or r->>'endExclusive'!~date_re or to_char(to_date(r->>'start','FXYYYY-MM-DD'),'YYYY-MM-DD')<>r->>'start'or to_char(to_date(r->>'endExclusive','FXYYYY-MM-DD'),'YYYY-MM-DD')<>r->>'endExclusive'or r->>'start'>=r->>'endExclusive'then return false;end if;end if;
r:=e->'meterRelationship';if r<>'null'::jsonb then if not neuvetra.m76_exact_keys(r,array['issuer','meterLabel','measurementBasis','dedicatedToSingleDevice','explanation'])or r->>'measurementBasis'not in('dedicated_single_device_consumption','shared_meter','shared_tank_allocation','stock_derived','other','unknown')or r->'dedicatedToSingleDevice'not in('null'::jsonb,'true'::jsonb,'false'::jsonb)then return false;end if;foreach k in array array['issuer','meterLabel']loop if r->k<>'null'::jsonb and not neuvetra.m76_text_valid(r->k,120)then return false;end if;end loop;if r->'explanation'<>'null'::jsonb and not neuvetra.m76_text_valid(r->'explanation',2000)then return false;end if;end if;end loop;
if(select count(*)from jsonb_array_elements(s->'assets'))<>(select count(distinct x->>'rowId')from jsonb_array_elements(s->'assets')x)then return false;end if;
for l in select x from jsonb_array_elements(a->'links')x loop if not neuvetra.m76_exact_keys(l,array['rowId','sourceId'])or l->>'rowId'!~uuid_re or(l->'sourceId'<>'null'::jsonb and(jsonb_typeof(l->'sourceId')<>'string'or l->>'sourceId'!~uuid_re))then return false;end if;end loop;
return(select count(*)from jsonb_array_elements(a->'links'))=(select count(distinct x->>'rowId')from jsonb_array_elements(a->'links')x)and(select jsonb_agg(x->'rowId'order by x->>'rowId')from jsonb_array_elements(a->'links')x)is not distinct from(select jsonb_agg(x->'rowId'order by x->>'rowId')from jsonb_array_elements(s->'assets')x);
exception when others then return false;end $function$

CREATE OR REPLACE FUNCTION neuvetra.m76_current_reconciliation(target_company uuid, review_override jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare coverage jsonb;roster jsonb;reviews jsonb;begin
select v.payload||jsonb_build_object('review',r.payload)into coverage from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.corporate_inventory_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company;
select v.payload into roster from neuvetra.stationary_equipment_heads h join neuvetra.stationary_equipment_versions v on v.id=h.version_id and v.company_id=h.company_id where h.company_id=target_company;
select coalesce(jsonb_agg(r.payload order by r.reviewed_at,r.id),'[]')into reviews from neuvetra.stationary_equipment_reviews r where r.company_id=target_company;if review_override is not null and review_override<>'null'::jsonb then reviews:=reviews||jsonb_build_array(review_override);end if;
return neuvetra.m76_derive_reconciliation(target_company,coverage,neuvetra.m76_current_workpapers(target_company),roster,reviews);end $function$

CREATE OR REPLACE FUNCTION neuvetra.m76_derive_reconciliation(target_company uuid, coverage jsonb, workpapers jsonb, version_payload jsonb, reviews jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra'
AS $function$
declare
 deps jsonb; pins jsonb; global_findings jsonb:='[]'; rows_json jsonb:='[]'; all_findings jsonb;
 activity jsonb:=version_payload->'activity'; statement jsonb:=activity->'rosterStatement';
 sources jsonb; source jsonb; asset jsonb; head jsonb; works jsonb; findings jsonb; screening jsonb;
 row_key text; source_id text; worksheet_ids jsonb; mapped_sources text[]:='{}'; used_worksheets text[]:='{}';
 entity_label text; facility_label text; current_review jsonb; final_status text; base jsonb;
begin
deps:=neuvetra.m76_dependencies(coverage,workpapers);

if coverage#>>'{review,decision}' is distinct from 'accepted_bounded_internal' then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','coverage_review_required','rowKey',null,'message','The exact current corporate coverage version needs bounded internal acceptance.','blocking',true)); end if;
if coalesce(version_payload,'null'::jsonb)='null'::jsonb then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','roster_missing','rowKey',null,'message','No independent stationary-equipment declaration has been saved.','blocking',true)); else
 global_findings:=global_findings||(version_payload->'findings');
if version_payload#>>'{dependencies,dependencySha256}' is distinct from deps->>'dependencySha256' then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','dependency_stale','rowKey',null,'message','Corporate coverage or a stationary workpaper/review changed; save a current declaration successor.','blocking',true)); end if;
if activity->>'coverageVersionId' is distinct from coverage->>'id' or activity->>'coverageVersionSha256' is distinct from coverage->>'versionSha256' then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','coverage_stale','rowKey',null,'message','The declaration is not bound to current corporate coverage.','blocking',true)); end if;
end if;
select coalesce(jsonb_agg(s order by n),'[]') into sources from jsonb_array_elements(coverage#>'{snapshot,sources}') with ordinality x(s,n) where s->>'domain'='stationary_combustion';
for asset in select a from jsonb_array_elements(coalesce(statement->'assets','[]'::jsonb)) with ordinality x(a,n) order by n loop
 row_key:='roster:'||(asset->>'rowId');
 select coalesce(jsonb_agg(f order by n),'[]') into findings from jsonb_array_elements(version_payload->'findings') with ordinality x(f,n) where f->>'rowKey'=row_key;
 select l->>'sourceId' into source_id from jsonb_array_elements(activity->'links') with ordinality x(l,n) where l->>'rowId'=asset->>'rowId' order by n desc limit 1;
 select s into source from jsonb_array_elements(sources) s where s->>'id'=source_id limit 1;
 select coalesce(jsonb_agg(w order by n),'[]') into works from jsonb_array_elements(workpapers) with ordinality x(w,n) where w#>>'{activity,binding,sourceId}'=source_id;
 if source_id is not null then mapped_sources:=array_append(mapped_sources,source_id);end if;
 for head in select w from jsonb_array_elements(works) w loop used_worksheets:=array_append(used_worksheets,head->>'worksheetId');end loop;
if source_id is not null and source is null then findings:=findings||jsonb_build_array(jsonb_build_object('code','source_missing','rowKey',row_key,'message','The mapped stationary source is absent from current corporate coverage.','blocking',true)); end if;
if source is not null and neuvetra.m76_source_eligible(coverage,source) is not true then findings:=findings||jsonb_build_array(jsonb_build_object('code','source_ineligible','rowKey',row_key,'message','The corporate stationary source or boundary is not eligible for the candidate.','blocking',true)); end if;
if source is not null then
 select s into screening from jsonb_array_elements(coverage#>'{snapshot,coverageItems}') with ordinality x(s,n) where s->>'sourceId'=source->>'id' and s->>'domain'='stationary_combustion' order by n limit 1;
if screening is null or screening->>'disposition' is distinct from 'included_activity' then findings:=findings||jsonb_build_array(jsonb_build_object('code','source_screening_unresolved','rowKey',row_key,'message','Current stationary-source screening must be included activity; missing, estimate, excluded or not-applicable assertions remain unresolved.','blocking',true)); end if;
end if;
if jsonb_array_length(works)=0 and source is not null then if (asset->>'equipmentType' in('boiler','space_heater') and asset->>'fuel'='Natural Gas' and(select count(*)from jsonb_array_elements(workpapers)w where w->>'_family'='natural_gas')>=3) or(asset->>'equipmentType'='stationary_emergency_generator'and asset->>'fuel'='Fossil Distillate Fuel Oil No. 2' and(select count(*)from jsonb_array_elements(workpapers)w where w->>'_family'='stationary_diesel')>=1)then findings:=findings||jsonb_build_array(jsonb_build_object('code','capacity_blocked','rowKey',row_key,'message','The relevant stationary workpaper capacity is full.','blocking',true)); else findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_missing','rowKey',row_key,'message','No current compatible stationary workpaper exists for this equipment.','blocking',true)); end if;end if;
if jsonb_array_length(works)>1 then findings:=findings||jsonb_build_array(jsonb_build_object('code','duplicate_workpaper','rowKey',row_key,'message','Multiple effective workpapers, including cross-family records, map to this stationary source.','blocking',true)); end if;
for head in select w from jsonb_array_elements(works) with ordinality x(w,n) order by n loop
if head->>'_family' is distinct from(case when asset->>'equipmentType' in('boiler','space_heater')and asset->>'fuel'='Natural Gas' then 'natural_gas' when asset->>'equipmentType'='stationary_emergency_generator'and asset->>'fuel'='Fossil Distillate Fuel Oil No. 2' then 'stationary_diesel' else null end)then findings:=findings||neuvetra.m76_f('workpaper_family_conflict',row_key,'Declared equipment/fuel and workpaper family differ.');end if;
if asset->'entityId' is distinct from head#>'{activity,binding,entityId}' or asset->'facilityId' is distinct from head#>'{activity,binding,facilityId}' or asset->>'controlBasis'<>'owned_operational_control_full_year' or asset->'period' is distinct from head#>'{activity,period}'then findings:=findings||neuvetra.m76_f('workpaper_fact_conflict',row_key,'Equipment and workpaper entity, facility, control or period differ.');end if;
if head->>'_family'='stationary_diesel' and(asset->'equipmentId' is distinct from head#>'{activity,equipment,assetId}'or asset->'identifierBasis' is distinct from head#>'{activity,equipment,identifierBasis}'or asset->'equipmentType' is distinct from head#>'{activity,equipment,equipmentType}'or asset->'fuel' is distinct from head#>'{activity,equipment,fuel}'or asset->'controlBasis' is distinct from head#>'{activity,equipment,controlBasis}'or asset->'controlExplanation' is distinct from head#>'{activity,equipment,controlExplanation}')then findings:=findings||neuvetra.m76_f('workpaper_equipment_conflict',row_key,'Generator equipment identity, fuel or control facts differ from the declaration.');end if;
if head#>'{activity,statement}'='null'::jsonb or asset#>>'{meterRelationship,issuer}'is null or asset#>>'{meterRelationship,meterLabel}'is null or lower(head#>>'{activity,statement,issuer}')is distinct from lower(asset#>>'{meterRelationship,issuer}')or lower(head#>>'{activity,statement,meterLabel}')is distinct from lower(asset#>>'{meterRelationship,meterLabel}')then findings:=findings||neuvetra.m76_f('workpaper_meter_conflict',row_key,'Declared consumption evidence issuer/meter and retained workpaper evidence differ.');end if;
if coalesce(head->'calculation','null'::jsonb)='null'::jsonb or exists(select 1 from jsonb_array_elements(head->'findings')f where f->>'code'not in('scope1_incomplete','method_not_released'))then findings:=findings||neuvetra.m76_f('workpaper_incomplete',row_key,'Current workpaper activity/evidence is missing, discrepant, unsupported or unconfirmed.');end if;
if head#>>'{activity,binding,coverageVersionId}' is distinct from coverage->>'id' or head#>>'{activity,binding,coverageVersionSha256}' is distinct from coverage->>'versionSha256' then findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_stale','rowKey',row_key,'message','The current workpaper is bound to older corporate coverage.','blocking',true)); end if;
if head#>>'{review,decision}' is distinct from 'accepted_bounded_internal' then findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_review_required','rowKey',row_key,'message','The exact current stationary workpaper needs separate bounded internal acceptance.','blocking',true)); end if;
end loop;
select coalesce(jsonb_agg(w->'worksheetId' order by (w->>'worksheetId') collate "C"),'[]') into worksheet_ids from jsonb_array_elements(works) w;
select e->>'legalName' into entity_label from jsonb_array_elements(coverage#>'{snapshot,entities}') e where e->>'id'=asset->>'entityId' limit 1;
select f->>'name' into facility_label from jsonb_array_elements(coverage#>'{snapshot,facilities}') f where f->>'id'=asset->>'facilityId' limit 1;
rows_json:=rows_json||jsonb_build_array(jsonb_build_object('rowKey',row_key,'rosterRowId',asset->'rowId','sourceId',source_id,'equipmentId',asset->'equipmentId','worksheetIds',worksheet_ids,'entityLabel',entity_label,'facilityLabel',facility_label,'sourceLabel',source->>'name','status',neuvetra.m76_row_status(findings),'findings',findings));
end loop;
for source in select s from jsonb_array_elements(sources) with ordinality x(s,n) where not(s->>'id'=any(mapped_sources)) order by n loop
 row_key:='source:'||(source->>'id');findings:='[]';
findings:=findings||jsonb_build_array(jsonb_build_object('code','orphan_source','rowKey',row_key,'message','Current corporate stationary source is absent from the equipment declaration.','blocking',true));
 select coalesce(jsonb_agg(w order by n),'[]') into works from jsonb_array_elements(workpapers) with ordinality x(w,n) where w#>>'{activity,binding,sourceId}'=source->>'id';
 for head in select w from jsonb_array_elements(works) w loop used_worksheets:=array_append(used_worksheets,head->>'worksheetId');end loop;
if jsonb_array_length(works)>1 then findings:=findings||neuvetra.m76_f('duplicate_workpaper',row_key,'Multiple current workpaper families map to this stationary source.');end if;
 select coalesce(jsonb_agg(w->'worksheetId' order by (w->>'worksheetId') collate "C"),'[]') into worksheet_ids from jsonb_array_elements(works) w;
 select e->>'legalName' into entity_label from jsonb_array_elements(coverage#>'{snapshot,entities}') e where e->>'id'=source->>'entityId' limit 1;
 select f->>'name' into facility_label from jsonb_array_elements(coverage#>'{snapshot,facilities}') f where f->>'id'=source->>'facilityId' limit 1;
 rows_json:=rows_json||jsonb_build_array(jsonb_build_object('rowKey',row_key,'rosterRowId',null,'sourceId',source->'id','equipmentId',null,'worksheetIds',worksheet_ids,'entityLabel',entity_label,'facilityLabel',facility_label,'sourceLabel',source->>'name','status','orphan_source','findings',findings));
end loop;
for head in select w from jsonb_array_elements(workpapers) with ordinality x(w,n) where not(w->>'worksheetId'=any(used_worksheets)) order by n loop
 row_key:='workpaper:'||(head->>'worksheetId');findings:='[]';
findings:=findings||jsonb_build_array(jsonb_build_object('code','orphan_workpaper','rowKey',row_key,'message','Current stationary workpaper is absent from the equipment declaration/source mapping.','blocking',true));
 rows_json:=rows_json||jsonb_build_array(jsonb_build_object('rowKey',row_key,'rosterRowId',null,'sourceId',head#>'{activity,binding,sourceId}','equipmentId',case when head->>'_family'='stationary_diesel' then head#>'{activity,equipment,assetId}'else 'null'::jsonb end,'worksheetIds',jsonb_build_array(head->'worksheetId'),'entityLabel',null,'facilityLabel',null,'sourceLabel',null,'status','orphan_workpaper','findings',findings));
end loop;
select coalesce(jsonb_agg(r order by (r->>'rowKey') collate "C"),'[]') into rows_json from jsonb_array_elements(rows_json) r;
select global_findings||coalesce(jsonb_agg(f order by n,k),'[]') into all_findings from jsonb_array_elements(rows_json) with ordinality x(r,n) cross join lateral jsonb_array_elements(r->'findings') with ordinality y(f,k);
select r into current_review from jsonb_array_elements(reviews) with ordinality x(r,n) where r->>'versionId'=version_payload->>'id' and r->>'versionSha256'=version_payload->>'versionSha256' and r#>>'{dependencies,dependencySha256}'=deps->>'dependencySha256' order by n limit 1;
if current_review is null or current_review->>'decision' is distinct from 'accepted_bounded_reconciliation' then all_findings:=all_findings||jsonb_build_array(jsonb_build_object('code','roster_review_required','rowKey',null,'message','The exact current stationary reconciliation needs independent internal acceptance.','blocking',true)); end if;
final_status:=case when not exists(select 1 from jsonb_array_elements(all_findings) f where f->>'blocking'='true' and f->>'code'<>'roster_review_required') and current_review->>'decision'='accepted_bounded_reconciliation' then 'reconciled_bounded_synthetic' else 'blocked' end;
base:=jsonb_build_object('profile','m76-stationary-reconciliation-v1','companyId',target_company,'period',jsonb_build_object('start','2025-01-01','endExclusive','2026-01-01'),
'rosterPin',case when coalesce(version_payload,'null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',version_payload->'id','sha256',version_payload->'versionSha256') end,
'rosterReviewPin',case when current_review is null then 'null'::jsonb else jsonb_build_object('id',current_review->'id','sha256',current_review->'decisionSha256') end,
'coveragePin',deps->'coveragePin','coverageReviewPin',deps->'coverageReviewPin','workpaperPins',deps->'workpaperPins','rows',rows_json,'findings',all_findings,
'counts',jsonb_build_object('evidenceRows',jsonb_array_length(coalesce(statement->'assets','[]'::jsonb)),
'declaredUniqueKnownEquipment',(select count(distinct a->>'equipmentId') from jsonb_array_elements(coalesce(statement->'assets','[]'::jsonb)) a where nullif(a->>'equipmentId','') is not null),
'currentStationarySources',jsonb_array_length(sources),'currentWorkpaperStreams',jsonb_array_length(workpapers),
'reconciledRows',(select count(*) from jsonb_array_elements(rows_json) r where r->>'status'='matched_reviewed'),
'blockingFindings',(select count(*) from jsonb_array_elements(all_findings) f where f->>'blocking'='true')),
'status',final_status,'dependencySha256',deps->>'dependencySha256',
'limitations','["synthetic_only","declared_stationary_reconciliation_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","no_emissions_aggregation","requirements_not_determined","no_external_assurance"]'::jsonb,
'synthetic',true,'scope1Completeness','incomplete','corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','emissionsTotals',null);
return base||jsonb_build_object('contentSha256',neuvetra.m67_hash(base));
end $function$

CREATE OR REPLACE FUNCTION neuvetra.m76_diesel_calculation(a jsonb, statement_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare q numeric;co2 numeric;ch4 numeric;n2o numeric;total numeric;i jsonb;body jsonb;begin
if not neuvetra.m76_diesel_can_calculate(a) then return 'null'::jsonb;end if;q:=(a->>'quantityGallons')::numeric;co2:=q*0.138*73.96;ch4:=q*0.138*3*0.001;n2o:=q*0.138*0.60*0.001;total:=co2+ch4*28+n2o*265;
i:=jsonb_build_object('binding',a->'binding','period',a->'period','equipment',a->'equipment','unit',a->'unit','quantityGallons',a->'quantityGallons','statementSha256',statement_hash);
body:=jsonb_build_object('profile','m76-diesel-decimal-result-v1','input',i,'inputSha256',neuvetra.m67_hash(i),'method',neuvetra.m76_diesel_method(),'derivedHhv',jsonb_build_object('quantityMmbtu',neuvetra.m76_diesel_exact(q*0.138),'heatBasis','HHV','basis','default_hhv_estimate'),'gasResults',jsonb_build_object('co2',jsonb_build_object('mass',neuvetra.m76_diesel_exact(co2),'massUnit','kg CO2','co2e',neuvetra.m76_diesel_exact(co2),'co2eUnit','kg CO2e'),'ch4',jsonb_build_object('mass',neuvetra.m76_diesel_exact(ch4),'massUnit','kg CH4','co2e',neuvetra.m76_diesel_exact(ch4*28),'co2eUnit','kg CO2e'),'n2o',jsonb_build_object('mass',neuvetra.m76_diesel_exact(n2o),'massUnit','kg N2O','co2e',neuvetra.m76_diesel_exact(n2o*265),'co2eUnit','kg CO2e')),'total',jsonb_build_object('unrounded',neuvetra.m76_diesel_exact(total),'display',neuvetra.m76_diesel_display(total),'unit','kg CO2e','rounding','half_even_4dp'));
return body||jsonb_build_object('resultSha256',neuvetra.m67_hash(body));end $function$

CREATE OR REPLACE FUNCTION neuvetra.m76_diesel_coverage(target_company uuid, b jsonb, current_required boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare cv record;s jsonb;e jsonb;f jsonb;src jsonb;bd jsonb;rel jsonb;node text;seen text[]:='{}';pair record;begin
perform neuvetra.m71_keys(b,'coverageVersionId,coverageVersionSha256,entityId,facilityId,sourceId,boundaryDecisionId');for pair in select key,value from jsonb_each(b) loop if jsonb_typeof(pair.value)<>'string' or (pair.value#>>'{}') !~ (case when pair.key='coverageVersionSha256' then '^[0-9a-f]{64}$' else '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' end) then raise exception 'invalid binding' using errcode='22023';end if;end loop;
select * into cv from neuvetra.corporate_inventory_versions where company_id=target_company and id=(b->>'coverageVersionId')::uuid;if not found or cv.version_sha256<>b->>'coverageVersionSha256' then raise exception 'coverage binding conflict' using errcode='23505';end if;
if current_required and not exists(select 1 from neuvetra.corporate_inventory_heads where company_id=target_company and version_id=cv.id) then raise exception 'coverage changed' using errcode='23505';end if;
s:=cv.payload->'snapshot';perform neuvetra.m71_snapshot(s,null);if neuvetra.m67_hash(s)<>cv.content_sha256 or neuvetra.m67_hash((cv.payload-'snapshot'-'versionSha256')||jsonb_build_object('profile','synthetic-corporate-coverage-v1'))<>cv.version_sha256 or cv.export_text<>neuvetra.m67_canonical(cv.payload||jsonb_build_object('findings',neuvetra.m71_findings(s),'synthetic',true,'corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','emissionsTotals',null,'review',null)) then raise exception 'coverage integrity failure' using errcode='22023';end if;
select x into e from jsonb_array_elements(s->'entities')x where x->>'id'=b->>'entityId';select x into f from jsonb_array_elements(s->'facilities')x where x->>'id'=b->>'facilityId';select x into src from jsonb_array_elements(s->'sources')x where x->>'id'=b->>'sourceId';select x into bd from jsonb_array_elements(s->'boundaryDecisions')x where x->>'id'=b->>'boundaryDecisionId';
if s->>'consolidationApproach'<>'operational_control' or e is null or f is null or src is null or bd is null or src->>'domain'<>'stationary_combustion' or src->>'entityId'<>e->>'id' or src->>'facilityId'<>f->>'id' or f->>'entityId'<>e->>'id' or bd->>'entityId'<>e->>'id' or e->>'countryCode'<>'US' or e->>'regionCode' is distinct from 'CA' or f->>'countryCode'<>'US' or f->>'regionCode' is distinct from 'CA' or bd->>'disposition'<>'included_activity' or bd->'reason'='null' or jsonb_array_length(bd->'evidenceRefs')=0 then raise exception 'source ineligible' using errcode='22023';end if;
for pair in select value from jsonb_array_elements(jsonb_build_array(e,f,src,bd))loop if pair.value->>'start'<>'2025-01-01' or pair.value->>'endExclusive'<>'2026-01-01' then raise exception 'unsupported period' using errcode='22023';end if;end loop;
node:=e->>'id';loop if node=any(seen) then raise exception 'relationship cycle' using errcode='22023';end if;seen:=array_append(seen,node);select x into rel from jsonb_array_elements(s->'relationships')x where x->>'childEntityId'=node;exit when rel is null;if rel->>'start'<>'2025-01-01' or rel->>'endExclusive'<>'2026-01-01' or rel->>'ownershipPercent' is distinct from '100' or rel->'controlFacts'='null' or jsonb_array_length(rel->'evidenceRefs')=0 then raise exception 'control basis incomplete' using errcode='22023';end if;node:=rel->>'parentEntityId';end loop;
return cv.export_text::jsonb;end $function$

CREATE OR REPLACE FUNCTION neuvetra.m76_diesel_findings(a jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare out jsonb:='[{"code":"scope1_incomplete","message":"This generator subtotal does not cover all stationary, mobile, fugitive or process emissions."},{"code":"method_not_released","message":"Factors and method are development candidates; no reporting or assurance determination."}]';s text:=neuvetra.m76_diesel_activity_status(a);begin
if a->'quantityGallons'='null' then out:=out||'[{"code":"activity_missing","message":"Consumed U.S. gallons are missing; no emissions were calculated."}]';end if;
if a->'statement'='null' then out:=out||'[{"code":"statement_missing","message":"No synthetic consumed-fuel statement is retained."}]';end if;
if s='unconfirmed' then out:=out||'[{"code":"statement_unconfirmed","message":"The synthetic consumption evidence has not been manually confirmed."}]';end if;
if s='discrepancy' then out:=out||'[{"code":"activity_statement_discrepancy","message":"Entered and stated consumption differ; the discrepancy remains unresolved."}]';end if;
if a->>'quantityGallons'='0.000' and not neuvetra.m76_diesel_can_calculate(a) then out:=out||'[{"code":"unsupported_zero","message":"Zero needs matching zero evidence and a no-consumption rationale covering test and maintenance runs."}]';end if;return out;end $function$

CREATE OR REPLACE FUNCTION neuvetra.m76_diesel_render_report(snapshot jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare v jsonb:=snapshot->'version';a jsonb:=v->'activity';c jsonb:=v->'calculation';src jsonb;f jsonb;entity jsonb;facts text;results text;findings text;html text;begin
select x into src from jsonb_array_elements(v#>'{coverageVersion,snapshot,sources}') x where x->>'id'=a#>>'{binding,sourceId}';select x into f from jsonb_array_elements(v#>'{coverageVersion,snapshot,facilities}') x where x->>'id'=a#>>'{binding,facilityId}';select x into entity from jsonb_array_elements(v#>'{coverageVersion,snapshot,entities}') x where x->>'id'=a#>>'{binding,entityId}';
facts:='<dl>'||neuvetra.m76_diesel_pair('Company',v#>>'{coverageVersion,snapshot,companyLabel}')||neuvetra.m76_diesel_pair('Entity',entity->>'legalName')||neuvetra.m76_diesel_pair('Facility',f->>'name')||neuvetra.m76_diesel_pair('Source',src->>'name')||neuvetra.m76_diesel_pair('Equipment ID',a#>>'{equipment,assetId}')||neuvetra.m76_diesel_pair('Identifier basis',a#>>'{equipment,identifierBasis}')||neuvetra.m76_diesel_pair('Equipment type',a#>>'{equipment,equipmentType}')||neuvetra.m76_diesel_pair('Engine type',a#>>'{equipment,engineType}')||neuvetra.m76_diesel_pair('Installation',a#>>'{equipment,stationaryInstallation}')||neuvetra.m76_diesel_pair('Control basis',a#>>'{equipment,controlBasis}')||neuvetra.m76_diesel_pair('Control explanation',a#>>'{equipment,controlExplanation}')||neuvetra.m76_diesel_pair('Fuel',a#>>'{equipment,fuel}')||neuvetra.m76_diesel_pair('Fossil fraction',a#>>'{equipment,fossilFraction}')||neuvetra.m76_diesel_pair('Fuel grade basis',a#>>'{equipment,fuelGradeBasis}')||neuvetra.m76_diesel_pair('Period',(a#>>'{period,start}')||' to '||(a#>>'{period,endExclusive}'))||neuvetra.m76_diesel_pair('Entered consumed U.S. gallons',a->>'quantityGallons')||neuvetra.m76_diesel_pair('Stated consumed U.S. gallons',a#>>'{statement,statedQuantityGallons}')||neuvetra.m76_diesel_pair('Activity status',v->>'activityStatus')||neuvetra.m76_diesel_pair('Manual confirmation',a->>'manualConfirmation')||neuvetra.m76_diesel_pair('Issuer',a#>>'{statement,issuer}')||neuvetra.m76_diesel_pair('Reference',a#>>'{statement,reference}')||neuvetra.m76_diesel_pair('Meter',a#>>'{statement,meterLabel}')||neuvetra.m76_diesel_pair('Measurement basis',a#>>'{statement,measurementBasis}')||neuvetra.m76_diesel_pair('Consumption boundary explanation',a#>>'{statement,consumptionBoundaryExplanation}')||neuvetra.m76_diesel_pair('Default factor eligibility explanation',a#>>'{statement,defaultFactorEligibilityExplanation}')||neuvetra.m76_diesel_pair('Supplier-specific HHV available',a#>>'{statement,supplierSpecificHhvAvailable}')||neuvetra.m76_diesel_pair('Supplier-specific carbon available',a#>>'{statement,supplierSpecificCarbonAvailable}')||neuvetra.m76_diesel_pair('Includes test and maintenance runs',a#>>'{statement,includesTesting}')||neuvetra.m76_diesel_pair('Statement locator',v#>>'{statement,locator}')||neuvetra.m76_diesel_pair('Statement SHA-256',v#>>'{statement,sha256}')||neuvetra.m76_diesel_pair('Unresolved discrepancy explanation',a->>'discrepancyReason')||neuvetra.m76_diesel_pair('No-consumption explanation',a->>'zeroReason')||neuvetra.m76_diesel_pair('Derived HHV MMBtu',c#>>'{derivedHhv,quantityMmbtu}')||neuvetra.m76_diesel_pair('Exact source subtotal kg CO2e',c#>>'{total,unrounded}')||neuvetra.m76_diesel_pair('Displayed source subtotal kg CO2e',c#>>'{total,display}')||neuvetra.m76_diesel_pair('Method',c#>>'{method,id}')||neuvetra.m76_diesel_pair('Method version',c#>>'{method,version}')||neuvetra.m76_diesel_pair('Workbook SHA-256',c#>>'{method,sourceSha256}')||neuvetra.m76_diesel_pair('Factor locators',(select string_agg(x,', ' order by n) from jsonb_array_elements_text(c#>'{method,factorCells}') with ordinality x(x,n)))||neuvetra.m76_diesel_pair('GWP basis',c#>>'{method,gwpAssessment}')||neuvetra.m76_diesel_pair('Rights status',c#>>'{method,rights}')||neuvetra.m76_diesel_pair('Review as captured',coalesce(snapshot#>>'{review,decision}','Unreviewed'))||neuvetra.m76_diesel_pair('Reviewer note',snapshot#>>'{review,note}')||neuvetra.m76_diesel_pair('Correction reason',v->>'correctionReason')||'</dl>';
results:=case when c='null'::jsonb then '<p>No emissions total was calculated. Required compatible activity or evidence is missing, unconfirmed or contradictory.</p>' else '<table><thead><tr><th>Gas</th><th>Mass</th><th>kg CO2e</th></tr></thead><tbody>'||(select string_agg('<tr><th>'||upper(key)||'</th><td>'||neuvetra.m76_diesel_escape(c#>>array['gasResults',key,'mass'])||' '||neuvetra.m76_diesel_escape(c#>>array['gasResults',key,'massUnit'])||'</td><td>'||neuvetra.m76_diesel_escape(c#>>array['gasResults',key,'co2e'])||'</td></tr>','' order by n) from(values('co2',1),('ch4',2),('n2o',3)) gases(key,n))||'</tbody></table>' end;
findings:='<ul>'||(select coalesce(string_agg('<li>'||neuvetra.m76_diesel_escape(x->>'message')||'</li>','' order by n),'') from jsonb_array_elements(v->'findings') with ordinality x(x,n))||'</ul>';
return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src ''none''; style-src ''unsafe-inline''; base-uri ''none''; form-action ''none''"><title>Synthetic stationary generator source report</title><style>body{font:16px/1.5 system-ui;max-width:950px;margin:2rem auto;padding:0 1rem;color:#172f2c;overflow-wrap:anywhere}th,td{padding:.45rem;text-align:left;border-bottom:1px solid #ccd8d0}table{width:100%;border-collapse:collapse}pre{white-space:pre-wrap;font:13px/1.5 monospace}@media print{body{font-size:11pt;margin:0;max-width:none}h2{break-after:avoid}}</style></head><body><h1>Stationary generator subtotal — synthetic internal draft</h1><p>Development candidate. Factors and method are not released. Scope 1 and corporate inventory incomplete. No filing determination or external assurance.</p><h2>Equipment, consumption and evidence</h2>'||facts||'<h2>Gas results</h2>'||results||'<h2>Open findings</h2>'||findings||'<p>Consumed U.S. gallons are converted to HHV MMBtu using the default 0.138 MMBtu/gallon estimate because supplier-specific HHV and carbon data are unavailable. Gas masses and exact total retain computational precision. Only the displayed source subtotal is rounded to four decimals with half-even rounding. Combustion only; upstream emissions and other source families are excluded. No aggregate emissions.</p><details><summary>Exact version and provenance</summary><pre>'||neuvetra.m76_diesel_escape(neuvetra.m67_canonical(snapshot))||'</pre></details></body></html>';end $function$

CREATE OR REPLACE FUNCTION neuvetra.m76_diesel_validate_request(r jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare e jsonb:=r->'equipment';s jsonb:=r->'statement';k text;uuid_re text:='^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';begin
perform neuvetra.m71_keys(r,'profile,binding,period,equipment,unit,quantityGallons,statement,manualConfirmation,discrepancyReason,zeroReason,expectedVersionId,expectedVersionSha256,correctionReason,idempotencyKey');
if r->>'profile' is distinct from 'synthetic-stationary-diesel-v1' or r->'period' is distinct from '{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb or r->>'unit' is distinct from 'US_gallon' or jsonb_typeof(r->'manualConfirmation')is distinct from 'boolean' or jsonb_typeof(r->'idempotencyKey')is distinct from 'string' or r->>'idempotencyKey'!~uuid_re then raise exception 'invalid generator profile'using errcode='22023';end if;
perform neuvetra.m71_keys(e,'assetId,identifierBasis,equipmentType,engineType,stationaryInstallation,controlBasis,controlExplanation,fuel,fossilFraction,fuelGradeBasis');
if jsonb_typeof(e->'assetId')is distinct from 'string'or e->>'assetId'!~'^[A-Z0-9][A-Z0-9._-]{0,63}$'or e->>'equipmentType'is distinct from 'stationary_emergency_generator'or e->>'engineType'is distinct from 'compression_ignition'or e->>'stationaryInstallation'is distinct from 'fixed'or e->>'controlBasis'is distinct from 'owned_operational_control_full_year'or e->>'fuel'is distinct from 'Fossil Distillate Fuel Oil No. 2'or e->>'fossilFraction'is distinct from '1.000'then raise exception 'unsupported generator facts'using errcode='22023';end if;
