select coalesce(string_agg('<li><a href="#evidence-'||neuvetra.m76_html_escape((x->>'id'))||'">'||neuvetra.m76_html_escape((x->>'reference'))||'</a> — '||neuvetra.m76_html_escape((x->>'issuer'))||' · '||neuvetra.m76_html_escape((x->>'locator'))||' · SHA-256 '||neuvetra.m76_html_escape((x->>'sha256'))||'</li>',''order by n),'')into statement_links from jsonb_array_elements((v->'statements'))with ordinality q(x,n);
select coalesce(string_agg('<section id="evidence-'||neuvetra.m76_html_escape(x->>'id')||'"><h3>'||neuvetra.m76_html_escape(x->>'reference')||' · '||neuvetra.m76_html_escape(x->>'issuer')||'</h3><p>'||neuvetra.m76_html_escape(x->>'description')||'</p><details><summary>Exact retained statement</summary><pre>'||neuvetra.m76_html_escape(x->>'text')||'</pre></details></section>',''order by n),'')into evidence_sections from jsonb_array_elements(v->'statements')with ordinality q(x,n);
select coalesce(string_agg('<tr><td data-label="Asset">'||neuvetra.m76_html_escape((x->>'assetId'))||'</td><td data-label="Equipment">'||neuvetra.m76_html_escape(coalesce(labels->>(x->>'equipment'),x->>'equipment'))||'</td><td data-label="Gas">'||neuvetra.m76_html_escape(coalesce((x->>'gas'),'Unknown'))||'</td><td data-label="Charge kg">'||neuvetra.m76_html_escape(coalesce((x->>'capacityKg'),'Unknown'))||'</td><td data-label="Corporate source">'||neuvetra.m76_html_escape(coalesce((select z->>'name'from jsonb_array_elements(coverage#>'{snapshot,sources}')z where z->>'id'=x->>'sourceId'),x->>'sourceId','Unknown'))||'</td><td data-label="Control">'||neuvetra.m76_html_escape(coalesce(labels->>(x->>'controlBasis'),x->>'controlBasis'))||'</td></tr>',''order by n),'')into asset_rows from jsonb_array_elements(coalesce((s#>'{reconciliation,assets}'),'[]'))with ordinality q(x,n);
select coalesce(string_agg('<li>'||neuvetra.m76_html_escape((x->>'message'))||'</li>',''order by n),'')into findings from jsonb_array_elements(coalesce((s#>'{reconciliation,findings}'),(v->'findings')))with ordinality q(x,n);
return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src ''none''; style-src ''unsafe-inline''; base-uri ''none''; form-action ''none''"><title>'||title||'</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:1000px;color:#172f2c;overflow-wrap:anywhere}table{border-collapse:collapse;width:100%}th,td{padding:.4rem;text-align:left;border-bottom:1px solid #ccd8d0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}@media(max-width:600px){thead{display:none}tr{display:block;margin:.8rem 0}td{display:block}td::before{content:attr(data-label);font-weight:600;margin-right:.5rem}}@media print{body{font-size:10pt;margin:0}tr{break-inside:avoid}}</style></head><body><h1>'||title||' — synthetic internal draft</h1><p>Company '||neuvetra.m76_html_escape(company)||' · '||neuvetra.m76_html_escape(label)||'</p><p>'||neuvetra.m76_html_escape(status)||'</p><p>Calendar 2025 · version '||(v->>'version')||' · internal review: '||neuvetra.m76_html_escape(coalesce(labels->>coalesce(s#>>'{review,decision}','unreviewed'),coalesce(s#>>'{review,decision}','unreviewed')))||'.</p><p>No complete Scope 1 or corporate inventory claim. Candidate methods and factors are not released. Requirements are not determined. No external assurance. No emissions aggregation.</p>'||number||'<h2>Retained evidence</h2><ul>'||statement_links||'</ul>'||evidence_sections||'<h2>Physical devices</h2><table><thead><tr><th>Asset</th><th>Equipment</th><th>Gas</th><th>Charge kg</th><th>Corporate source</th><th>Control</th></tr></thead><tbody>'||asset_rows||'</tbody></table><h2>Open findings</h2><ul>'||findings||'</ul><details><summary>Exact retained data and provenance</summary><pre>'||neuvetra.m76_html_escape(neuvetra.m67_canonical(s))||'</pre></details></body></html>';end $function$

CREATE OR REPLACE FUNCTION neuvetra.m77_validate_activity(family text, a jsonb, coverage jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
#variable_conflict use_column
declare s jsonb:=(coverage->'snapshot');b jsonb;src jsonb;e jsonb;f jsonb;bd jsonb;r jsonb;k text;d jsonb;list jsonb;node text;rel jsonb;seen text[]:='{}';begin
if family='source'then perform neuvetra.m71_keys(a,'profile,binding,label,assetId,equipment,gas,capacityKg,calculatorInput,evidenceStatements');if (a->>'profile')is distinct from 'synthetic-fugitive-source-v1'then raise exception 'source profile'using errcode='22023';end if;b:=(a->'binding');perform neuvetra.m71_keys(b,'coverageVersionId,coverageVersionSha256,entityId,facilityId,sourceId,boundaryDecisionId');if (b->>'coverageVersionId')is distinct from (coverage->>'id')or (b->>'coverageVersionSha256')is distinct from (coverage->>'versionSha256')then raise exception 'coverage binding'using errcode='22023';end if;
select x into e from jsonb_array_elements((s->'entities'))x where (x->>'id')=(b->>'entityId');select x into f from jsonb_array_elements((s->'facilities'))x where (x->>'id')=(b->>'facilityId');select x into src from jsonb_array_elements((s->'sources'))x where (x->>'id')=(b->>'sourceId');select x into bd from jsonb_array_elements((s->'boundaryDecisions'))x where (x->>'id')=(b->>'boundaryDecisionId');if e is null or f is null or src is null or bd is null or (src->>'domain')is distinct from 'fugitive'or (src->>'entityId')is distinct from (e->>'id')or (src->>'facilityId')is distinct from (f->>'id')or (f->>'entityId')is distinct from (e->>'id')or (bd->>'entityId')is distinct from (e->>'id')then raise exception 'source binding facts'using errcode='22023';end if;
perform neuvetra.m76_diesel_text((a->'label'),120);perform neuvetra.m77_id((a->'assetId'));if (a->>'equipment')is null or (a->>'equipment')not in('fixed_hvac','fixed_refrigeration','fixed_fire_suppression','portable_fire_suppression','mobile_hvac','mobile_refrigeration','other','unknown')then raise exception 'equipment type'using errcode='22023';end if;if (a->'gas')<>'null'::jsonb then perform neuvetra.m76_diesel_text((a->'gas'),80);end if;if (a->'capacityKg')<>'null'::jsonb then perform neuvetra.m77_kg((a->'capacityKg'));end if;if jsonb_typeof((a->'evidenceStatements'))is distinct from 'array'or jsonb_array_length((a->'evidenceStatements'))>210 then raise exception 'evidence capacity'using errcode='22023';end if;for r in select value from jsonb_array_elements((a->'evidenceStatements'))loop perform neuvetra.m71_keys(r,'reference,issuer,description');perform neuvetra.m77_id((r->'reference'));perform neuvetra.m76_diesel_text((r->'issuer'),120);perform neuvetra.m76_diesel_text((r->'description'),2000);if length((r->>'description'))<20 then raise exception 'evidence statement missing facts'using errcode='22023';end if;end loop;if(select count(distinct (x->>'reference'))from jsonb_array_elements((a->'evidenceStatements'))x)<>jsonb_array_length((a->'evidenceStatements'))then raise exception 'duplicate evidence'using errcode='22023';end if;
if (a->'calculatorInput')<>'null'::jsonb then r:=(a->'calculatorInput');perform neuvetra.m77_calculate(r);if (r->>'asset_id')is distinct from (a->>'assetId')or (r->'equipment')is distinct from (a->'equipment')or (r->'gas')is distinct from (a->'gas')or (r->'opening_capacity')is distinct from (a->'capacityKg')then raise exception 'source input facts conflict'using errcode='22023';end if;if (s->>'consolidationApproach')is distinct from 'operational_control'or (e->>'countryCode')<>'US'or (e->>'regionCode')is distinct from 'CA'or (f->>'countryCode')<>'US'or (f->>'regionCode')is distinct from 'CA'or (bd->>'disposition')<>'included_activity'or (bd->'reason')='null'::jsonb or jsonb_array_length((bd->'evidenceRefs'))=0 then raise exception 'unsupported method corporate facts'using errcode='22023';end if;if jsonb_array_length(src->'evidenceRefs')=0 or s#>>'{period,start}'<>'2025-01-01'or s#>>'{period,endExclusive}'<>'2026-01-01'or not exists(select 1 from jsonb_array_elements(s->'coverageItems')i where i->>'domain'='fugitive'and i->>'sourceId'=src->>'id'and i->>'entityId'=e->>'id'and i->>'disposition'='included_activity'and i->>'start'='2025-01-01'and i->>'endExclusive'='2026-01-01'and i->>'evidenceState'='linked'and i->>'activityDataState'in('entered','explicit_zero')and i->'reason'<>'null'::jsonb and jsonb_array_length(i->'evidenceRefs')>0)then raise exception 'source screening missing'using errcode='22023';end if;for list in select value from jsonb_array_elements(r->'refills')loop if not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')st where st->'reference'=list->'reference'and st->'issuer'=list->'contractor')then raise exception 'servicing evidence contractor mismatch'using errcode='22023';end if;end loop;for list in select value from jsonb_array_elements(jsonb_build_array(e,f,src,bd))loop if (list->>'start')<>'2025-01-01'or (list->>'endExclusive')<>'2026-01-01'then raise exception 'method corporate period'using errcode='22023';end if;end loop;node:=(e->>'id');loop if node=any(seen)then raise exception 'relationship cycle'using errcode='22023';end if;seen:=array_append(seen,node);select x into rel from jsonb_array_elements((s->'relationships'))x where (x->>'childEntityId')=node;exit when rel is null;if (rel->>'start')<>'2025-01-01'or (rel->>'endExclusive')<>'2026-01-01'or (rel->>'ownershipPercent')is distinct from '100'or (rel->'controlFacts')='null'::jsonb or jsonb_array_length((rel->'evidenceRefs'))=0 then raise exception 'incomplete corporate control'using errcode='22023';end if;node:=(rel->>'parentEntityId');end loop;
for k in select (value#>>'{}')from jsonb_each((r->'evidence'))union all select (x->>'reference')from jsonb_array_elements((r->'refills'))x union all select (x->>'evidence')from jsonb_array_elements((r->'releases'))x union all select (r->>'zero_activity_evidence')where (r->'zero_activity_evidence')<>'null'::jsonb loop if not exists(select 1 from jsonb_array_elements((a->'evidenceStatements'))x where (x->>'reference')=k)then raise exception 'unresolved evidence reference'using errcode='22023';end if;end loop;end if;
else perform neuvetra.m71_keys(a,'profile,coverageVersionId,coverageVersionSha256,declaration');if (a->>'profile')is distinct from 'synthetic-fugitive-population-v1'or (a->>'coverageVersionId')is distinct from (coverage->>'id')or (a->>'coverageVersionSha256')is distinct from (coverage->>'versionSha256')then raise exception 'population binding'using errcode='22023';end if;d:=(a->'declaration');if d<>'null'::jsonb then perform neuvetra.m71_keys(d,'issuer,reference,description,discoveryBasis,completeness,coveredEntityIds,coveredFacilityIds,controlledFleetChecked,allControlledLocationsIncluded,assets');perform neuvetra.m76_diesel_text((d->'issuer'),120);perform neuvetra.m77_id((d->'reference'));perform neuvetra.m76_diesel_text((d->'description'),2000);perform neuvetra.m76_diesel_text((d->'discoveryBasis'),2000);if length((d->>'discoveryBasis'))<20 or (d->>'completeness')is null or (d->>'completeness')not in('unknown','partial','declared_complete')or jsonb_typeof((d->'controlledFleetChecked'))is distinct from 'boolean'or jsonb_typeof((d->'allControlledLocationsIncluded'))is distinct from 'boolean'then raise exception 'population discovery facts'using errcode='22023';end if;foreach k in array array['coveredEntityIds','coveredFacilityIds']loop if jsonb_typeof(d->k)is distinct from 'array'or jsonb_array_length(d->k)>25 or(select count(distinct x)from jsonb_array_elements_text(d->k)x)<>jsonb_array_length(d->k)then raise exception 'location declaration capacity/duplicates'using errcode='22023';end if;for node in select value from jsonb_array_elements_text(d->k)loop if node!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'then raise exception 'location UUID'using errcode='22023';end if;end loop;end loop;if jsonb_typeof((d->'assets'))is distinct from 'array'or jsonb_array_length((d->'assets'))>25 then raise exception 'physical population capacity'using errcode='54000';end if;for r in select value from jsonb_array_elements((d->'assets'))loop perform neuvetra.m71_keys(r,'assetId,entityId,facilityId,equipment,gas,capacityKg,controlBasis,explanation,sourceId');perform neuvetra.m77_id((r->'assetId'));if (r->>'equipment')is null or (r->>'equipment')not in('fixed_hvac','fixed_refrigeration','fixed_fire_suppression','portable_fire_suppression','mobile_hvac','mobile_refrigeration','other','unknown')or (r->>'controlBasis')is null or (r->>'controlBasis')not in('owned_operational_control_full_year','unknown','partial_year','other')then raise exception 'asset classification/control facts'using errcode='22023';end if;foreach k in array array['entityId','facilityId','sourceId']loop if r->k<>'null'::jsonb and(jsonb_typeof(r->k)is distinct from 'string'or r->>k!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')or(k='entityId'and r->k='null'::jsonb)then raise exception 'asset corporate UUID'using errcode='22023';end if;end loop;if (r->'gas')<>'null'::jsonb then perform neuvetra.m76_diesel_text((r->'gas'),80);end if;if (r->'capacityKg')<>'null'::jsonb then perform neuvetra.m77_kg((r->'capacityKg'));end if;perform neuvetra.m76_diesel_text((r->'explanation'),2000);if length((r->>'explanation'))<20 then raise exception 'asset facts explanation required'using errcode='22023';end if;end loop;end if;end if;end $function$

CREATE OR REPLACE FUNCTION neuvetra.m78_assert_current_proof(target_company uuid, p jsonb, check_process boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
#variable_conflict use_column
declare x jsonb;actual jsonb;expected jsonb;d text;v jsonb;r jsonb;deps jsonb;bound jsonb;begin
perform neuvetra.m71_keys(p,'priorVersions,coverageVersion,boundCoverageVersions,sourceVersions,fleet,stationary,fugitive,process,policy');if p->'coverageVersion'is distinct from neuvetra.m77_current_coverage(target_company)then raise exception 'current corporate proof changed'using errcode='23505';end if;
select coalesce(jsonb_agg(x order by x#>>'{version,id}'collate "C"),'[]')into expected from(
select jsonb_build_object('family','natural_gas','version',v.payload||jsonb_build_object('review',r.payload))x from neuvetra.stationary_gas_heads h join neuvetra.stationary_gas_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.stationary_gas_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company
union all select jsonb_build_object('family','mobile_diesel','version',v.payload||jsonb_build_object('review',r.payload))from neuvetra.mobile_diesel_heads h join neuvetra.mobile_diesel_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.mobile_diesel_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company
union all select jsonb_build_object('family','stationary_diesel','version',v.payload||jsonb_build_object('review',r.payload))from neuvetra.stationary_diesel_heads h join neuvetra.stationary_diesel_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.stationary_diesel_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company
union all select jsonb_build_object('family','fugitive','version',v.payload||jsonb_build_object('review',r.payload))from neuvetra.fugitive_heads h join neuvetra.fugitive_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.fugitive_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company and h.family='source')q;
if p->'sourceVersions'is distinct from expected then raise exception 'current source proof changed'using errcode='23505';end if;
foreach d in array array['fleet','stationary','fugitive']loop
 if d='fleet'then select v.payload into v from neuvetra.controlled_fleet_heads h join neuvetra.controlled_fleet_versions v on v.id=h.version_id and v.company_id=h.company_id where h.company_id=target_company;actual:=neuvetra.m75_current_reconciliation(target_company);select rr.payload into r from neuvetra.controlled_fleet_reviews rr where rr.company_id=target_company and rr.version_id=(v->>'id')::uuid and rr.payload#>>'{dependencies,dependencySha256}'=actual->>'dependencySha256';
 elsif d='stationary'then select v.payload into v from neuvetra.stationary_equipment_heads h join neuvetra.stationary_equipment_versions v on v.id=h.version_id and v.company_id=h.company_id where h.company_id=target_company;actual:=neuvetra.m76_current_reconciliation(target_company);select rr.payload into r from neuvetra.stationary_equipment_reviews rr where rr.company_id=target_company and rr.version_id=(v->>'id')::uuid and rr.payload#>>'{dependencies,dependencySha256}'=actual->>'dependencySha256';
 else select vv.payload into v from neuvetra.fugitive_heads h join neuvetra.fugitive_versions vv on vv.id=h.version_id and vv.company_id=h.company_id where h.company_id=target_company and h.family='population';deps:=neuvetra.m77_current_dependencies(target_company);select rr.payload into r from neuvetra.fugitive_reviews rr where rr.company_id=target_company and rr.version_id=(v->>'id')::uuid and rr.payload#>>'{dependencies,dependencySha256}'=deps->>'dependencySha256';actual:=neuvetra.m77_reconciliation(target_company,p->'coverageVersion',neuvetra.m77_current_workpapers(target_company),v,r);end if;
 if p->d is distinct from jsonb_build_object('version',v,'review',r,'reconciliation',actual)then raise exception 'current discovery proof changed'using errcode='23505';end if;
end loop;
select jsonb_build_object('version',vv.payload,'review',rr.payload,'proof',vv.proof)into actual from neuvetra.scope1_heads h join neuvetra.scope1_versions vv on vv.id=h.version_id and vv.company_id=h.company_id left join neuvetra.scope1_reviews rr on rr.company_id=vv.company_id and rr.version_id=vv.id where h.company_id=target_company and h.family='process_screen';if check_process and p->'process'is distinct from coalesce(actual,'null'::jsonb)then raise exception 'current process proof changed'using errcode='23505';end if;
select coalesce(jsonb_agg(v.export_text::jsonb||jsonb_build_object('review',r.payload)order by v.id),'[]')into bound from neuvetra.corporate_inventory_versions v left join neuvetra.corporate_inventory_reviews r on r.company_id=v.company_id and r.version_id=v.id where v.company_id=target_company and v.id::text<>p#>>'{coverageVersion,id}'and v.id::text in(select distinct id from(select p#>>'{fleet,version,activity,coverageVersionId}'id union all select p#>>'{stationary,version,activity,coverageVersionId}'union all select p#>>'{fugitive,version,activity,coverageVersionId}'union all select p#>>'{process,version,activity,binding,coverageVersionId}')q);if p->'boundCoverageVersions'is distinct from bound then raise exception 'bound corporate proof mismatch'using errcode='22023';end if;
if p->'policy'<>'null'::jsonb and p->'policy'is distinct from neuvetra.m78_policy()then raise exception 'unadmitted policy'using errcode='22023';end if;if octet_length(neuvetra.m67_canonical(p))>4000000 then raise exception 'proof capacity exceeded'using errcode='22023';end if;
end $function$

CREATE OR REPLACE FUNCTION neuvetra.m78_process_findings(a jsonb, c jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
#variable_conflict use_column
declare out jsonb:='[]';d jsonb:=a->'declaration';x jsonb;l jsonb;e jsonb;g jsonb;id text;k text;group_rows jsonb;locations jsonb;begin
if d='null'::jsonb or d->>'completeness'<>'declared_complete'or d->'allControlledOperationsIncluded'<>'true'::jsonb or a->'manualConfirmation'<>'true'::jsonb then out:=out||jsonb_build_array(neuvetra.m78_finding('process_discovery_incomplete','Complete discovery and evidence confirmation are required.',null,'process_screen'));end if;
select coalesce(jsonb_agg(x->'rowId'order by x->>'rowId'collate "C"),'[]')into locations from jsonb_array_elements(a->'locations')x;
if d<>'null'::jsonb and(d->'coveredEntityIds'is distinct from(select jsonb_agg(x->'id'order by x->>'id'collate "C")from jsonb_array_elements(c#>'{snapshot,entities}')x)or d->'coveredFacilityIds'is distinct from coalesce((select jsonb_agg(x->'id'order by x->>'id'collate "C")from jsonb_array_elements(c#>'{snapshot,facilities}')x),'[]'))then out:=out||jsonb_build_array(neuvetra.m78_finding('process_scope_incomplete','Discovery must cover every retained entity and location.',null,'process_screen'));end if;
for x in select value from jsonb_array_elements(c#>'{snapshot,facilities}')loop if not exists(select 1 from jsonb_array_elements(a->'locations')l where l->'facilityId'=x->'id'and l->'entityId'=x->'entityId')then out:=out||jsonb_build_array(neuvetra.m78_finding('process_location_missing','Retained location has no process inspection.',x->>'id','process_screen'));end if;end loop;
for x in select value from jsonb_array_elements(a->'evidenceStatements')loop if not exists(select 1 from jsonb_array_elements(c#>'{snapshot,entities}')e where e->'id'=x->'entityId')or x->'facilityId'<>'null'::jsonb and not exists(select 1 from jsonb_array_elements(c#>'{snapshot,facilities}')f where f->'id'=x->'facilityId'and f->'entityId'=x->'entityId')then out:=out||jsonb_build_array(neuvetra.m78_finding('process_evidence_location_unknown','Statement location does not resolve.',x->>'reference','process_screen'));end if;end loop;
for l in select value from jsonb_array_elements(a->'locations')loop
 if not exists(select 1 from jsonb_array_elements(c#>'{snapshot,entities}')e where e->'id'=l->'entityId')or l->'facilityId'<>'null'::jsonb and not exists(select 1 from jsonb_array_elements(c#>'{snapshot,facilities}')f where f->'id'=l->'facilityId'and f->'entityId'=l->'entityId')then out:=out||jsonb_build_array(neuvetra.m78_finding('process_location_unknown','Inspection location does not resolve.',l->>'rowId','process_screen'));end if;
 if jsonb_array_length(l->'evidenceReferences')=0 or exists(select 1 from jsonb_array_elements_text(l->'evidenceReferences')r where not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where e->>'reference'=r and e->'entityId'=l->'entityId'and e->'facilityId'=l->'facilityId'))or not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where l->'evidenceReferences'? (e->>'reference')and e->>'purpose'='business_activity')or not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where l->'evidenceReferences'?(e->>'reference')and e->>'purpose'=case when l->'facilityId'='null'::jsonb then 'offsite_discovery'else 'process_inspection'end)then out:=out||jsonb_build_array(neuvetra.m78_finding('process_location_evidence_missing','Inspection requires retained activity and location-matched discovery evidence.',l->>'rowId','process_screen'));end if;
end loop;
for x in select value from jsonb_array_elements(c#>'{snapshot,entities}')loop if not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where e->'entityId'=x->'id'and e->'facilityId'='null'::jsonb and e->>'purpose'='offsite_discovery')then out:=out||jsonb_build_array(neuvetra.m78_finding('process_offsite_evidence_missing','Every entity needs explicit controlled non-facility discovery evidence.',x->>'id','process_screen'));end if;end loop;
foreach k in array array['mineral_products','chemical_production','metal_production','oil_and_gas','waste_treatment','agricultural_biological','other_direct_process']loop select coalesce(jsonb_agg(x),'[]')into group_rows from jsonb_array_elements(a->'assessments')x where x->>'category'=k and x->'discoveredSourceId'='null'::jsonb;if jsonb_array_length(group_rows)<>1 or group_rows#>'{0,locationRowIds}'is distinct from locations then out:=out||jsonb_build_array(neuvetra.m78_finding('process_category_scope_incomplete','Every category requires one full-discovery assessment.',k,'process_screen'));end if;end loop;
for x in select value from jsonb_array_elements(a->'assessments')loop
