CREATE OR REPLACE FUNCTION neuvetra.create_inventory_draft_report(target_company_id uuid, target_inventory_id uuid, target_pack_id uuid, requested_report_id uuid, requested_audit_id uuid, expected_inventory_snapshot_sha256 text, expected_archive_sha256 text, request_report_bytes bytea, request_report_sha256 text, request_report_byte_length integer, request_manifest_sha256 text, request_lineage_sha256 text, request_idempotency_key uuid, request_operation_fingerprint text)
