->>'id');loop if node=any(seen)then raise exception 'relationship cycle'using errcode='22023';end if;seen:=array_append(seen,node);select x into rel from jsonb_array_elements((s->'relationships'))x where (x->>'childEntityId')=node;exit when rel is null;if (rel->>'start')<>'2025-01-01'or (rel->>'endExclusive')<>'2026-01-01'or (rel->>'ownershipPercent')is distinct from '100'or (rel->'controlFacts')='null'::jsonb or jsonb_array_length((rel->'evidenceRefs'))=0 then raise exception 'incomplete corporate control'using errcode='22023';end if;node:=(rel->>'parentEntityId');end loop;
for k in select (value#>>'{}')from jsonb_each((r->'evidence'))union all select (x->>'reference')from jsonb_array_elements((r->'refills'))x union all select (x->>'evidence')from jsonb_array_elements((r->'releases'))x union all select (r->>'zero_activity_evidence')where (r->'zero_activity_evidence')<>'null'::jsonb loop if not exists(select 1 from jsonb_array_elements((a->'evidenceStatements'))x where (x->>'reference')=k)then raise exception 'unresolved evidence reference'using errcode='22023';end if;end loop;end if;
