keys(r,'assetId,entityId,facilityId,equipment,gas,capacityKg,controlBasis,explanation,sourceId');perform neuvetra.m77_id((r->'assetId'));if (r->>'equipment')is null or (r->>'equipment')not in('fixed_hvac','fixed_refrigeration','fixed_fire_suppression','portable_fire_suppression','mobile_hvac','mobile_refrigeration','other','unknown')or (r->>'controlBasis')is null or (r->>'controlBasis')not in('owned_operational_control_full_year','unknown','partial_year','other')then raise exception 'asset classification/control facts'using errcode='22023';end if;foreach k in array array['entityId','facilityId','sourceId']loop if r->k<>'null'::jsonb and(jsonb_typeof(r->k)is distinct from 'string'or r->>k!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')or(k='entityId'and r->k='null'::jsonb)then raise exception 'asset corporate UUID'using errcode='22023';end if;end loop;if (r->'gas')<>'null'::jsonb then perform neuvetra.m76_diesel_text((r->'gas'),80);end if;if (r->'capacityKg')<>'null'::jsonb then perform neuvetra.m77_kg((r->'capacityKg'));end if;perform neuvetra.m76_diesel_text((r->'explanation'),2000);if length((r->>'explanation'))<20 then raise exception 'asset facts explanation required'using errcode='22023';end if;end loop;end if;end if;end $function$

CREATE OR REPLACE FUNCTION neuvetra.m78_assert_current_proof(target_company uuid, p jsonb, check_process boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
#variable_conflict use_column
declare x jsonb;actual jsonb;expected jsonb;d text;v jsonb;r jsonb;deps jsonb;bound jsonb;begin
perform neuvetra.m71_keys(p,'priorVersions,coverageVersion,boundCoverageVersions,sourceVersions,fleet,stationary,fugitive,process,policy');if p->'coverageVersion'is distinct from neuvetra.m77_current_coverage(target_company)then raise exception 'current corporate proof changed'using errcode='23505';end if;
