method:=case when family='fugitive'then 'acbfed90deaf7c164fe889b87732a998396ace265c92973ba3f79c6a71c038af'else neuvetra.m67_hash(c->'method')end;if not exists(select 1 from jsonb_array_elements(p#>'{policy,methods}')m where m->>'family'=family and m->>'methodSha256'=method)then findings:=findings||jsonb_build_array(neuvetra.m78_finding('candidate_policy_method_mismatch','Source method is not admitted by the exact accounting-reviewed policy.',v->>'id'));continue;end if;
