for r in select value from jsonb_array_elements(source_rows)loop select x into g from jsonb_array_elements(p#>'{policy,gasGwps}')x where x->'gas'=r->'gas';if g is null then findings:=findings||jsonb_build_array(neuvetra.m78_finding('candidate_policy_gas_mismatch','Gas is absent from the reviewed compatibility policy.',id));continue;end if;if r->>'unit'is distinct from 'kg '||(r->>'gas')or r->>'mass'!~'^(0|[1-9][0-9]{0,39})([.][0-9]{1,30})?$'or r->>'co2e'!~'^(0|[1-9][0-9]{0,39})([.][0-9]{1,30})?$'then raise exception 'exact source gas units/decimals required'using errcode='22023';end if;mass:=(r->>'mass')::numeric;co2e:=(r->>'co2e')::numeric;if mass*(g->>'gwp')::numeric<>co2e then raise exception 'gas mass/GWP parity failed'using errcode='22023';end if;total:=total+co2e;rows:=rows||jsonb_build_array(jsonb_build_object('sourceId',id,'family',family,'physicalId',neuvetra.m78_physical(p,family,v),'entityId',v#>'{activity,binding,entityId}','facilityId',v#>'{activity,binding,facilityId}','gas',r->'gas','gasKind',g->'gasKind','massKgExact',neuvetra.m76_diesel_exact(mass),'co2eKgExact',neuvetra.m76_diesel_exact(co2e),'originalMass',r->'mass','originalMassUnit',r->'unit','methodPin',method,'gwpPolicyPin',p#>'{policy,policySha256}','estimateBasis',case when family='fugitive'then c->'limitation'when family='stationary_diesel'then to_jsonb('default_hhv_estimate'::text)else 'null'::jsonb end));end loop;if total<>expected then raise exception 'source total parity failed'using errcode='22023';end if;
end loop;end if;
policy_blocked:=exists(select 1 from jsonb_array_elements(findings)f where f->>'code'like 'candidate_policy_%');blocked:=exists(select 1 from jsonb_array_elements(findings)f where f->>'classification'='functional_blocker');subtotal:=case when p->'policy'<>'null'::jsonb and not policy_blocked and jsonb_array_length(rows)>0 then neuvetra.m78_rollup(p,rows)else null end;body:=jsonb_build_object('dependencies',deps,'sourceUnion',union_rows,'findings',findings,'knownSourceSubtotal',subtotal,'totals',case when blocked then null else subtotal end,'status',case when blocked then 'blocked'else 'reconciled_bounded_synthetic'end);return body||jsonb_build_object('contentSha256',neuvetra.m67_hash(body));end $function$

CREATE OR REPLACE FUNCTION neuvetra.m78_render_report(s jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
#variable_conflict use_column
declare v jsonb:=s->'version';c jsonb:=s#>'{proof,coverageVersion,snapshot}';r jsonb:=s->'reconciliation';t jsonb;title text;status text;accepted boolean;statements jsonb:=neuvetra.m78_report_statements(s);numbers text;findings text;evidence text;locations text;links text;begin
title:=case when s->>'family'='process_screen'then 'Process-source screening'else 'Gross Scope 1 inventory'end;accepted:=coalesce(s#>>'{review,decision}'in('accepted_bounded_process_screen','accepted_bounded_inventory'),false);status:=case when s->>'family'='process_screen'then case when exists(select 1 from jsonb_array_elements(v->'findings')f where f->>'classification'='functional_blocker')then 'Blocked process discovery'when accepted then 'Reviewed bounded process screen'else 'Process review pending'end when r->>'status'='reconciled_bounded_synthetic'then 'Reconciled synthetic Scope 1 candidate'else 'Scope 1 incomplete'end;t:=coalesce(nullif(r->'totals','null'::jsonb),nullif(r->'knownSourceSubtotal','null'::jsonb));
if t is not null then numbers:='<h2>'||case when r->'totals'<>'null'::jsonb then 'Gross company total'else 'Known-source subtotal — incomplete coverage'end||'</h2><p>'||neuvetra.m75_html_escape(t#>>'{company,kgCo2eDisplay}')||' kg CO2e</p><table><thead><tr><th>Gas</th><th>Emitted kg gas</th><th>Gross kg CO2e exact</th></tr></thead><tbody>'||coalesce((select string_agg('<tr><td data-label="Gas">'||neuvetra.m75_html_escape(g->>'gas')||case when g->>'gasKind'='blend'then ' (blend; constituents not inferred)'else ''end||'</td><td data-label="Emitted kg gas">'||neuvetra.m75_html_escape(g->>'massKgExact')||'</td><td data-label="Gross kg CO2e exact">'||neuvetra.m75_html_escape(g->>'kgCo2eExact')||'</td></tr>',''order by n)from jsonb_array_elements(t->'gasLines')with ordinality q(g,n)),'')||'</tbody></table>'||neuvetra.m78_report_table('Sources',t->'sourceRows')||neuvetra.m78_report_table('Facilities — organizational attribution',t->'facilityRows')||neuvetra.m78_report_table('Entities',t->'entityRows')||'<p>Totals sum unrounded source contributions before half-even display rounding. Displayed company total minus displayed source sum: '||neuvetra.m75_html_escape(t->>'displayRoundingDelta')||' kg CO2e. No offsets or avoided emissions deducted.</p>';else numbers:='<p>No combined company CO2e total is available while compatibility or source coverage is unresolved.</p>';end if;
select coalesce(string_agg('<li>'||neuvetra.m75_html_escape(f->>'classification')||': '||neuvetra.m75_html_escape(f->>'message')||'</li>',''order by n),'')into findings from jsonb_array_elements(coalesce(nullif(r->'findings','null'::jsonb),v->'findings'))with ordinality q(f,n);
select coalesce(string_agg('<section id="statement-'||neuvetra.m75_html_escape(e->>'id')||'"><h3>'||neuvetra.m75_html_escape(e->>'description')||'</h3><p>Locator '||neuvetra.m75_html_escape(e->>'locator')||' · SHA-256 '||neuvetra.m75_html_escape(e->>'sha256')||'</p><details><summary>Exact retained statement</summary><pre>'||neuvetra.m75_html_escape(e->>'text')||'</pre></details></section>',''order by n),'')into evidence from jsonb_array_elements(statements)with ordinality q(e,n);
select coalesce(string_agg('<li>'||neuvetra.m75_html_escape((select e->>'legalName'from jsonb_array_elements(c->'entities')e where e->'id'=f->'entityId'limit 1))||' — '||neuvetra.m75_html_escape(f->>'name')||' · '||neuvetra.m75_html_escape(f->>'id')||'</li>',''order by n),'')into locations from jsonb_array_elements(c->'facilities')with ordinality q(f,n);select coalesce(string_agg('<li><a href="#statement-'||neuvetra.m75_html_escape(e->>'id')||'">'||neuvetra.m75_html_escape(e->>'description')||'</a></li>',''order by n),'')into links from jsonb_array_elements(statements)with ordinality q(e,n);
return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src ''none''; style-src ''unsafe-inline''; base-uri ''none''; form-action ''none''"><title>'||title||'</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:1000px;color:#172f2c;overflow-wrap:anywhere}table{border-collapse:collapse;width:100%}th,td{padding:.4rem;text-align:left;border-bottom:1px solid #ccd8d0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}@media(max-width:600px){thead{display:none}tr{display:block;margin:.8rem 0}td{display:block}td::before{content:attr(data-label);font-weight:600;margin-right:.5rem}}@media print{body{font-size:10pt;margin:0}tr{break-inside:avoid}}</style></head><body><h1>'||title||' — synthetic internal draft</h1><p>'||neuvetra.m75_html_escape(c->>'companyLabel')||' · calendar 2025 · version '||(v->>'version')||'</p><p>'||neuvetra.m75_html_escape(status)||' · '||case when accepted then 'accepted for bounded internal review'when s->'review'<>'null'::jsonb then 'changes requested'else 'not reviewed'end||'.</p><p>Scope 1 and corporate inventory remain incomplete for release. Candidate methods and factors are not released. Requirements are not determined. No external assurance. Fictional evidence is not original customer evidence.</p>'||numbers||neuvetra.m78_report_detail_sections(s)||'<h2>Retained entities and locations</h2><ul>'||locations||'</ul><h2>Coverage findings and limitations</h2><ul>'||findings||'</ul><h2>Retained evidence</h2><ul>'||links||'</ul>'||evidence||'<details><summary>Exact retained snapshot and provenance</summary><pre>'||neuvetra.m75_html_escape(neuvetra.m67_canonical(s))||'</pre></details></body></html>';end $function$

CREATE OR REPLACE FUNCTION neuvetra.m78_screen_findings(a jsonb, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
#variable_conflict use_column
declare out jsonb:=neuvetra.m78_process_findings(a,p->'coverageVersion');f jsonb;g jsonb;x jsonb;actual jsonb;d text;begin
for f in select value from jsonb_array_elements(p#>'{coverageVersion,findings}')where value->>'code'in('unsupported_consolidation','unsupported_geography','unsupported_temporal_allocation','unsupported_boundary_relationship','control_evidence_missing','boundary_unreconciled','boundary_basis_missing','boundary_assertion_unverified')loop out:=out||jsonb_build_array(neuvetra.m78_finding('corporate_scope1_boundary_blocked',f->>'message',f->>'recordId','process_screen'));end loop;
if p#>>'{coverageVersion,review,decision}'is distinct from 'accepted_bounded_internal'then out:=out||jsonb_build_array(neuvetra.m78_finding('corporate_review_required','Current corporate boundary requires exact review.',null,'process_screen'));end if;
for g in select value from jsonb_array_elements(a->'gasCoverage')loop actual:=neuvetra.m78_gas_sources(p,g->>'gasGroup');if jsonb_array_length(actual)>0 and g->>'state'<>'covered_by_sources'or g->>'state'='covered_by_sources'and g->'sourceIds'is distinct from coalesce((select jsonb_agg(x#>'{version,activity,binding,sourceId}'order by x#>>'{version,activity,binding,sourceId}'collate "C")from jsonb_array_elements(actual)x),'[]')then out:=out||jsonb_build_array(neuvetra.m78_finding('gas_source_coverage_conflict','Gas applicability must name every exact source in the discovered population.',g->>'gasGroup','process_screen'));end if;if g->>'state'<>'covered_by_sources'then continue;end if;
foreach d in array array['fleet','stationary','fugitive']loop if p#>>array[d,'reconciliation','status']is distinct from 'reconciled_bounded_synthetic'or p#>>array[d,'review','decision']is distinct from 'accepted_bounded_reconciliation'then out:=out||jsonb_build_array(neuvetra.m78_finding('gas_physical_population_unreconciled','Positive gas coverage requires independently reconciled complete physical populations.',g->>'gasGroup','process_screen'));end if;end loop;
for x in select value from jsonb_array_elements(actual)loop if x#>'{version,calculation}'='null'::jsonb or x#>>'{version,review,decision}'is distinct from 'accepted_bounded_internal'or x#>'{version,activity,binding,coverageVersionId}'is distinct from p#>'{coverageVersion,id}'or x#>'{version,activity,binding,coverageVersionSha256}'is distinct from p#>'{coverageVersion,versionSha256}'then out:=out||jsonb_build_array(neuvetra.m78_finding('gas_source_incomplete','Positive gas coverage requires current exact supported source review.',x#>>'{version,activity,binding,sourceId}','process_screen'));end if;end loop;
end loop;return out;end $function$

CREATE OR REPLACE FUNCTION neuvetra.m78_validate_activity(family text, a jsonb, c jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
#variable_conflict use_column
declare b jsonb:=a->'binding';d jsonb;x jsonb;k text;begin
if family='process_screen'then perform neuvetra.m71_keys(a,'profile,binding,declaration,locations,assessments,gasCoverage,evidenceStatements,manualConfirmation');if a->>'profile'is distinct from 'synthetic-process-screen-v1'or jsonb_typeof(a->'manualConfirmation')is distinct from 'boolean'then raise exception 'process profile'using errcode='22023';end if;
elsif family='inventory'then perform neuvetra.m71_keys(a,'profile,binding,note');if a->>'profile'is distinct from 'synthetic-scope1-inventory-v1'then raise exception 'inventory profile'using errcode='22023';end if;perform neuvetra.m76_diesel_text(a->'note',2000);else raise exception 'family required'using errcode='22023';end if;
perform neuvetra.m71_keys(b,'coverageVersionId,coverageVersionSha256,processCoverageItemId,period');if b->'coverageVersionId'is distinct from c->'id'or b->'coverageVersionSha256'is distinct from c->'versionSha256'or b->'period'is distinct from '{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb or b->'period'is distinct from c#>'{snapshot,period}'or not exists(select 1 from jsonb_array_elements(c#>'{snapshot,coverageItems}')x where x->'id'=b->'processCoverageItemId'and x->>'domain'='process'and x->'entityId'='null'::jsonb and x->'sourceId'='null'::jsonb)then raise exception 'exact corporate/process coverage binding required'using errcode='22023';end if;
if family='inventory'then return;end if;
d:=a->'declaration';if d<>'null'::jsonb then perform neuvetra.m71_keys(d,'completeness,coveredEntityIds,coveredFacilityIds,allControlledOperationsIncluded,discoveryBasis');if coalesce(d->>'completeness','')not in('unknown','partial','declared_complete')or jsonb_typeof(d->'allControlledOperationsIncluded')is distinct from 'boolean'then raise exception 'discovery declaration required'using errcode='22023';end if;perform neuvetra.m78_sorted_strings(d->'coveredEntityIds',150,'uuid');perform neuvetra.m78_sorted_strings(d->'coveredFacilityIds',150,'uuid');perform neuvetra.m76_diesel_text(d->'discoveryBasis',2000);if length(d->>'discoveryBasis')<20 then raise exception 'discovery basis required'using errcode='22023';end if;end if;
foreach k in array array['locations','assessments','gasCoverage','evidenceStatements']loop if jsonb_typeof(a->k)is distinct from 'array'or jsonb_array_length(a->k)>(case k when 'locations'then 25 when 'gasCoverage'then 7 else 100 end)then raise exception 'process capacity'using errcode='22023';end if;end loop;
for x in select value from jsonb_array_elements(a->'locations')loop perform neuvetra.m71_keys(x,'rowId,entityId,facilityId,operationId,businessActivities,equipmentAndMaterials,controlExplanation,evidenceReferences');perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'rowId'),1,'uuid');perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'entityId'),1,'uuid');if(x->'facilityId'='null'::jsonb)=(x->'operationId'='null'::jsonb)then raise exception 'facility or operation required'using errcode='22023';end if;if x->'facilityId'<>'null'::jsonb then perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'facilityId'),1,'uuid');else perform neuvetra.m77_id(x->'operationId');end if;perform neuvetra.m76_diesel_text(x->'businessActivities',2000);perform neuvetra.m76_diesel_text(x->'equipmentAndMaterials',2000);perform neuvetra.m76_diesel_text(x->'controlExplanation',2000);perform neuvetra.m78_sorted_strings(x->'evidenceReferences',100,'id');end loop;
for x in select value from jsonb_array_elements(a->'assessments')loop perform neuvetra.m71_keys(x,'rowId,category,discoveredSourceId,locationRowIds,disposition,reason,evidenceReferences');perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'rowId'),1,'uuid');if coalesce(x->>'category','')not in('mineral_products','chemical_production','metal_production','oil_and_gas','waste_treatment','agricultural_biological','other_direct_process')or coalesce(x->>'disposition','')not in('unknown','indicated','not_applicable_proposed')or(x->>'disposition'='indicated')=(x->'discoveredSourceId'='null'::jsonb)then raise exception 'process assessment required'using errcode='22023';end if;if x->'discoveredSourceId'<>'null'::jsonb then perform neuvetra.m77_id(x->'discoveredSourceId');end if;perform neuvetra.m78_sorted_strings(x->'locationRowIds',25,'uuid');perform neuvetra.m78_sorted_strings(x->'evidenceReferences',100,'id');if x->'reason'<>'null'::jsonb then perform neuvetra.m76_diesel_text(x->'reason',2000);end if;end loop;
for x in select value from jsonb_array_elements(a->'gasCoverage')loop perform neuvetra.m71_keys(x,'gasGroup,state,sourceIds,discoveredSourceIds,locationRowIds,reason,evidenceReferences');if coalesce(x->>'gasGroup','')not in('CO2','CH4','N2O','HFCs','PFCs','SF6','NF3')or coalesce(x->>'state','')not in('unknown','indicated','not_applicable_proposed','covered_by_sources')then raise exception 'gas applicability required'using errcode='22023';end if;perform neuvetra.m78_sorted_strings(x->'sourceIds',150,'uuid');perform neuvetra.m78_sorted_strings(x->'discoveredSourceIds',100,'id');perform neuvetra.m78_sorted_strings(x->'locationRowIds',25,'uuid');perform neuvetra.m78_sorted_strings(x->'evidenceReferences',100,'id');if x->'reason'<>'null'::jsonb then perform neuvetra.m76_diesel_text(x->'reason',2000);end if;if x->>'state'='covered_by_sources'and jsonb_array_length(x->'sourceIds')=0 or x->>'state'='indicated'and jsonb_array_length(x->'discoveredSourceIds')=0 or x->>'state'<>'indicated'and jsonb_array_length(x->'discoveredSourceIds')<>0 or x->>'state'='not_applicable_proposed'and jsonb_array_length(x->'sourceIds')<>0 then raise exception 'gas state source conflict'using errcode='22023';end if;end loop;
for x in select value from jsonb_array_elements(a->'evidenceStatements')loop perform neuvetra.m71_keys(x,'reference,issuer,description,issuedOn,purpose,entityId,facilityId');perform neuvetra.m77_id(x->'reference');perform neuvetra.m76_diesel_text(x->'issuer',120);perform neuvetra.m76_diesel_text(x->'description',2000);if length(x->>'description')<20 or coalesce(x->>'purpose','')not in('business_activity','process_inspection','offsite_discovery')or to_char((x->>'issuedOn')::date,'YYYY-MM-DD')is distinct from x->>'issuedOn'then raise exception 'dated statement required'using errcode='22023';end if;perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'entityId'),1,'uuid');if x->'facilityId'<>'null'::jsonb then perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'facilityId'),1,'uuid');end if;end loop;
foreach k in array array['locations','assessments','gasCoverage','evidenceStatements']loop perform neuvetra.m78_sorted_strings((select coalesce(jsonb_agg(x->case k when 'gasCoverage'then 'gasGroup'when 'evidenceStatements'then 'reference'else 'rowId'end order by n),'[]')from jsonb_array_elements(a->k)with ordinality q(x,n)),100,'text');end loop;if jsonb_array_length(a->'gasCoverage')<>7 then raise exception 'all seven gas groups required'using errcode='22023';end if;
perform neuvetra.m78_sorted_strings((select coalesce(jsonb_agg(x->'discoveredSourceId'order by x->>'discoveredSourceId'collate "C"),'[]')from jsonb_array_elements(a->'assessments')x where x->'discoveredSourceId'<>'null'::jsonb),100,'id');if octet_length(neuvetra.m67_canonical(a))>200000 then raise exception 'activity capacity exceeded'using errcode='22023';end if;
end $function$

CREATE OR REPLACE FUNCTION neuvetra.record_synthetic_inventory_review(target_company_id uuid, target_inventory_id uuid, review_id uuid, audit_id uuid, requested_decision text, requested_reason_code text, requested_acknowledgments text[], request_idempotency_key uuid, request_operation_fingerprint text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'neuvetra', 'pg_temp'
AS $function$
declare actor_id uuid := neuvetra.current_user_id(); stored_id uuid; inventory record;
begin
  if actor_id is null then raise exception 'authentication required' using errcode = '42501'; end if;
  if not neuvetra.can_manage_company(target_company_id) then raise exception 'workspace not found' using errcode = '42501'; end if;
  if requested_decision not in ('approve_bounded_draft','changes_requested') or request_operation_fingerprint !~ '^[0-9a-f]{64}$' then raise exception 'review contract mismatch' using errcode = '22023'; end if;
  if (requested_decision = 'approve_bounded_draft' and (requested_reason_code <> 'bounded_synthetic_scope_reviewed' or requested_acknowledgments <> array['annual_coverage_incomplete_1_of_12_months','market_based_scope2_not_included','factor_and_method_not_released','synthetic_local_only_no_assurance']::text[]))
    or (requested_decision = 'changes_requested' and (requested_reason_code <> 'source_or_calculation_revision_required' or requested_acknowledgments <> array[]::text[]))
  then raise exception 'review contract mismatch' using errcode = '22023'; end if;
  select id, status, complete, factor_release_eligible, submitted_by into inventory from neuvetra.inventory_versions
    where company_id = target_company_id and id = target_inventory_id for update;
  if inventory.id is null then raise exception 'inventory not found' using errcode = '42501'; end if;
  if inventory.status <> 'in_review' or inventory.complete or inventory.factor_release_eligible or inventory.submitted_by = actor_id then raise exception 'review contract mismatch' using errcode = '22023'; end if;
  insert into neuvetra.inventory_review_decisions (
    id, company_id, inventory_version_id, decision, outcome, inventory_status_after, acknowledged_warning_codes, reason_code,
    idempotency_key, operation_fingerprint, decided_by
  ) values (
    review_id, target_company_id, target_inventory_id, requested_decision,
    case when requested_decision = 'approve_bounded_draft' then 'approved_bounded_draft' else 'changes_requested' end,
    case when requested_decision = 'approve_bounded_draft' then 'approved_bounded_draft' else 'changes_requested' end,
    requested_acknowledgments, requested_reason_code, request_idempotency_key, request_operation_fingerprint, actor_id
  ) on conflict (company_id, inventory_version_id) do nothing returning id into stored_id;
  if stored_id is null then
    select id into stored_id from neuvetra.inventory_review_decisions where company_id = target_company_id and inventory_version_id = target_inventory_id
      and decision = requested_decision and reason_code = requested_reason_code and acknowledged_warning_codes = requested_acknowledgments and operation_fingerprint = request_operation_fingerprint;
    if stored_id is null then raise exception 'review conflict' using errcode = '23505'; end if;
    return stored_id;
  end if;
  insert into neuvetra.inventory_review_audit_log values (
    audit_id, target_company_id, actor_id, 'inventory.review.recorded', stored_id,
    jsonb_build_object('inventory_version_id', target_inventory_id, 'decision', requested_decision,
      'outcome', case when requested_decision = 'approve_bounded_draft' then 'approved_bounded_draft' else 'changes_requested' end), now()
  );
  return stored_id;
end $function$

CREATE OR REPLACE FUNCTION neuvetra.render_annual_electricity_report(report_id uuid, company uuid, creator uuid, captured text, source jsonb, identity_sha text)
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
declare result text:=neuvetra.annual_electricity_report_template(); values_map jsonb; item record; escaped text; r jsonb:=source->'review'; m jsonb:=source->'method'; month_row jsonb; month_index integer:=0; month_prefix text;
begin
 values_map:=jsonb_build_object(
 'subtotalLabel',case when (source#>>'{coverage,electricityComplete}')::boolean then 'Full-year electricity subtotal — all 12 months entered' else 'Entered-month electricity subtotal' end,
 'knownMonths',source#>>'{coverage,knownMonths}','coverageNote',case when (source#>>'{coverage,electricityComplete}')::boolean then 'Full electricity period coverage for this fictional facility; the overall company inventory remains incomplete.' else 'This subtotal excludes months not entered.' end,
