CREATE OR REPLACE FUNCTION neuvetra.review_annual_inventory_v2(target_company_id uuid, target_inventory_id uuid, review_id uuid, audit_id uuid, requested_decision text, requested_reason text, requested_warnings text[], request_idempotency_key uuid, request_operation_fingerprint text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'neuvetra', 'pg_temp'
AS $function$
declare actor_id uuid := neuvetra.current_user_id(); stored_id uuid; inv record;
begin
  if actor_id is null or not neuvetra.can_manage_company(target_company_id) then raise exception 'workspace not found' using errcode='42501'; end if;
  select * into inv from neuvetra.annual_inventory_versions where company_id=target_company_id and id=target_inventory_id for update;
  if inv.id is null or inv.submitted_by=actor_id then raise exception 'review conflict' using errcode='22023'; end if;
  if (requested_decision='approve_bounded_annual_location_draft' and (requested_reason is distinct from 'bounded_annual_location_register_reviewed' or requested_warnings is distinct from array['one_period_estimated','one_period_excluded','market_based_scope2_not_included','factor_and_method_not_released','scope_1_and_scope_3_not_assessed','synthetic_local_only_no_assurance']::text[])) or
     (requested_decision='changes_requested' and (requested_reason is distinct from 'source_or_calculation_revision_required' or requested_warnings is distinct from array[]::text[])) then raise exception 'review contract mismatch' using errcode='22023'; end if;
  insert into neuvetra.annual_inventory_review_decisions values(review_id,target_company_id,target_inventory_id,requested_decision,requested_reason,requested_warnings,request_idempotency_key,request_operation_fingerprint,actor_id,now())
    on conflict (company_id,annual_inventory_version_id) do nothing returning id into stored_id;
  if stored_id is null then select id into stored_id from neuvetra.annual_inventory_review_decisions where company_id=target_company_id and annual_inventory_version_id=target_inventory_id and decision=requested_decision and operation_fingerprint=request_operation_fingerprint; end if;
  if stored_id is null then raise exception 'review conflict' using errcode='23505'; end if;
  insert into neuvetra.annual_inventory_audit_log values(audit_id,target_company_id,actor_id,'annual_inventory.reviewed',stored_id,jsonb_build_object('decision',requested_decision),now()) on conflict do nothing;
  return stored_id;
end $function$

CREATE OR REPLACE FUNCTION neuvetra.review_corporate_inventory(target_company uuid, target_inventory uuid, request jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
declare actor uuid:=auth.uid();v record;old record;body jsonb;fingerprint text;digest text;new_id uuid:=gen_random_uuid();captured timestamptz:=date_trunc('milliseconds',clock_timestamp());begin
 if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;
 perform neuvetra.m71_keys(request,'versionId,expectedVersionSha256,decision,note,acknowledgedLimitations,idempotencyKey');
 if exists(select 1 from jsonb_each(request) where key<>'acknowledgedLimitations' and jsonb_typeof(value)<>'string') or request->>'versionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or request->>'note'<>normalize(request->>'note',NFC) or request->>'note'~'[[:cntrl:]]' then raise exception 'invalid review types' using errcode='22023';end if;
 if jsonb_typeof(request->'note')<>'string' or length(request->>'note') not between 1 and 500 or request->>'note'<>btrim(request->>'note') or request->>'decision' not in('accepted_bounded_internal','changes_requested') or request->'acknowledgedLimitations'<>'["synthetic_only","corporate_inventory_incomplete","methods_not_released","requirements_not_determined","no_emissions_calculated","no_external_assurance"]'::jsonb then raise exception 'invalid review' using errcode='22023';end if;
 fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','review','actor',actor,'companyId',target_company,'inventoryId',target_inventory,'request',request-'idempotencyKey'));
 select * into old from neuvetra.corporate_inventory_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;
 if found then if old.fingerprint<>fingerprint or old.kind<>'review' then raise exception 'request conflict' using errcode='23505';end if;return old.record_id;end if;
 select * into v from neuvetra.corporate_inventory_versions where company_id=target_company and inventory_id=target_inventory and id=(request->>'versionId')::uuid;
 if not found or v.version_sha256 is distinct from request->>'expectedVersionSha256' or v.payload->'contributorIds' ? actor::text or not exists(select 1 from neuvetra.corporate_inventory_heads where company_id=target_company and id=target_inventory and version_id=v.id) then raise exception 'review conflicts or contributor cannot review' using errcode='23505';end if;
 captured:=date_trunc('milliseconds',clock_timestamp());
 body:=jsonb_build_object('id',new_id,'versionId',v.id,'versionSha256',v.version_sha256,'decision',request->'decision','note',request->'note','acknowledgedLimitations',request->'acknowledgedLimitations','reviewerId',actor,'reviewedAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
 digest:=neuvetra.m67_hash(body||jsonb_build_object('profile','synthetic-corporate-coverage-v1','companyId',target_company));body:=body||jsonb_build_object('decisionSha256',digest);
 insert into neuvetra.corporate_inventory_reviews values(new_id,target_company,v.id,body,digest,actor,captured);
 insert into neuvetra.corporate_inventory_requests values(target_company,(request->>'idempotencyKey')::uuid,fingerprint,'review',new_id);
 insert into neuvetra.corporate_inventory_audit values(gen_random_uuid(),target_company,new_id,'review',digest,actor,captured);return new_id;
end $function$

CREATE OR REPLACE FUNCTION neuvetra.review_electricity_worksheet(target_company uuid, request jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
declare actor uuid:=neuvetra.current_user_id(); v record; prior record; review_id uuid:=gen_random_uuid(); fingerprint text; digest text; body jsonb; acknowledgments jsonb; note text; decision_captured_at timestamptz;
begin
 if actor is null or not neuvetra.can_manage_company(target_company) then raise exception 'workspace not found' using errcode='42501'; end if;
 perform id from neuvetra.companies where id=target_company for update;
 decision_captured_at:=date_trunc('milliseconds',clock_timestamp());
 if jsonb_typeof(request) is distinct from 'object' or (select array_agg(key order by key) from jsonb_object_keys(request) key) is distinct from array['acknowledgedLimitations','decision','expectedResultSha256','idempotencyKey','note','versionId']::text[] then raise exception 'invalid worksheet review' using errcode='22023'; end if;
 if exists(select 1 from jsonb_each(request) where key not in('note','acknowledgedLimitations') and jsonb_typeof(value)<>'string') or (request->>'idempotencyKey') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'invalid worksheet review' using errcode='22023'; end if;
 acknowledgments := '["synthetic_manual_input","overall_inventory_incomplete","january_2023_camx_only","market_based_scope2_not_included","factor_and_method_not_released","scope_1_and_scope_3_not_assessed","no_assurance"]'::jsonb;
 if request->>'decision'='accept_bounded_internal_draft' then
  if request->'note' is distinct from 'null'::jsonb or request->'acknowledgedLimitations' is distinct from acknowledgments then raise exception 'invalid worksheet review' using errcode='22023'; end if;
 elsif request->>'decision'='changes_requested' then
  note:=request->>'note';
  if jsonb_typeof(request->'note') is distinct from 'string' or (note !~ '^[ -~]+$' or char_length(note) not between 1 and 500) or note<>btrim(note) or request->'acknowledgedLimitations' is distinct from '[]'::jsonb then raise exception 'invalid worksheet review' using errcode='22023'; end if;
 else raise exception 'invalid worksheet review' using errcode='22023'; end if;
 select * into v from neuvetra.electricity_worksheet_versions where company_id=target_company and id=(request->>'versionId')::uuid;
 if not found or v.result_sha256 is distinct from request->>'expectedResultSha256' or v.created_by=actor then raise exception 'worksheet review conflicts' using errcode='23505'; end if;
 fingerprint:=encode(sha256(convert_to(actor::text||E'\n'||(request-'idempotencyKey')::text,'utf8')),'hex');
 select * into prior from neuvetra.electricity_worksheet_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;
 if found then
  if prior.kind<>'review' or prior.operation_fingerprint<>fingerprint then raise exception 'worksheet request conflicts' using errcode='23505';end if;
  return prior.record_id;
 end if;
 select id into review_id from neuvetra.electricity_worksheet_reviews where company_id=target_company and operation_fingerprint=fingerprint;
 if found then
  insert into neuvetra.electricity_worksheet_requests values(target_company,(request->>'idempotencyKey')::uuid,fingerprint,'review',review_id);
  return review_id;
 end if;
 if exists(select 1 from neuvetra.electricity_worksheet_versions where company_id=target_company and version>v.version) or exists(select 1 from neuvetra.electricity_worksheet_reviews where company_id=target_company and version_id=v.id) then raise exception 'worksheet review conflicts' using errcode='23505';end if;
 review_id:=gen_random_uuid();
 digest:=encode(sha256(convert_to(concat_ws(E'\n','neuvetra.synthetic.manual-electricity-worksheet.v1',target_company::text,review_id::text,v.id::text,v.result_sha256,request->>'decision',coalesce(note,'<null>'),(select coalesce(string_agg(value,',' order by ord),'') from jsonb_array_elements_text(request->'acknowledgedLimitations') with ordinality as a(value,ord)),actor::text),'utf8')),'hex');
 body:=jsonb_build_object('id',review_id,'versionId',v.id,'resultSha256',v.result_sha256,'decision',request->>'decision','note',note,'acknowledgedLimitations',request->'acknowledgedLimitations','reviewerId',actor,'decisionSha256',digest);
 insert into neuvetra.electricity_worksheet_reviews values(review_id,target_company,v.id,body,digest,fingerprint,actor,decision_captured_at);
 insert into neuvetra.electricity_worksheet_requests values(target_company,(request->>'idempotencyKey')::uuid,fingerprint,'review',review_id);
 insert into neuvetra.electricity_worksheet_audit values(gen_random_uuid(),target_company,review_id,'review',digest,actor,decision_captured_at);
 return review_id;
end $function$

CREATE OR REPLACE FUNCTION neuvetra.review_inventory_draft_report(target_company_id uuid, target_inventory_id uuid, target_report_id uuid, requested_decision_id uuid, requested_audit_id uuid, request_decision text, request_reason_code text, request_acknowledged_limitations text[], request_change_route_code text, request_change_note text, expected_report_sha256 text, expected_inventory_snapshot_sha256 text, expected_archive_sha256 text, expected_manifest_sha256 text, expected_lineage_sha256 text, expected_report_created_by uuid, request_decision_snapshot_sha256 text, request_idempotency_key uuid, request_operation_fingerprint text)
