if family='process_screen'then for key in select 'process:'||(x->>'discoveredSourceId')from jsonb_array_elements(a->'assessments')x where x->'discoveredSourceId'<>'null'::jsonb union all select 'gas:'||(g->>'gasGroup')||':'||id from jsonb_array_elements(a->'gasCoverage')g,jsonb_array_elements_text(g->'discoveredSourceIds')id loop insert into neuvetra.scope1_process_discoveries values(target_company,2025,key,(v->>'streamId')::uuid,captured)on conflict do nothing;end loop;end if;
perform neuvetra.m78_record_request(target_company,target_stream,family,'save',request,(v->>'id')::uuid,v->>'versionSha256',captured);return(v->>'id')::uuid;end $function$

CREATE OR REPLACE FUNCTION neuvetra.save_source_worksheet(target_company uuid, request jsonb, correction boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$
declare actor uuid:=neuvetra.current_user_id(); predecessor record; prior record; new_id uuid; seq integer; fingerprint text; input_hash text; result_hash text;
 raw_quantity text; kwh text; mwh text; exact_total text; display_total text; scaled numeric; q numeric; rem numeric; reason text; body jsonb; method jsonb; evidence jsonb; source record; captured timestamptz; captured_text text; difference_reason text;
begin
 if actor is null or not neuvetra.can_manage_company(target_company) then raise exception 'workspace not found' using errcode='42501';end if;
 perform id from neuvetra.companies where id=target_company for update;
 if not neuvetra.can_manage_company(target_company) then raise exception 'workspace not found' using errcode='42501';end if;
 captured:=date_trunc('milliseconds',clock_timestamp());captured_text:=to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
 if jsonb_typeof(request) is distinct from 'object' or (select array_agg(key order by key) from jsonb_object_keys(request) key) is distinct from (case when correction then array['companyLabel','correctionReason','expectedResultSha256','expectedSourceSha256','expectedVersionId','facilityLabel','geography','idempotencyKey','manualConfirmation','period','quantityDifferenceReason','quantityKwh','sourceId','sourcePage','unit'] else array['companyLabel','expectedSourceSha256','facilityLabel','geography','idempotencyKey','manualConfirmation','period','quantityDifferenceReason','quantityKwh','sourceId','sourcePage','unit'] end) then raise exception 'invalid worksheet input' using errcode='22023';end if;
 if exists(select 1 from jsonb_each(request) where key not in('sourcePage','manualConfirmation','quantityDifferenceReason') and jsonb_typeof(value)<>'string') or request->>'period'<>'2023-01' or request->>'geography'<>'CAMX' or request->>'unit'<>'kWh' or request->>'idempotencyKey' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'invalid worksheet input' using errcode='22023';end if;
 if request->>'companyLabel' !~ '^[ -~]{1,100}$' or request->>'companyLabel'<>btrim(request->>'companyLabel') or request->>'facilityLabel' !~ '^[ -~]{1,100}$' or request->>'facilityLabel'<>btrim(request->>'facilityLabel') then raise exception 'invalid worksheet label' using errcode='22023';end if;
 if request->'sourcePage' is distinct from '1'::jsonb or request->'manualConfirmation' is distinct from 'true'::jsonb or request->>'sourceId' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'expectedSourceSha256' !~ '^[0-9a-f]{64}$' then raise exception 'invalid source confirmation' using errcode='22023';end if;
 select * into source from neuvetra.electricity_sources where company_id=target_company and id=(request->>'sourceId')::uuid;
 if not found or source.sha256 is distinct from request->>'expectedSourceSha256' then raise exception 'source conflicts' using errcode='23505';end if;
 if encode(sha256(source.original_bytes),'hex')<>source.sha256 or octet_length(source.original_bytes)<>source.byte_length then raise exception 'source integrity failed';end if;
 raw_quantity:=request->>'quantityKwh';
 if char_length(raw_quantity)>11 or raw_quantity !~ '^(0|[1-9][0-9]{0,6})(\.[0-9]{1,3})?$' or raw_quantity ~ '[^0-9.]' then raise exception 'invalid worksheet quantity' using errcode='22023';end if;
 if raw_quantity::numeric>1000000 then raise exception 'invalid worksheet quantity' using errcode='22023';end if;
 kwh:=(raw_quantity::numeric)::numeric(10,3)::text;
 difference_reason:=request->>'quantityDifferenceReason';
 if kwh=source.printed_quantity_kwh then
  if request->'quantityDifferenceReason' is distinct from 'null'::jsonb then raise exception 'invalid quantity difference reason' using errcode='22023';end if;
 else
  if jsonb_typeof(request->'quantityDifferenceReason') is distinct from 'string' or difference_reason !~ '^[ -~]+$' or char_length(difference_reason) not between 1 and 500 or difference_reason<>btrim(difference_reason) then raise exception 'quantity difference reason required' using errcode='22023';end if;
 end if;
 evidence:=jsonb_build_object('source',neuvetra.electricity_source_metadata(source.id,target_company),'page',1,'confirmedBy',actor,'confirmedAt',captured_text,'quantityDifferenceReason',difference_reason);
 mwh:=(raw_quantity::numeric*0.001)::numeric(10,6)::text;
 scaled:=raw_quantity::numeric*1000*1950402888;
 exact_total:=rtrim(rtrim((scaled*0.0000000000001)::numeric(20,13)::text,'0'),'.');
 q:=div(scaled,1000000000); rem:=mod(scaled,1000000000);
 if rem>500000000 or (rem=500000000 and mod(q,2)=1) then q:=q+1;end if;
 display_total:=(q*0.0001)::numeric(12,4)::text;
 if correction then
  reason:=request->>'correctionReason';
  if (reason !~ '^[ -~]+$' or char_length(reason) not between 1 and 500) or reason<>btrim(reason) then raise exception 'invalid correction reason' using errcode='22023';end if;
 else reason:=null;end if;
 fingerprint:=encode(sha256(convert_to(actor::text||E'\n'||correction::text||E'\n'||((request-'idempotencyKey')||jsonb_build_object('quantityKwh',kwh))::text,'utf8')),'hex');
 select * into prior from neuvetra.source_worksheet_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;
 if found then
  if prior.kind<>'save' or prior.operation_fingerprint<>fingerprint then raise exception 'worksheet request conflicts' using errcode='23505';end if;
  return prior.record_id;
 end if;
 select id into new_id from neuvetra.source_worksheet_versions where company_id=target_company and operation_fingerprint=fingerprint;
 if found then
  insert into neuvetra.source_worksheet_requests values(target_company,(request->>'idempotencyKey')::uuid,fingerprint,'save',new_id);
  return new_id;
 end if;
 select * into predecessor from neuvetra.source_worksheet_versions where company_id=target_company order by version desc limit 1;
 if correction then
  if not found or predecessor.id is distinct from (request->>'expectedVersionId')::uuid or predecessor.result_sha256 is distinct from request->>'expectedResultSha256' or (predecessor.payload->>'quantityKwh'=kwh and predecessor.payload->>'companyLabel'=request->>'companyLabel' and predecessor.payload->>'facilityLabel'=request->>'facilityLabel' and predecessor.payload#>>'{evidence,source,id}'=source.id::text and predecessor.payload#>'{evidence,quantityDifferenceReason}'=request->'quantityDifferenceReason') then raise exception 'worksheet correction conflicts' using errcode='23505';end if;
  seq:=predecessor.version+1;
 else
  if found then raise exception 'worksheet already exists' using errcode='23505';end if;
  seq:=1;
 end if;
 new_id:=gen_random_uuid();
 input_hash:=encode(sha256(convert_to(concat_ws(E'\n','neuvetra.synthetic.source-electricity-worksheet.v1',target_company::text,new_id::text,seq::text,coalesce(predecessor.id::text,'<null>'),actor::text,request->>'companyLabel',request->>'facilityLabel',kwh,'2023-01','CAMX','kWh',coalesce(reason,'<null>'),source.id::text,target_company::text,source.fixture_id,source.original_name,source.media_type,source.byte_length::text,source.sha256,source.printed_quantity_kwh,source.uploaded_by::text,to_char(source.uploaded_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'1',actor::text,captured_text,coalesce(difference_reason,'<null>')),'utf8')),'hex');
 method:='{"id":"scope2-location-based-egrid-subregion","version":"2023-r2-camx-v1","factorId":"epa-egrid2023-r2-camx-total-output","factorVersion":"eGRID2023-revision-2","factorValue":"195.0402888","factorUnit":"kg CO2e/MWh","sourceSha256":"3dfbbcf2f949d58d5b2dbee3aab8150bd04a0c8ebb730ba1cd37a013bd4450ab","sheet":"SRL23","cell":"AI6","classification":"development_candidate","policy":"m64-accounting-policy-v1","accountingProfile":"manual-synthetic-2023-01-camx-kwh-v1","factorCandidateSha256":"8770ae6238df8525e5250850fab248c934be33f459ed19cc1fa24bd0718cb356","gwpPolicySha256":"fd9fd8973012da1a232dad7fc00db3013194751a92b34ab21dfd4f7b2c5148c5","reviewedEngineSha256":"4ad28f3877d13f238bbbf7e8bfb1fc6241922b9def73712ec1b02fd80b51b82c"}'::jsonb;
 result_hash:=encode(sha256(convert_to(concat_ws(E'\n',input_hash,mwh,exact_total,display_total,'kg CO2e','half_even_4dp',method->>'id',method->>'version',method->>'factorId',method->>'factorVersion',method->>'factorValue',method->>'factorUnit',method->>'sourceSha256',method->>'sheet',method->>'cell',method->>'classification',method->>'policy',method->>'accountingProfile',method->>'factorCandidateSha256',method->>'gwpPolicySha256',method->>'reviewedEngineSha256','synthetic=true','complete=false','releaseEligible=false','assurance=none','synthetic_manual_confirmation','document_attachment_not_verification','overall_inventory_incomplete','january_2023_camx_only','market_based_scope2_not_included','factor_and_method_not_released','scope_1_and_scope_3_not_assessed','no_assurance'),'utf8')),'hex');
 body:=jsonb_build_object('id',new_id,'version',seq,'previousVersionId',predecessor.id,'companyLabel',request->>'companyLabel','facilityLabel',request->>'facilityLabel','quantityKwh',kwh,'quantityMwh',mwh,'period','2023-01','geography','CAMX','unit','kWh','correctionReason',reason,'inputSha256',input_hash,'resultSha256',result_hash,'createdBy',actor,'evidence',evidence,'method',method,'total',jsonb_build_object('unrounded',exact_total,'display',display_total,'unit','kg CO2e','rounding','half_even_4dp'));
 insert into neuvetra.source_worksheet_versions values(new_id,target_company,seq,predecessor.id,body,input_hash,result_hash,fingerprint,actor,captured);
 insert into neuvetra.source_worksheet_requests values(target_company,(request->>'idempotencyKey')::uuid,fingerprint,'save',new_id);
 insert into neuvetra.source_worksheet_audit values(gen_random_uuid(),target_company,new_id,'save',result_hash,actor,captured);
 return new_id;
end $function$

CREATE OR REPLACE FUNCTION neuvetra.save_stationary_diesel(target_company uuid, target_worksheet uuid, request jsonb, calculation jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare actor uuid:=auth.uid();head record;prior record;old record;coverage jsonb;a jsonb;statement jsonb:='null';statement_id uuid;statement_text text;statement_hash text;expected_calc jsonb;body jsonb;v jsonb;contributors jsonb;fingerprint text;input_hash text;content_hash text;version_hash text;frozen text;new_id uuid:=gen_random_uuid();captured timestamptz;meter text;ref text;begin
if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;
perform neuvetra.m76_diesel_validate_request(request);fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','save','actor',actor,'companyId',target_company,'worksheetId',target_worksheet,'request',request-'idempotencyKey'));
select * into old from neuvetra.stationary_diesel_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'save' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
coverage:=neuvetra.m76_diesel_coverage(target_company,request->'binding',true);a:=request-'expectedVersionId'-'expectedVersionSha256'-'correctionReason'-'idempotencyKey';
select * into head from neuvetra.stationary_diesel_heads where company_id=target_company and id=target_worksheet for update;
select * into prior from neuvetra.stationary_diesel_versions where company_id=target_company and id=head.version_id;
if target_worksheet is null then
if request->'expectedVersionId'<>'null' or exists(select 1 from neuvetra.stationary_diesel_heads where company_id=target_company and source_id=(a#>>'{binding,sourceId}')::uuid)then raise exception 'source stream exists' using errcode='23505';end if;
if(select count(*) from neuvetra.stationary_diesel_heads where company_id=target_company)>=1 then raise exception 'stream limit' using errcode='54000';end if;
insert into neuvetra.stationary_diesel_heads(id,company_id,source_id,asset_id) values(gen_random_uuid(),target_company,(a#>>'{binding,sourceId}')::uuid,a#>>'{equipment,assetId}') returning * into head;
else
if head.id is null then raise exception 'source identity conflict' using errcode='23505';end if;
select * into prior from neuvetra.stationary_diesel_versions where company_id=target_company and id=head.version_id;
if prior.id::text is distinct from request->>'expectedVersionId' or prior.version_sha256 is distinct from request->>'expectedVersionSha256' then raise exception 'stale source version' using errcode='23505';end if;
if prior.payload->'activity'=a then raise exception 'no-op correction' using errcode='23505';end if;end if;
if(select count(*) from neuvetra.stationary_diesel_versions where company_id=target_company)>=40 then raise exception 'version limit' using errcode='54000';end if;
if a->'statement'<>'null' then
statement_id:=gen_random_uuid();statement_text:=neuvetra.m76_diesel_statement(a,coverage);statement_hash:=encode(sha256(convert_to(statement_text,'utf8')),'hex');statement:=jsonb_build_object('id',statement_id,'profile','m76-synthetic-generator-statement-v1','input',a->'statement','locator','m76-diesel-statement:'||statement_id::text||':annual-activity','text',statement_text,'sha256',statement_hash,'byteLength',octet_length(convert_to(statement_text,'utf8')));
meter:=neuvetra.m67_hash(jsonb_build_array(lower(a#>>'{statement,issuer}'),lower(a#>>'{statement,meterLabel}'),'2025'));ref:=neuvetra.m67_hash(jsonb_build_array(lower(a#>>'{statement,issuer}'),lower(a#>>'{statement,reference}'),'2025'));
end if;
if meter is not null then
 if exists(select 1 from neuvetra.stationary_diesel_evidence_reservations where company_id=target_company and evidence_key in(meter,ref) and worksheet_id<>head.id) or exists(select 1 from neuvetra.mobile_diesel_evidence_reservations where company_id=target_company and evidence_key=ref and statement_kind='fuel') then raise exception 'consumed evidence conflict' using errcode='23505';end if;
 insert into neuvetra.stationary_diesel_evidence_reservations values(target_company,meter,head.id,'meter',clock_timestamp()) on conflict do nothing;
 insert into neuvetra.stationary_diesel_evidence_reservations values(target_company,ref,head.id,'reference',clock_timestamp()) on conflict do nothing;
 end if;
expected_calc:=neuvetra.m76_diesel_calculation(a,statement_hash);if calculation is distinct from expected_calc then raise exception 'calculation binding invalid' using errcode='22023';end if;
-- This update also enforces same company/meter/year and issuer/reference/year uniqueness.
update neuvetra.stationary_diesel_heads set meter_key=meter,reference_key=ref,source_id=(a#>>'{binding,sourceId}')::uuid,asset_id=a#>>'{equipment,assetId}' where id=head.id;
captured:=date_trunc('milliseconds',clock_timestamp());
select jsonb_agg(x order by x collate "C") into contributors from(select distinct x from(select jsonb_array_elements_text(coalesce(prior.payload->'contributorIds','[]'))x union all select jsonb_array_elements_text(coverage->'contributorIds') union all select actor::text)a)a;
input_hash:=neuvetra.m67_hash(a);body:=jsonb_build_object('activity',a,'activityStatus',neuvetra.m76_diesel_activity_status(a),'coverageVersion',coverage,'statement',statement,'calculation',calculation,'findings',neuvetra.m76_diesel_findings(a));content_hash:=neuvetra.m67_hash(body);
v:=jsonb_build_object('profile','synthetic-stationary-diesel-v1','id',new_id,'companyId',target_company,'worksheetId',head.id,'version',head.revision+1,'previousVersionId',prior.id,'previousVersionSha256',prior.version_sha256,'createdBy',actor,'createdAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'contributorIds',contributors,'correctionReason',request->'correctionReason','inputSha256',input_hash,'contentSha256',content_hash);version_hash:=neuvetra.m67_hash(v);
v:=(v-'profile')||body||jsonb_build_object('versionSha256',version_hash,'synthetic',true,'scope1Completeness','incomplete','corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','review',null);frozen:=neuvetra.m67_canonical(v);
if octet_length(convert_to(frozen,'utf8'))>102400 then raise exception 'version bytes limit' using errcode='54001';end if;perform neuvetra.m76_diesel_capacity(target_company,octet_length(convert_to(frozen,'utf8'))+4096);
if statement_id is not null then insert into neuvetra.stationary_diesel_statements values(statement_id,target_company,statement,statement_hash,statement_text);end if;
insert into neuvetra.stationary_diesel_versions values(new_id,target_company,head.id,head.revision+1,prior.id,(a#>>'{binding,coverageVersionId}')::uuid,statement_id,(a->>'quantityGallons')::numeric,v,input_hash,content_hash,version_hash,actor,captured,frozen);
insert into neuvetra.stationary_diesel_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'save',fingerprint,new_id);insert into neuvetra.stationary_diesel_audit values(gen_random_uuid(),target_company,new_id,'save',version_hash,actor,captured);
update neuvetra.stationary_diesel_heads set version_id=new_id,revision=revision+1 where id=head.id;return new_id;end $function$

CREATE OR REPLACE FUNCTION neuvetra.save_stationary_equipment(target_company uuid, target_roster uuid, request jsonb, version_payload jsonb, statement_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'neuvetra', 'pg_temp'
AS $function$declare actor uuid:=auth.uid();head neuvetra.stationary_equipment_heads%rowtype;prior neuvetra.stationary_equipment_versions%rowtype;old neuvetra.stationary_equipment_requests%rowtype;fingerprint text;statement_id uuid;captured timestamptz;deps jsonb;activity jsonb;content jsonb;contributors jsonb;expected_statement_text text;begin
 if not neuvetra.m76_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;
 if not neuvetra.m76_exact_keys(request,array['profile','coverageVersionId','coverageVersionSha256','expectedDependencySha256','period','rosterStatement','manualConfirmation','links','expectedVersionId','expectedVersionSha256','correctionReason','idempotencyKey']) or not neuvetra.m76_exact_keys(version_payload,array['id','companyId','rosterId','version','previousVersionId','previousVersionSha256','createdBy','createdAt','contributorIds','correctionReason','activity','dependencies','statement','findings','inputSha256','contentSha256','versionSha256','synthetic','scope1Completeness','corporateCompleteness','releaseEligible','assurance','emissionsTotals']) or request->>'profile' is distinct from 'synthetic-stationary-equipment-v1' or request->'period' is distinct from jsonb_build_object('start','2025-01-01','endExclusive','2026-01-01') or jsonb_typeof(request->'manualConfirmation') is distinct from 'boolean' or jsonb_typeof(request->'links') is distinct from 'array' or (request->'rosterStatement'<>'null'::jsonb and jsonb_typeof(request#>'{rosterStatement,assets}') is distinct from 'array') or jsonb_array_length(request->'links')>25 or coalesce(jsonb_array_length(request#>'{rosterStatement,assets}'),0)>25 or request->>'expectedDependencySha256'!~'^[0-9a-f]{64}$' or request->>'coverageVersionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or request->>'coverageVersionSha256'!~'^[0-9a-f]{64}$' or (request->'expectedVersionId'='null'::jsonb and (request->'expectedVersionSha256'<>'null'::jsonb or request->'correctionReason'<>'null'::jsonb)) or (request->'expectedVersionId'<>'null'::jsonb and (request->>'expectedVersionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or request->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or neuvetra.m76_text_valid(request->'correctionReason',500) is not true)) then raise exception 'invalid roster request' using errcode='22023';end if;
 deps:=neuvetra.m76_current_dependencies(target_company);activity:=request-array['expectedDependencySha256','expectedVersionId','expectedVersionSha256','correctionReason','idempotencyKey'];content:=jsonb_build_object('activity',version_payload->'activity','dependencies',version_payload->'dependencies','statement',version_payload->'statement','findings',version_payload->'findings');
 if jsonb_typeof(version_payload->'version') is distinct from 'number' or version_payload->>'version'!~'^[1-9][0-9]*$' or version_payload->>'id'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or version_payload->>'rosterId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or version_payload->>'companyId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or version_payload->>'createdBy'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or version_payload->>'createdAt'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z$' or jsonb_typeof(version_payload->'contributorIds') is distinct from 'array' or neuvetra.m76_activity_valid(activity) is not true or request->>'expectedDependencySha256' is distinct from deps->>'dependencySha256' or version_payload->'dependencies' is distinct from deps or version_payload->'activity' is distinct from activity or version_payload->>'inputSha256' is distinct from neuvetra.m67_hash(activity) or version_payload->>'contentSha256' is distinct from neuvetra.m67_hash(content) or version_payload->'synthetic' is distinct from 'true'::jsonb or version_payload->>'scope1Completeness' is distinct from 'incomplete' or version_payload->>'corporateCompleteness' is distinct from 'incomplete' or version_payload->'releaseEligible' is distinct from 'false'::jsonb or version_payload->>'assurance' is distinct from 'none' or version_payload->'emissionsTotals' is distinct from 'null'::jsonb or version_payload->'findings' is distinct from neuvetra.m76_roster_findings(activity,(select cv.payload from neuvetra.corporate_inventory_heads ch join neuvetra.corporate_inventory_versions cv on cv.company_id=ch.company_id and cv.id=ch.version_id where ch.company_id=target_company)) then raise exception 'invalid roster derivation' using errcode='22023';end if;
 if request->>'coverageVersionId' is distinct from deps#>>'{coveragePin,id}' or request->>'coverageVersionSha256' is distinct from deps#>>'{coveragePin,sha256}' then raise exception 'stale roster dependencies' using errcode='23505';end if;
